window.POEM_SHARD={"open_21000":["瑶华乐","李贺","古风","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["穆天子，走龙媒，八辔冬珑逐天回。","五精扫地凝云开，高门左右日月环。","四方错镂棱层殷，舞霞垂尾长盘珊。","江澄海净神母颜，施红点翠照虞泉。","曳云拖玉下崑山，列斾如松，张盖如轮。","金风殿秋，清明发春。","八銮十乘，矗如云屯。","琼锺瑶席甘露文，玄霜绦雪何足云，薰梅染柳将赠君。","铅华之水洗君骨，与君相对作真质。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21001":["北中寒","李贺","七言律诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["一方黑照三方紫，黄河冰合鱼龙死。","三尺木皮断文理，百石强车上河水。","霜花草上大如钱，挥刀不入迷蒙天。","争瀯海水飞凌喧，山瀑无声玉虹悬。"],"",[],{"source":"周啸天","body":["在全诗写景中，首句有确定基调的作用，也就是提纲挈领。以下各句，虽说没有明显的逻辑联系，然而除“三尺木皮断文理”外，都是写天地间水文变幻所构成的种种不同奇观，而这正是严寒统治的世界的特点。这些景观次第是：冰封的黄河及河上的行车、钱大的霜花、浓重的雾幔、浮冰充斥的海洋、冻结了的飞瀑等等，既源于真实，又糅合了诗人奇特的想象，从而把读者带进了一个奇异的冰雪世界，那里天是墨的、地是亮的，宛如一座神秘的水晶王国……你会感到寒冷，更会感到超出寒冷百倍的惊讶和愉快。这首诗，就像是李贺从他那古破锦囊中掏出些零金碎玉般的断句，随便凑合而成的。然而，它们一经组合，便天衣无缝了。","遣词设喻，于无理处得奇趣，是这首诗的另一个显著特点。如果我们拘泥于自然常识和语法常识，那么就会对《北中寒》的诗句逐一加以“订正”：黄河冰合时，应是鱼龙潜底。说“鱼龙死”，岂有此理？《汉书》谓“胡貉之地，阴积之处，木皮三寸”，不是“三尺”。是“百石重车”，不是“强车”；是“上河冰”，不是“上河水”。迷雾可说挥刀难破，不是“不入”。如此等等。然而所有这些无论从事理上还是措辞上对常规的违反，都包含着独创的匠心，都是出奇制胜。“鱼龙死”意味着河水全体冻结，注重表现异乎寻常的严寒，无理而有趣。“百石强车上河水”的“水”即是“冰”，但用“水”字则取得了一种令人惊异的效果。“抽刀断水水更流”虽更近乎常理，而“挥刀不入迷濛天”则别有神奇之感，可见那北国之雾异常的稠密。虹本有七彩，而“玉虹”的铸辞，更强调冻瀑的透明，而透明中亦能折射出不同的色光。凡此皆能给读者以十分新异的语感。"]},[],["https://github.com/chinese-poetry/chinese-poetry","《全唐诗》（清·曹寅等编，康熙扬州诗局本）"]],"open_21002":["梁台古愁","李贺","七言古诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["梁王台沼空中立，天河之水夜飞入。","台前鬬玉作蛟龙，绿粉扫天愁露湿。","撞钟饮酒行射天，金虎蹙裘喷血斑。","朝朝暮暮愁海翻，长绳系日乐当年。","芙蓉凝红得秋色，兰脸别春啼脉脉。","芦洲客雁报春来，寥落野篁秋漫白。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21003":["公无出门","李贺","古风","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["天迷迷，地密密。","熊虺食人魂，雪霜断人骨。","嗾犬狺狺相索索，舐掌偏宜佩兰客。","帝遣乘轩灾自息，玉星点劒黄金轭。","我虽跨马不得还，历阳湖波大如山。","毒虬相视振金环，狻猊猰貐吐嚵涎。","鲍焦一世披草眠，颜回廿九鬓毛斑。","颜回非血衰，鲍焦不违天。","天畏遭衔啮，所以致之然。","分明犹惧公不信，公看呵壁书问天。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21004":["神弦别曲","李贺","乐府","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["巫山小女隔云别，春风松花山上发。","绿盖独穿香径归，白马花竿前孑孑。","蜀江风澹水如罗，堕兰谁泛相经过。","南山桂树爲君死，云衫浅汚红脂花。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21005":["绿水词","李贺","五言律诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["今宵好风月，阿侯在何处。","爲有倾人色，翻成足愁苦。","东湖采莲叶，南湖拔蒲根。","未持寄小姑，且持感愁魂。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21006":["沙路曲","李贺","乐府","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["柳脸半眠丞相树，佩马钉铃踏沙路。","断烬遗香褭翠烟，烛骑啼乌上天去。","帝家玉龙开九关，帝前动笏移南山。","独垂重印押千官，金窠篆字红屈盘。","沙路归来闻好语，旱火不光天下雨。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21007":["上之回","李贺","古风","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["上之回，大旗喜。","悬红云，挞凤尾。","劒匣破，舞蛟龙。","蚩尤死，鼓逢逢。","天高庆雷齐坠地，地无惊烟海千里。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21008":["高轩过","李贺","古风","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["华裾织翠青如葱，金环压辔摇玲珑。","马蹄隐耳声隆隆，入门下马气如虹。","云是东京才子，文章钜公。","二十八宿罗心胸，九精照耀贯当中。","殿前作赋声摩空，笔补造化天无功。","庞眉书客感秋蓬，谁知死草生华风。","我今垂翅附冥鸿，他日不羞蛇作龙。"],"九精照耀一作元精耿耿",[["古评·《唐诗镜》","九精照耀一作元精耿耿"],["古评·《诗人玉屑》","李贺年七岁，以长短之制，名动京华。时韩文公与皇甫湜览贺所作，奇之，因联骑造门求见。贺总角荷衣而出，二公不之信，因令面赋一篇。贺承命，欣然操觚染翰，旁若无人，仍名曰高轩过。云：二公大惊，遂以所乘马，命联镳而还所居，亲为束发。後举进士。贺父名瑨，或谤贺不避家讳，韩文公特为着辨讳一篇"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）","古籍注评：《诗人玉屑》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/詩人玉屑_(四庫全書本)）"]],"open_21009":["贝宫夫人","李贺","七言律诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["丁丁海女弄金环，雀钗翘揭双翅关。","六宫不语一生闲，高悬银牓照青山。","长眉凝绿几千年，清凉堪老镜中鸾。","秋肌稍觉玉衣寒，空光帖妥水如天。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21010":["兰香神女庙","李贺","五言古诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["古春年年在，闲绿摇暖云。","松香飞晚华，柳渚含日昏。","沙砌落红满，石泉生水芹。","幽篁画新粉，蛾绿横晓门。","弱蕙不胜露，山秀愁空春。","舞佩剪鸾翼，帐带涂轻银。","兰桂吹浓香，菱藕长莘莘。","看雨逢瑶姬，乘船值江君。","吹箫饮酒醉，结绶金丝裙。","走天呵白鹿，游水鞭锦鳞。","密发虚鬟飞，腻颊凝花匀。","团鬓分蛛巢，穠眉笼小唇。","弄蝶和轻妍，风光怯腰身。","深帏金鸭冷，奁镜幽凤尘。","踏雾乘风归，撼玉山上闻。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21011":["送韦仁实兄弟入关","李贺","五言古诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["送客饮别酒，千觞无赭颜。","何物最伤心，马首鸣金鐶。","野色浩无主，秋明空旷间。","坐来壮胆破，断目不能看。","行槐引西道，青梢长攒攒。","韦郎好兄弟，叠玉生文翰。","我在山上舍，一亩蒿硗田。","夜雨呌租吏，春声暗交关。","谁解念劳劳，苍突唯南山。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21012":["洛阳城外别皇甫湜","李贺","五言律诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["洛阳吹别风，龙门起断烟。","冬树束生涩，晚紫凝华天。","单身野霜上，疲马飞蓬间。","凭轩一双泪，奉坠绿衣前。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21013":["溪晚凉","李贺","七言律诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["白狐向月号山风，秋寒扫云留碧空。","玉烟青湿白如幢，银湾晓转流天东。","溪汀眠鹭梦征鸿，轻涟不语细游溶。","层岫回岑复叠龙，苦篁对客吟歌筒。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21014":["官不来题皇甫湜先辈厅","李贺","古风","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["官不来，官庭秋，老桐错干青龙愁。","书司曹佐走如牛，叠声问佐官来不。","官不来，门幽幽。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21015":["长平箭头歌","李贺","乐府","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["漆灰骨末丹水沙，凄凄古血生铜花。","白翎金簳雨中尽，直余三脊残狼牙。","我寻平原乘两马，驿东石田蒿坞下。","风长日短星萧萧，黑旗云湿悬空夜。","左魂右魄啼肌瘦，酪瓶倒尽将羊炙。","虫栖雁病芦笋红，回风送客吹阴火。","访古丸澜收断镞，折锋赤璺曾刲肉。","南陌东城马上儿，劝我将金换簝竹。"],"折锋赤璺曾刲肉佳句",[["古评·《唐诗镜》","折锋赤璺曾刲肉佳句"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）"]],"open_21016":["江楼曲","李贺","乐府","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["楼前流水江陵道，鲤鱼风起芙蓉老。","晓钗催鬓语南风，抽帆归来一日功。","鼍吟浦口飞梅雨，竿头酒旗换青苎。","萧骚浪白云差池，黄粉油衫寄郎主。","新槽酒声苦无力，南湖一顷菱花白。","眼前便有千里愁，小玉开屏见山色。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21017":["塞下曲","李贺","乐府","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["胡角引北风，蓟门白於水。","天含青海道，城头月千里。","露下旗蒙蒙，寒金鸣夜刻。","蕃甲鏁蛇鳞，马嘶青塚白。","秋静见旄头，沙远席羁愁。","帐北天应尽，河声出塞流。"],"",[["古评·《唐诗品汇》","刘云悲壮卓絶"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）"]],"open_21018":["染丝上春机","李贺","七言律诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["玉罂泣水桐花井，蒨丝沈水如云影。","美人嬾态燕脂愁，春梭抛掷鸣高楼。","彩线结茸背复叠，白袷玉郎寄桃叶。","爲君挑鸾作腰绶，愿君处处宜春酒。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21019":["五粒小松歌","李贺","乐府","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["蛇子蛇孙鳞蜿蜿，新香几粒洪厓饭。","绿波浸叶满浓光，细束龙髯铰刀剪。","主人壁上铺州图，主人堂前多俗儒。","月明白露秋泪滴，石笋溪云肯寄书。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21020":["塘上行","李贺","乐府","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["藕花凉露湿，花缺藕根涩。","飞下雌鸳鸯，塘水声溘溘。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21021":["吕将军歌","李贺","乐府","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["吕将军，骑赤兔。","独携大胆出秦门，金粟堆边哭陵树。","北方逆气污青天，劒龙夜呌将军闲。","将军振袖挥劒锷，玉阙朱城有门阁。","榼榼银龟摇白马，傅粉女郎火旗下。","恒山铁骑请金枪，遥闻箙中花箭香。","西郊寒蓬叶如刺，皇天新栽养神骥。","廐中高桁排蹇蹄，饱食青刍饮白水。","圆苍低迷盖张地，九州人事皆如此。","赤山秀铤御时英，绿眼将军会天意。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21022":["休洗红","李贺","杂言古诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["休洗红，洗多红色浅。","卿卿骋少年，昨日殷桥见。","封侯早归来，莫作弦上箭。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21023":["神弦曲","李贺","乐府","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["西山日没东山昏，旋风吹马马踏云。","画弦素管声浅繁，花裙綷䌨步秋尘。","桂叶刷风桂坠子，青狸哭血寒狐死。","古壁彩虬金帖尾，雨工骑入秋潭水。","百年老鴞成木魅，笑声碧火巢中起。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21024":["野歌","李贺","乐府","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["鵶翎羽箭山桑弓，仰天射落衔芦鸿。","麻衣黑肥冲北风，带酒日晚歌田中。","男儿屈穷心不穷，枯荣不等嗔天公。","寒风又变爲春柳，条条看即烟蒙蒙。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21025":["神弦","李贺","七言古诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["女巫浇酒云满空，玉炉炭火香冬冬。","海神山鬼来座中，纸钱窸窣鸣𩘶风","相思木帖金舞鸾，攒蛾一啑重一弹。","呼星召鬼歆杯盘，山魅食时人森寒。","终南日色低平湾，神兮长在有无间。","神嗔神喜师更颜，送神万骑还青山。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21026":["将进酒","李贺","古风","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["琉璃锺，琥珀浓，小槽酒滴真珠红。","烹龙炮凤玉脂泣，罗屏绣幕围香风。","吹龙笛，击鼍鼓，皓齿歌，细腰舞。","况是青春日将暮，桃花乱落如红雨。","劝君终日酩酊醉，酒不到刘伶坟上土。"],"",[],{"source":"周啸天","body":["以下四个三字句写宴上歌舞音乐，在遣词造境上更加奇妙。吹笛就吹笛，偏作“吹龙笛”，形象地状出笛声之悠扬有如瑞龙长吟——乃非人世间的音乐；击鼓就击鼓，偏作“击鼍鼓”，盖鼍皮坚厚可蒙鼓，着一“鼍”字，则鼓声洪亮如闻。继而，将歌女唱歌写作“皓齿歌”，也许受到“谁为发皓齿”（三国魏曹植《杂诗》）句的启发，但效果大不同，曹诗“皓齿”只是“皓齿”，而此句“皓齿”借代佳人，又使人由形体美见歌声美，或者说将听觉美通转为视觉美。将舞女起舞写作“细腰舞”，“细腰”同样代美人，又能具体生动显示出人体的曲线美，一举两得。“皓齿”“细腰”各与歌唱、舞蹈特征相关，用来均有形象暗示功用，能化陈辞为新语。仅十二字，就将音乐歌舞之美妙写得尽态极妍。","“行乐须及春”（李白《月下独酌》），如果说前面写的是行乐，下两句则意味“须及春”。铸词造境愈出愈奇：“桃花乱落如红雨”，这是用形象的语言说明“青春将暮”，生命没有给人们多少欢乐的日子，须要及时行乐。在桃花之落与雨落这两种很不相同的景象中达成联想，从而创出红雨乱落这样一种比任何写风雨送春之句更新奇、更为惊心动魄的境界，这是需要多么活跃的想象力和多么敏捷的表现力，想象与联想活跃到匪夷所思的程度，正是李贺形象思维的一个最大特色。他如“黑云压城城欲摧”（《雁门太守行》）、“银浦流云学水声”（《天上谣》）、“羲和敲日玻璃声”（《秦王饮酒》）等等例子不胜枚举。真是“时花美女，不足为其色也；牛鬼蛇神，不足为其虚荒诞幻也”（杜牧《李长吉歌诗叙》）。","由于诗人称引精美名物，运用华艳辞藻，同时又综合运用多种修辞手法，使诗歌具有了色彩、线条等绘画形式美。","诗中写宴席的诗句，也许使人想到前人名句如“葡萄美酒夜光杯，欲饮琵琶马上催”（王翰《凉州词》），“兰陵美酒郁金香，玉碗盛来琥珀光”（李白《客中作》），“紫驼之峰出翠釜，水晶之盘行素鳞。犀箸厌饫久未下，鸾刀缕切空纷纶”（杜甫《丽人行》），相互比较一下，能更好认识李贺的特点。它们虽然都在称引精美名物，但李贺“不屑作经人道过语”（清王琦《李长吉歌诗汇解序》），他不用“琥珀光”形容“兰陵美酒”——如李白所作那样，而用“琥珀浓”取代“美酒”一词，自有独到面目。更重要的区别还在于，名物与名物间，绝少“欲饮”“盛来”“厌饫久未下”等等叙写语言，只是在空间内把物象一一感性呈现（即不作理性说明）。然而，“琉璃锺，琥珀浓，小槽酒滴真珠红”，诸物象并不给人脱节的感觉，而自有“盛来”“欲饮”“厌饫”之意，即能形成一个宴乐的场面。","这手法与电影“蒙太奇”（镜头剪辑）语言相类。电影不能靠话语叙述，而是通过一些基本视像、具体画面、镜头的衔接来“造句谋篇”。虽纯是感性显现，而画面与画面间又有内在逻辑联系。如前举诗句，杯、酒、滴酒的槽床……相继出现，就给人酒宴进行着的意念。","省略叙写语言，不但大大增加形象的密度，同时也能启迪读者活跃的联想，使之能动地去填补、丰富那物象之间的空白。","此诗前一部分是大段关于人间乐事的瑰丽夸大的描写，结尾二句猛作翻转，出现了死的意念和“坟上土”的惨淡形象。前后似不协调而正具有机联系。前段以人间乐事极力反衬死的可悲，后段以终日醉酒和暮春之愁思又回过来表露了生的无聊，这样，就十分生动而真实地将诗人内心深处所隐藏的死既可悲而生亦无聊的最大的矛盾和苦闷揭示出来了。总之，这个乐极生悲、龙身蛇尾式的奇突结构，有力表现了诗歌的主题。这又表现了李贺艺术构思上不落窠臼的特点。"]},[],["https://github.com/chinese-poetry/chinese-poetry","《全唐诗》（清·曹寅等编，康熙扬州诗局本）"]],"open_21027":["美人梳头歌","李贺","乐府","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["西施晓梦绡帐寒，香鬟堕髻半沈檀。","辘轳咿哑转鸣玉，惊起芙蓉睡新足。","双鸾开镜秋水光，解鬟临镜立象牀。","一编香丝云撒地，玉钗落处无声腻。","纤手却盘老鵶色，翠滑宝钗簪不得。","春风烂熳恼娇慵，十八鬟多无气力。","妆成𩭏鬌敧不斜，云裾数步踏雁沙","背人不语向何处，下堦自折樱桃花。"],"玉钗落处无声腻衬贴形容得佳结语有致",[["古评·《唐诗镜》","玉钗落处无声腻衬贴形容得佳结语有致"]],{"source":"郭扬波","body":["第一个场景是“云鬓半偏新睡觉”（白居易《长恨歌》），写美人起床后慵懒的姿态。西施代指所写美人。天色已明，而她沉醉于梦乡之中。“寒”字除标明节令是早春外，还暗示她是独宿，更增孤寂之感。“香鬟”句写到头发，是为下文的梳头作铺垫。睡了一夜，美人的鬟髻松散，一个“半”字写出欲坠未坠之态，犹如水中的檀香木，散发阵阵清香。这时传来咿咿哑哑的辘轳声，原来是有人开始干活，从井中汲水。美人便被这辘辘声从梦中惊醒。白居易《长恨歌》有“芙蓉如面柳如眉”之句，这里是以之代指美人，也是对其容貌的夸赞。","第二个场景则是中间八句对梳头场景的细致描摹。“双鸾开镜”之语别出心裁，仿佛是镜盖上所绘凤凰开启了镜盖，作者丰富的想象力可见一斑；镜面如秋水一般明净光洁。尽管她站立在象床上，那满头青丝仍然垂至地面，且如云撒地。随着解开的发丝落下地面的还有玉钗，因为头发滑润，玉钗顺着长发上滑落下来几乎是悄无声响的。这里以“立象床”状头发之长，以“一编香丝云撒地”状头发之多，以玉钗滑落无声状头发之柔滑，皆是夸张，生动形象、细致精妙。","对梳妆所用镜子和欲梳之长发做了充分渲染后，“梳头”这一中心场景这才千呼万唤始出来。南朝乐府《西洲曲》有“双鬟鸦雏色”之句，这里用老鸦色代指头发。美人开始动手梳理，把乌黑的长发盘结起来，头发像翠鸟的羽毛一样光滑以至于宝钗都插不住。由于梳得匀，盘得实，映着光线，如同碧丝一般，滑腻得连宝钗也插不稳。后两句写美人发长髻多，梳理整齐花了不小的工夫，显得娇而无力，虽有春风烂漫却心生懊恼，字面看是因鬟多费力而嗔怪，其实亦是因独处无人共沐春风而恼。女子的娇弱亦是一种美，再加上娇嗔，就更具风韵。","最后一个场景是写梳理完毕后的绰约身姿。鬌是一种优美的发式，秀美大方。接着描述她头发梳成后如何曳动云裾，缓步下台阶。“云裾”，状美人之罗裙随风飘动；“踏雁沙”是比喻，形容其步履所至，如雁足踏沙上，显得行步匀缓。最后两句则通过描述美人的动作向读者透露了她幽幽的心事。她转身默默走向庭院，是做什么呢？原来是去采折缤纷如雪的樱桃花，伤春惜春之中也许更加思念离人。","梳头本是凡常之事，但经李贺这般新颖的创作，便使一位慵懒美丽又幽怨的女子形象如画般鲜明，看似艳词，但不失风雅。关于这首诗的主题，历来看法不一，并无定论。有的学者认为是写普通的“幽闺春怨”，有的学者认为是诗人咏新婚妻子之作，也有学者认为是以其姐姐为原型所做的虚构。从本诗对美人梳头情状描绘得如此细致生动来看，完全处于虚构是不太可能，但究竟是否是写自己的妻子却难以根据现有的资料来下结论。不过，这一不确定并不影响我们对此诗的欣赏。"]},[],["https://github.com/chinese-poetry/chinese-poetry","《全唐诗》（清·曹寅等编，康熙扬州诗局本）","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）"]],"open_21028":["月漉漉篇","李贺","乐府","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["月漉漉，波烟玉。","莎青桂花繁，芙蓉别江木。","粉态裌罗寒，雁羽铺烟湿。","谁能看石帆，乘船镜中入。","秋白鲜红死，水香莲子齐。","挽菱隔歌袖，绿刺罥银泥。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21029":["京城","李贺","五言绝句","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["驱马出门意，牢落长安心。","两事谁向道，自作秋风吟。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21030":["官街鼓","李贺","七言古诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["晓声隆隆催转日，暮声隆隆呼月出。","汉城黄柳暎新帘，柏陵飞燕埋香骨。","磓发千年日长白，孝武秦王听不得。","从君翠发芦花色，独共南山守中国。","几回天上葬神仙，漏声相将无断缘。"],"唐书马周传云先是京师晨昬传呼警衆後置鼔伐之呼冬鼔周所奏也",[["古评·《唐诗品汇》","唐书马周传云先是京师晨昬传呼警衆後置鼔伐之呼冬鼔周所奏也"]],{"source":"周啸天","body":["诗开始就描绘出一幅离奇的画面：日月跳丸，循环不已；画外传来咚咚不绝的鼓声。这样的描述，既夸张，又富于奇特的想象。一、二句描述鼓声，展示了日月不停运转的惊人图景；三、四句转入人间图景的描绘：宫墙内，春天的柳枝刚由枯转荣，吐出鹅黄的嫩芽，宫中却传出美人死去的消息。这样，官街鼓给读者的印象就十分惊心动魄了。它正是“月寒日暖煎人寿”的“飞光”的形象的体现。第五、六句用对比手法再写鼓声：千年人事灰飞烟灭，就像是被鼓点“捶碎”，而“日长白”——宇宙却永恒存在。可秦皇汉武再也听不到鼓声了，与永恒的时光比较，他们的生命多么短促可悲！这里专提“孝武（即汉武帝）秦皇”，是因为这两位皇帝都曾追求长生，然而他们未遂心愿，不免在鼓声中消灭。值得玩味的是，官街鼓乃唐制，本不关秦汉，“孝武秦皇”当然“听不得”，而诗中却把鼓声写得自古已有之，而且永不消逝，秦皇汉武一度听过，只是眼前不能再听。可见诗人的用心，并非在讴咏官街鼓本身，而是着眼于这个艺术形象所象征的事物——那永恒的时光、不停的逝川。","七、八两句分咏人生和官街鼓，再一次对比：尽管你“高堂明镜悲白发，朝如青丝暮成雪”（李白《将进酒》），日趋衰老；然而官街鼓永远不老，只有它“独共南山守中国”。这两句因省略较多，曾引起纷歧的解说。但仔细玩味，它们是分咏两个对立面。“君”字乃泛指世人，可以包含“孝武秦皇”，却未必专指二帝。通过两次对比，进一步突出了人生有限与时间无限的矛盾之不可克服。诗写到这里，意思似乎已表达得淋漓尽致了。但诗人并没有就此搁笔，最后两句突发异想道：天上的神仙也不免一死，不死的只有官街鼓。它的鼓声与漏声相继不断万古长存。这里仍用对比，却不再用人生与鼓声比，而以神仙与鼓声比：天上神仙已死去几回而隆隆鼓声却始终如一，连世人希羡的神仙寿命与鼓声比较也是这样短促可悲，那么人生的短促就更不在话下了。","《官街鼓》反复地、淋漓尽致地刻画和渲染生命有涯、时光无限的矛盾，有人认为意在批判神仙之说。这评价是很不够的。从李贺生平及其全部诗歌看，他慨叹人生短促、时光易逝，其中应含有“志士惜日短”的成分。他怀才不遇，眼看生命虚掷，不免对此特别敏感，特别痛心。此诗艺术上的一个显著特色是，通过异常活跃的想象，把抽象的时间和报时的鼓点发生联想，巧妙地创造出“官街鼓”这样一个象征的艺术形象。赋无形以有形，化无声为有声，抽象的概念转化为可感的形象，让读者通过形象的画面，在强烈的审美活动中深深体味到诗人的思想活动。"]},[],["https://github.com/chinese-poetry/chinese-poetry","《全唐诗》（清·曹寅等编，康熙扬州诗局本）","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）"]],"open_21031":["许公子郑姬歌","李贺","乐府","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["许史世家外亲贵，宫锦千端买沈醉。","铜驼酒熟烘明胶，古堤大柳烟中翠。","桂开客花名郑袖，入洛闻香鼎门口。","先将芍药献妆台，後解黄金大如斗。","莫愁帘中许合欢，清弦五十爲君弹。","弹声咽春弄君骨，骨兴牵人马上鞍。","两马八蹄踏兰苑，情如合竹谁能见。","夜光玉枕栖凤皇，袷罗当门刺纯綫。","长翻蜀纸卷明君，转角含商破碧云。","自从小靥来东道，曲里长眉少见人。","相如塚上生秋柏，三秦谁是言情客。","蛾鬟醉眼拜诸宗，爲谒皇孙请曹植。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21032":["新夏歌","李贺","乐府","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["晓木千笼真蜡彩，落蕊枯香数分在。","阴枝秀牙卷缥茸，长风回气扶葱茏。","野家麦畦上新壠，长畛裴回桑柘重。","刺香满地菖蒲草，雨梁燕语悲身老。","三月摇扬入河道，天浓地浓柳梳扫。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21033":["题归梦","李贺","五言律诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["长安风雨夜，书客梦昌谷。","怡怡中堂笑，小弟栽涧菉。","家门厚重意，望我饱饥腹。","劳劳一寸心，灯花照鱼目。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21034":["经沙苑","李贺","五言律诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["野水泛长澜，宫牙开小蒨。","无人柳自春，草渚鸳鸯暖。","晴嘶卧沙马，老去悲啼展。","今春还不归，塞嘤折翅雁。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21035":["出城别张又新酬李汉","李贺","五言古诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["李子别上国，南山崆峒春。","不闻今夕鼓，差慰煎情人。","赵壹赋命薄，马卿家业贫。","乡书何所报，紫蕨生石云。","长安玉桂国，戟带披侯门。","惨阴地自光，宝马踏晓昏。","腊春戏草苑，玉挽鸣𨏈辚","绿网缒金铃，霞卷清池漘。","开贯泻蚨母，买冰防夏蝇。","时宜裂大袂，劒客车盘茵。","小人如死灰，心切生秋榛。","皇图跨四海，百姓拖长绅。","光明霭不发，腰龟徒甃银。","吾将噪礼乐，声调摩清新。","欲使十千岁，帝道如飞神。","华实自苍老，流采长倾湓。","没没暗齰舌，涕血不敢论。","今将下东道，祭酒而别秦。","六郡无剿儿，长刀谁拭尘。","地理阳无正，快马逐服辕。","二子美年少，调道讲清浑。","讥笑断冬夜，家庭疎筱穿。","曙风起四方，秋月当东悬。","赋诗面投掷，悲哉不遇人。","此别定沾臆，越布先裁巾。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21036":["南园","李贺","七言律诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["方领蕙带折角巾，杜若已老兰苕春。","南山削秀蓝玉合，小雨归去飞凉云。","熟杏暖香梨叶老，草梢竹栅锁池痕。","郑公乡老开酒尊，坐泛楚奏吟招魂。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21037":["假龙吟歌","李贺","乐府","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["石轧铜杯，吟咏枯瘁。","苍鹰摆血，白凤下肺。","桂子自落，云弄车盖。","木死沙崩恶谿岛，阿母得仙今不老。","窞中跳汰截清涎，隈壖卧水埋金爪。","崖蹬苍苔吊石发，江君掩帐篔簹折。","莲花去国一千年，雨後闻腥犹带铁。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21038":["感讽六首 一","李贺","五言古诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["人间春荡荡，帐暖香扬扬。","飞光染幽红，夸娇来洞房。","舞席泥金蛇，桐竹罗花牀。","眼逐春瞑醉，粉随泪色黄。","王子下马来，曲沼鸣鸳鸯。","焉知肠车转，一夕巡九方。"],"",[],{"source":"周啸天","body":["李贺有一种境界幽冷荒诞的诗，它们常常为人引以说明李贺诗的某种特点，却又因为情调的“消极”，为选家所摒弃。连司空图的二十四“诗品”也没有“荒诞”一品，不免小有遗憾。而这类“荒诞”的诗，实蕴涵诗人李贺的苦心孤诣，是后世称之为“诗鬼”的主要原因，在美学风格上也有独到的贡献。列在《感讽》这一题下的“南山何其悲”，便是这样的呕心沥血之作。诗中塑造的阴森恐怖的境界，是诗人内心苦闷的深刻的象征。我国古代通行土葬，城市近郊的山陵往往为市朝之公墓，如洛阳的北邙与长安的终南山，都有松柏丛生的陵园。此诗写的就是深秋夜半南山墓地的情景。南山是坟地，故空寂无人，雨天尤其萧瑟。“鬼雨”的铸辞由此而来，非常警策。而“空草”的铸辞也非常别致。因为秋能兴悲，愁能杀人，尤其在远离市井的南山，打在空寂的草木上的秋雨，真个别有阴冷的鬼气。“鬼”字遥兴篇末的冥境（今人口语中的“鬼天气”“鬼话”等等含有诅咒的意味，即由此延伸而出）。以下一跳写到长安，那是繁华的人境。然而人皆有死，终须托体山阿。联系到开篇，“长安夜半秋，风前几人老”二句只平平道来也有些惊心动魄了。由青春年少而至于衰老，本是自然规律，何关乎秋风秋雨？然而秋风秋雨使人忧伤，忧伤足以加速人的衰老，而衰老则将导致人的死亡啊。“低迷黄昏径，袅袅青栎道”两句是三重意义上的过渡：就地域言，是从长安到南山的过渡；就气候言，是从风雨到雨霁的过渡；就生命言，是从人境到冥界的过渡。这个过渡通过山林的道径描述而完成，很有别趣。曲折的路径笼罩在昏暗之中，两旁是沙沙响着的青栎，谁走在这样的路上也不免心中犯疑，乃至毛骨惊然。沿着这条幽暗之路，最后通到了一片白晃晃的世界。后四句中读者看到了一个安静得可怕的午夜世界。诗人用战栗着的想象，描绘了一个神秘的比黑夜更为可怕的白夜：“月午树立影，一山唯白晓。漆炬迎新人，幽圹萤扰扰。”寂静的山林，月到中天，树影缩成一团，消失在树脚，于是到处明晃晃的，有甚于天亮的时候。这时磷火（漆炬）如烛光点点；鬼影幢幢，似乎是在迎接新来的伙伴，坟茔中乱糟糟萤火般的磷光，使人想到鬼的聚会！这想象，是幻觉，却又那么逼真。铸辞用字的倒错和异常，产生了令人惊愕不已的效果：“月午”对应着人间的日午，“白晓”其实出现在深夜，鬼灯发着幽昧的光，故曰“漆炬”，“新人”其实是新鬼……阴错阳差的语言有力地刻画出一个本不存在的冥界。在古诗或乐府中，“新人”还特指新妇（如《焦仲卿妻》“不足迎新人”，《上山采蘼芜》“新人不如故”，杜甫《佳人》“但闻新人笑”），从李贺《苏小小墓》看，他是认定鬼也能恋爱婚嫁的。所以“漆炬迎新人”二句，未尝不可解为鬼的迎娶，正是“冷翠烛（即漆炬），劳光彩”（《苏小小墓》）呢。“幽圹萤扰扰”则应是鬼的喜庆热闹的婚筵场面了，这也是诗中的别趣。据说天才的诗人在创作时都有些精神失常或失态。作为一位有些神经质的诗人，李贺更是如此。他在悲哀苦闷时想到死后，却又把幻想作为审美观照的对象加以玩味，不由自主地又给它添上一点点生趣，虚荒诞幻中仍有着天真烂漫的所在。读者为之既错愕又神往。诗列在“感讽”题下，显然想要告诫世人什么，又终于没有说出。然而他却创造了一个独到的艺术境界，借以表现了一种生之困惑。杜牧说“荒国陊殿，梗莽丘垄，不足为其怨恨悲愁也；鲸吸鳌掷，牛鬼蛇神，不足为其虚荒诞幻也”（《李长吉歌诗序》），于此诗可见一斑。"]},[],["https://github.com/chinese-poetry/chinese-poetry","《全唐诗》（清·曹寅等编，康熙扬州诗局本）"]],"open_21039":["感讽六首 二","李贺","五言律诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["苦风吹朔寒，沙惊秦木折。","舞影逐空天，画鼓余清节。","蜀书秋信断，黑水朝波咽。","娇魂从回风，死处悬乡月。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21040":["感讽六首 三","李贺","五言古诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["杂杂胡马尘，森森边士戟。","天教胡马战，晓云皆血色。","妇人携汉卒，箭箙囊巾帼。","不慙金印重，踉蹡腰鞬力。","恂恂乡门老，昨夜试锋镝。","走马遣书勳，谁能分粉墨。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21041":["感讽六首 四","李贺","五言古诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["青门放弹去，马色连空郊。","何年帝家物，玉装鞍上摇。","去去走犬归，来来坐烹羔。","千金不了馔，狢肉称盘臊。","试问谁家子，乃老能佩刀。","西山白盖下，贤儁寒萧萧。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21042":["感讽六首 五","李贺","五言律诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["晓菊泫寒露，似悲团扇风。","秋凉经汉殿，班子泣衰红。","本无辞辇意，岂见入空宫。","腰衱佩珠断，灰蝶生阴松。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21043":["感讽六首 六","李贺","五言古诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["蝶飞红粉台，柳扫吹笙道。","十日悬户庭，九秋无衰草。","调歌送风转，杯池白鱼小。","水宴截香腴，菱科映青罩。","䒠蒙梨花满，春昏弄长啸。","唯愁苦花落，不悟世衰到。","抚旧唯销魂，南山坐悲峭。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21044":["莫愁曲","李贺","乐府","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["草生龙坡下，鵶噪城堞头。","何人此城里，城角栽石榴。","青丝系五马，黄金络双牛。","白鱼驾莲船，夜作十里游。","归来无人识，暗上沈香楼。","罗牀倚瑶瑟，残月倾帘钩。","今日槿花落，明朝桐树秋。","莫负平生意，何名何莫愁。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21045":["夜来乐","李贺","古风","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["红罗复帐金流苏，华灯九枝悬鲤鱼。","丽人暎月开铜铺，春水滴酒猩猩沽。","重一箧，香十株，赤金瓜子兼杂麸。","五丝封青凫，阿侯此笑千万余。","南轩汉转帘影疎，桐林哑哑挟子乌。","劒崖鞭节青石珠，白騧吹湍凝霜须。","漏长送佩承明庐，倡楼嵯峨明月孤。","新客下马故客去，绿蝉秀黛重拂梳。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21046":["嘲雪","李贺","五言律诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["昨日发葱岭，今朝下兰渚。","喜从千里来，乱笑含春语。","龙沙湿汉旗，凤扇迎秦素。","久别辽城鹤，毛衣已应故。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21047":["春怀引","李贺","乐府","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["芳蹊密影成花洞，柳结浓烟花带重。","蟾蜍碾玉挂明弓，扞拨装金打仙凤。","宝枕垂云选春梦，钿合碧寒龙脑冻。","阿侯系锦觅周郎，凭仗东风好相送。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21048":["白虎行","李贺","乐府","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["火乌日暗崩腾云，秦皇虎视苍生羣。","烧书灭国无暇日，铸劒佩玦惟将军。","玉坛设醮思冲天，一世二世当万年。","烧丹未得不死药，拏舟海上寻神仙。","鲸鱼张鬣海波沸，耕人半作征人鬼。","雄豪气猛如焰烟，无人爲决天河水。","谁最苦兮谁最苦，报人义士深相许。","渐离击筑荆卿歌，荆卿把酒燕丹语。","劒如霜兮胆如铁，出燕城兮望秦月。","天授秦封祚未移，衮龙衣点荆卿血。","朱旗卓地白虎死，汉皇知是真天子。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21049":["有所思","李贺","杂言古诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["去年陌上歌离曲，今日君书远游蜀。","帘外花开二月风，台前泪滴千行竹。","琴心与妾肠，此夜断还续。","想君白马悬雕弓，世间何处无春风。","君心未肯镇如石，妾颜不久如花红。","夜残高碧横长河，河上无梁空白波。","西风未起悲龙梭，年年织素攒双蛾。","江山迢遰无休绝，泪眼看灯乍明灭。","自从孤馆深锁窗，桂花几度圆还缺。","鵶鵶向晓鸣森木，风过池塘响丛玉。","白日萧条梦不成，桥南更问仙人卜。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21050":["啁少年","李贺","七言古诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["青騘马肥金鞍光，龙脑入缕罗衫香。","美人狭坐飞琼觞，贫人唤云天上郎。","别起高楼临碧筱，丝曳红鳞出深沼。","有时半醉百花前，背把金丸落飞鸟。","自说生来未爲客，一身美妾过三百。","岂知斸地种苗家，官税频催勿人织。","长得积玉夸豪毅，每揖闲人多意气。","生来不读半行书，只把黄金买身贵。","少年安得长少年，海波尚变爲桑田。","荣枯递传急如箭，天公不肯於公偏。","莫道韶华镇长在，发白面皱专相待。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21051":["高平县东私路","李贺","五言律诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["侵侵槲叶香，木花滞寒雨。","今夕山上秋，永谢无人处。","石磎远荒涩，棠实悬辛苦。","古者定幽寻，呼君作私路。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21052":["神仙曲","李贺","乐府","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["碧峰海面藏灵书，上帝拣作神仙居。","清明笑语闻空虚，鬬乘巨浪骑鲸鱼。","春罗书字邀王母，共讌红楼最深处。","鹤羽冲风过海迟，不如却使青龙去。","犹疑王母不相许，垂露娃鬟更传语。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21053":["龙夜吟","李贺","乐府","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["鬈发胡儿眼睛绿，高楼夜静吹横竹。","一声似向天上来，月下美人望乡哭。","直排七点星藏指，暗合清风调宫徵。","蜀道秋深云满林，湘江半夜龙惊起。","玉堂美人边塞情，碧窗皓月愁中听。","寒碪能捣百尺练，粉泪凝珠滴红线。","胡儿莫作陇头吟，隔窗暗结愁人心。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21054":["崑仑使者","李贺","七言律诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["崑仑使者无消息，茂陵烟树生愁色。","金盘玉露自淋漓，元气茫茫收不得。","麒麟背上石文裂，虬龙鳞下红枝折。","何处偏伤万国心，中天夜久高明月。"],"",[["古评·《唐诗品汇》","刘云甚有风刺"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗品彚（附唐诗拾遗）》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩品彚_(四庫全書本)）"]],"open_21055":["汉唐姬饮酒歌","李贺","乐府","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["御服沾霜露，天衢长蓁棘。","金隐秋尘姿，无人爲带饰。","玉堂歌声寝，芳林烟树隔。","云阳台上歌，鬼哭复何益。","铁劒常光光，至凶威屡逼。","强枭噬母心，犇厉索人魄。","相看两相泣，泪下如波激。","宁用清酒爲，欲作黄泉客。","不说玉山颓，且无饮中色。","勉从天帝诉，天上寡沈厄。","无处张穗帷，如何望松柏。","妾身昼团团，君魂夜寂寂。","蛾眉自觉长，颈粉谁怜白。","矜持昭阳意，不肯看南陌。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21056":["听颖师琴歌","李贺","乐府","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["别浦云归桂花渚，蜀国弦中双凤语。","芙蓉叶落秋鸾离，越王夜起游天姥。","暗佩清臣敲水玉，渡海蛾眉牵白鹿。","谁看挟劒赴长桥，谁看浸发题春竹。","竺僧前立当吾门，梵宫真相眉棱尊。","古琴大轸长八尺，峄阳老树非桐孙。","凉馆闻弦惊病客，药囊暂别龙须席。","请歌直请卿相歌，奉礼官卑复何益。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21057":["谣俗","李贺","乐府","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["上林胡蝶小，试伴汉家君。","飞向南城去，误落石榴裙。","脉脉花满树，翾翾燕遶云。","出门不识路，羞问陌头人。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21058":["静女春曙曲","李贺","乐府","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["嫩叶怜芳抱新蕊，泣露枝枝滴夭泪。","粉窗香咽颓晓云，锦堆花密藏春睡。","恋屏孔雀摇金尾，莺舌分明呼婢子。","冰洞寒龙半匣水，一只商鸾逐烟起。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21059":["少年乐","李贺","七言律诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["芳草落花如锦地，二十长游醉乡里。","红缨不动白马骄，垂柳金丝香拂水。","吴娥未笑花不开，绿鬓耸堕兰云起。","陆郎倚醉牵罗袂，夺得宝钗金翡翠。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21060":["句","李贺","五言律诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["不见山巅树，摧杌下爲薪。","日覩井中泥，上出作埃尘。","情知一丘趣，不谢千里印。","倚剑登高台，悠悠送春目。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21061":["冰柱","刘叉","古风","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["师干久不息，农爲兵兮民重嗟。","骚然县宇，土崩水溃。","畹中无熟谷，壠上无桑麻。","王春判序，百卉茁甲含葩。","有客避兵奔游僻，跋履险厄至三巴。","貂裘蒙茸已敝缕，鬓发蓬舥。","雀惊鼠伏，宁遑安处。","独卧旅舍无好梦，更堪走风沙。","天人一夜剪瑛琭，诘旦都成六出花。","南亩未盈尺，纤片乱舞空纷拏。","旋落旋逐朝暾化，檐间冰柱若削出交加。","或低或昂，小大莹洁。","随势无等差，始疑玉龙下界来人世。","齐向茅檐布爪牙，又疑汉高帝。","西方未斩虵，人不识，谁爲当风杖莫邪。","铿镗冰有韵，的皪玉无瑕。","不爲四时雨，徒於道路成泥柤。","不爲九江浪，徒爲汩没天之涯。","不爲双井水，满瓯泛泛烹春茶。","不爲中山浆，清新馥鼻盈百车。","不爲池与沼，养鱼种芰成霪䨟。","不爲醴泉与甘露，使名异瑞世俗夸。","特禀朝澈气，洁然自许靡间其迩遐。","森然气结一千里，滴沥声沈十万家。","明也虽小，暗之大不可遮。","勿被曲瓦，直下不能抑羣邪。","奈何时逼，不得时在我目中。","倏然漂去无余㱔，自是成毁任天理。","天於此物岂宜有忒赊，反令井蛙壁虫变容易。","背人缩首竞呀呀，我愿天子回造化。","藏之韫椟翫之生光华。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21062":["雪车","刘叉","古风","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["腊令凝绨三十日，缤纷密雪一复一。","孰云润泽在枯荄，闤闠饿民涷欲死。","死中犹被豺狼食，官车初还城垒未完备。","人家千里无烟火，鸡犬何太怨。","天不恤吾甿，如何连夜瑶花乱。","皎洁既同君子节，沾濡多着小人面。","寒鏁侯门见客稀，色迷塞路行商断。","小小细细如尘间，轻轻缓缓成朴簌。","官家不知民馁寒，尽驱牛车盈道载屑玉。","载载欲何之，秘藏深宫以御炎酷。","徒能自卫九重间，岂信车辙血，点点尽是农夫哭。","刀兵残丧後，满野谁爲载白骨。","远戍久乏粮，太仓谁爲运红粟。","戎夫尚逆命，扁箱鹿角谁爲敌。","士夫困征讨，买花载酒谁爲适。","天子端然少旁求，股肱耳目皆奸慝。","依违用事佞上方，犹驱饿民运造化防暑厄。","吾闻躬耕南亩舜之圣，爲民吞蝗唐之德。","未闻𭐁孽苦苍生，相羣相党上下爲蟊贼","庙堂食禄不自慙，我爲斯民叹息还叹息。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21063":["修养","刘叉","七言古诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["损神终日谈虚空，不必归命于胎中。","我神不西亦不东，烟收云散何蒙蒙。","尝令体如微微风，绵绵不断道自冲。","世人逢一不逢一，一回存想一回出。","只知一切望一切，不觉一日损一日。","劝君修真复识真，世上道人多忤人。","披图醮录益乱神，此法那能坚此身。","心田自有灵地珍，惜哉自有不自亲，明真汩没随埃尘。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21064":["勿执古寄韩潮州","刘叉","杂言古诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["古人皆执古，不辞[冻]饿悲。","今人亦执古，自取行坐危。","老菊凌霜葩，狞松抱雪姿。","武王亦至明，宁哀首阳饥。","仲尼岂非圣，但爲互乡嗤。","寸心生万路，今古棼若丝。","逐逐行不尽，茫茫休者谁。","来恨不可遏，去悔何足追。","玉石共笑唾，驽骥相奔驰。","请君勿执古，执古徒自隳。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21065":["荅孟东野","刘叉","五言古诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["酸寒孟夫子，苦爱老叉诗。","生涩有百篇，谓是琼瑶辞。","百篇非所长，忧来豁穷悲。","唯有刚肠铁，百链不柔亏。","退之何可駡，东野何可欺。","文王已云没，谁顾好爵縻。","生死守一丘，宁计饱与饥。","万事付杯酒，从人笑狂痴。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21066":["自古无长生劝姚合酒","刘叉","五言古诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["奉子一杯酒，爲子照颜色。","但愿腮上红，莫管颏下白。","自古无长生，生者何戚戚。","登山勿厌高，四望都无极。","丘陇逐日多，天地爲我窄。","祗见李耳书，对之空脉脉。","何曾见天上，着得刘安宅。","若问长生人，昭昭孔丘籍。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21067":["独饮","刘叉","五言绝句","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["尽欲调太羹，自古无好手。","所以山中人，兀兀但饮酒。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21068":["作诗","刘叉","五言律诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["作诗无知音，作不如不作。","未逢赓载人，此道终寂寞。","有虞今已殁，来者谁爲托。","朗咏豁心胸，笔与泪俱落。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21069":["天津桥","刘叉","七言绝句","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["洛阳宫阙照天地，四面山川无毒气。","谁令汉祖都秦关，从此奸雄转相炽。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21070":["嘲荆卿","刘叉","五言绝句","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["白虹千里气，血颈一劒义。","报恩不到头，徒作轻生士。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21071":["代牛言","刘叉","五言绝句","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["渴饮颍水流，饿喘吴门月。","黄金如可种，我力终不竭。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21072":["莫问卜","刘叉","古风","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["莫问卜，人生吉凶皆自速。","伏羲文王若无死，今人不爲古人哭。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21073":["观八骏图","刘叉","七言绝句","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["穆王八骏走不歇，海外去寻长日月。","五云望断阿母宫，归来落得新白发。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21074":["经战地","刘叉","五言古诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["杀气不上天，阴风吹雨血。","冤魂不入地，髑髅哭沙月。","人命固有常，此地何夭折。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21075":["野哭","刘叉","七言绝句","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["棘针生狞义路闲，野泉相吊声潺潺。","哀哉异教溺颓俗，淳源一去何时还。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21076":["古怨","刘叉","五言律诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["君莫嫌丑妇，丑妇死守贞。","山头一怪石，长作望夫名。","鸟有并翼飞，兽有比肩行。","丈夫不立义，岂如鸟兽情。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21077":["烈士咏","刘叉","五言古诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["烈士或爱金，爱金不爲贫。","义死天亦许，利生鬼亦嗔。","胡爲轻薄儿，使酒杀平人。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21078":["狂夫","刘叉","五言古诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["大妻唱舜歌，小妻鼓湘瑟。","狂夫游冶归，端坐仍作色。","不读关雎篇，安知后妃德。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21079":["饿咏","刘叉","五言绝句","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["文王久不出，贤士如土贱。","妻孥从饿死，敢爱黄金篆。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21080":["自问","刘叉","五言律诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["自问彭城子，何人授汝颠。","酒肠宽似海，诗胆大於天。","断劒徒劳匣，枯琴无复弦。","相逢不多合，赖是向林泉。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21081":["入蜀","刘叉","五言律诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["望空问真宰，此路爲谁开。","峡色侵天去，江声滚地来。","孔明深有意，锺会亦何才。","信此非人事，悲歌付一杯。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21082":["塞上逢卢仝","刘叉","杂言古诗","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["直到桑乾北，逢君夜不眠。","上楼腰脚健，怀土眼睛穿。","斗柄寒垂地，河流[冻]彻天。","羁魂泣相向，何事有诗篇。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21083":["偶书","刘叉","七言绝句","约元和间","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["日出扶桑一丈高，人间万事细如毛。","野夫怒见不平处，磨损胸中万古刀。"],"",[],{},[["野夫怒见不平处，磨损胸中万古刀。","侠气名句，刚健愤世。"]],["https://github.com/chinese-poetry/chinese-poetry","《全唐诗》卷三九一","《唐诗鉴赏辞典》刘叉条（上海辞书出版社，1983）","《全唐诗》（清·曹寅等编，康熙扬州诗局本）"]],"open_21084":["爱碣山石","刘叉","五言绝句","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["碣石何青青，挽我双眼睛。","爱尔多古峭，不到人间行。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21085":["与孟东野","刘叉","五言绝句","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["寒衣草木皮，饥饭葵藿根。","不爲孟夫子，岂识市井门。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21086":["姚秀才爱予小劒因赠","刘叉","五言绝句","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["一条古时水，向我手心流。","临行泻赠君，勿薄细碎讐。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21087":["老恨","刘叉","五言绝句","","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["雪打杉松残，补书书不完。","嬾学渭上翁，辛苦把钓竿。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21088":["思归乐","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["山中思归乐，尽作思归鸣。","尔是此山鸟，安得失乡名。","应缘此山路，自古离人征。","阴愁感和气，俾尔从此生。","我虽失乡去，我无失乡情。","惨舒在方寸，宠辱将何惊。","浮生居大块，寻丈可寄形。","身安即形乐，岂独乐咸京。","命者道之本，死者天之平。","安问远与近，何言殇与彭。","君看赵工部，八十支体轻。","交州二十载，一到长安城。","长安不须臾，复作交州行。","交州又累岁，移镇广与荆。","归朝新天子，济济爲上卿。","肌肤无瘴色，饮食康且宁。","长安一昼夜，死者如霣星。","丧车四门出，何关炎瘴萦。","况我三十二，百年未半程。","江陵道涂近，楚俗云水清。","遐想玉泉寺，久闻岘山亭。","此去尽绵历，岂无心赏幷。","红餐日充腹，碧涧朝析酲。","开门待宾客，寄书安弟兄。","闲穷四声韵，闷阅九部经。","身外皆委顺，眼前随所营。","此意久已定，谁能求苟荣。","所以官甚小，不畏权势倾。","倾心岂不易，巧诈神之刑。","万物有本性，况复人性灵。","金埋无土色，玉坠无瓦声。","劒折有寸利，镜破有片明。","我可俘爲囚，我可刃爲兵。","我心终不死，金石贯以诚。","此诚患不至，诚至道亦亨。","微哉满山鸟，呌噪何足听。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21089":["春鸠","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["春鸠与百舌，音响讵同年。","如何一时语，俱得春风怜。","犹知化工意，当春不生蝉。","免教争呌噪，沸渭桃花前。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21090":["春蝉","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["我自东归日，厌苦春鸠声。","作诗怜化工，不遣春蝉生。","及来商山道，山深气不平。","春秋两相似，虫豸百种鸣。","风松不成韵，蜩螗沸如羹。","岂无朝阳凤，羞与微物争。","安得天上雨，奔浑河海倾。","荡涤反时气，然後好晴明。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21091":["兔丝","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["人生莫依倚，依倚事不成。","君看兔丝蔓，依倚榛与荆。","荆榛易蒙密，百鸟撩乱鸣。","下有狐兔穴，奔走亦纵横。","樵童斫将去，柔蔓与之幷。","翳荟生可耻，束缚死无名。","桂树月中出，珊瑚石上生。","俊鹘度海食，应龙升天行。","灵物本特达，不复相缠萦。","缠萦竟何者，荆棘与飞茎。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21092":["古社","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["古社基址在，人散社不神。","惟有空心树，妖狐藏魅人。","狐惑意颠倒，臊腥不复闻。","丘坟变城郭，花草仍荆榛。","良田千万顷，占作天荒田。","主人议芟斫，怪见不敢前。","那言空山烧，夜随风马奔。","飞声鼓鼙震，高焰旗帜飜。","逡巡荆棘尽，狐兔无子孙。","狐死魅人灭，烟消坛墠存。","绕坛旧田地，给授有等伦。","农收邨落盛，社树新团圆。","社公千万岁，永保邨中民。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21093":["松树","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["华山高幢幢，上有高高松。","株株遥各各，叶叶相重重。","槐树夹道植，枝叶俱冥蒙。","既无贞直干，复有罥挂虫。","何不种松树，使之摇清风。","秦时已曾种，顦顇种不供。","可怜孤松意，不与槐树同。","闲在高山顶，樛盘虯与龙。","屈爲大厦栋，庇荫侯与公。","不肯作行伍，俱在尘土中。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21094":["芳树","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["芳树已寥落，孤英尤可嘉。","可怜团团叶，盖覆深深花。","游蜂竞钻刺，鬬雀亦纷拏。","天生细碎物，不爱好华光。","非无歼殄法，念尔有生涯。","春雷一声发，惊燕亦惊蛇。","清池养神蔡，已复长虾蟇。","雨露贵平施，吾其春草芽。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21095":["桐花","元稹","杂言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["胧月上山馆，紫桐垂好阴。","可惜暗澹色，无人知此心。","舜没苍梧野，凤归丹穴岑。","遗落在人世，光华那复深。","年年怨春意，不竞桃杏林。","唯占清明後，牡丹还复侵。","况此空馆闭，云谁恣幽寻。","徒烦鸟噪集，不语山嶔岑。","满院青苔地，一树莲花簪。","自开还自落，暗芳终暗沈。","尔生不得所，我愿裁爲琴。","安置君王侧，调和元首音。","安问宫徵角，先辨雅郑淫。","宫弦春以君，君若春日临。","商弦廉以臣，臣作旱天霖。","人安角声畅，人困鬬不任。","羽以类万物，祆物神不歆。","徵以节百事，奉事罔不钦。","五者苟不乱，天命乃可忱。","君若问孝理，弹作梁山吟。","君若事宗庙，拊以和球琳。","君若不好谏，愿献触疏箴。","君若不罢猎，请听荒于禽。","君若侈台殿，雍门可沾襟。","君若傲贤隽，鹿鸣有食芩。","君闻祈招什，车马勿駸駸。","君若欲败度，中有式如金。","君闻薰风操，志气在愔愔。","中有阜财语，勿受来献賝。","北里当绝听，祸莫大於婬。","南风苟不竞，无往遗之擒。","奸声不入耳，巧言宁孔壬。","枭音亦云革，安得沴与祲。","天子既穆穆，羣材亦森森。","劒士还农野，丝人归织紝。","丹凤巢阿阁，文鱼游碧浔。","和气浃寰海，易若溉蹄[涔]。","改张乃可鼓，此语无古今。","非琴独能尔，事有谕因鍼。","感尔桐花意，闲怨杳难禁。","待我持斤斧，置君爲大琛。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21096":["雉媒","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["双雉在野时，可怜同嗜欲。","毛衣前後成，一种文章足。","一雉独先飞，冲开芳草绿。","网罗幽草中，暗被潜羁束。","剪刀摧六翮，丝线缝双目。","啖养能几时，依然已驯熟。","都无旧性灵，返与他心腹。","置在芳草中，翻令诱同族。","前时相失者，思君意弥笃。","朝朝旧处飞，往往巢边哭。","今朝树上啼，哀音断还续。","远见尔文章，知君草中伏。","和鸣忽相召，鼓翅遥相瞩。","畏我未肯来，又啄翳前粟。","歛翮远投君，飞驰势奔蹙。","罥挂在君前，向君声促促。","信君决无疑，不道君相覆。","自恨飞太高，疎罗偶然触。","看看架上鹰，拟食无罪肉。","君意定何如，依旧雕笼宿。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21097":["箭镞","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["箭镞本求利，淬砺良甚难。","砺将何所用，砺以射凶残。","不砺射不入，不射人不安。","爲盗即当射，宁问私与官。","夜射官中盗，中之血阑干。","带箭君前诉，君王悄不欢。","顷曾爲盗者，百箭中心攒。","竞将儿女泪，滴沥助辛酸。","君王责良帅，此祸谁爲端。","帅言发硎罪，不使刃稍刓。","君王不忍杀，逐之如迸丸。","仍令後来箭，尽可头团团。","发硎去虽远，砺镞心不阑。","会射蛟螭尽，舟行无恶澜。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21098":["赛神","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["邨落事妖神，林木大如邨。","事来三十载，巫觋传子孙。","邨中四时祭，杀尽鸡与豚。","主人不堪命，积燎曾欲燔。","旋风天地转，急雨江河翻。","采薪持斧者，弃斧纵横奔。","山深多掩暎，仅免鲸鲵吞。","主人集邻里，各各持酒罇。","庙中再三拜，愿得禾稼存。","去年大巫死，小觋又妖言。","邑中神明宰，有意效西门。","焚除计未决，伺者迭乘轩。","庙深荆棘厚，但见狐兔蹲。","巫言小神变，可验牛马蕃。","邑吏齐进说，幸勿祸乡原。","踰年计不定，县听良亦烦。","涉夏祭时至，因令修四垣。","忧虞神愤恨，玉帛意弥敦。","我来神庙下，箫鼓正喧喧。","因言遣妖术，灭绝由本根。","主人中罢舞，许我重叠论。","蜉蝣生湿处，鸱鴞集黄昏。","主人邪心起，气焰日夜繁。","狐狸得蹊径，潜穴主人园。","腥臊袭左右，然後托丘樊。","岁深树成就，曲直可轮辕。","幽妖尽依倚，万怪之所屯。","主人一心好，四面无篱藩。","命樵执斤斧，怪木宁遽髠。","主人且倾听，再爲谕清浑。","阿胶在末派，罔象游上源。","灵药逡巡尽，黑波朝夕喷。","神龙厌流浊，先伐鼍与鼋。","鼋鼍在龙穴，妖气常郁温。","主人恶淫祀，先去邪与惛。","惛邪中人意，蛊祸蚀精魂。","德胜妖不作，势强威亦尊。","计穷然後赛，後赛复何恩。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21099":["大觜乌","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["阳乌有二类，觜白者名慈。","求食哺慈母，因以此名之。","饮啄颇廉俭，音响亦柔雌。","百巢同一树，栖宿不复疑。","得食先反哺，一身常苦羸。","缘知五常性，飜被衆禽欺。","其一觜大者，攫搏性贪痴。","有力强如鹘，有爪利如锥。","音响甚㕭嗗，潜通妖怪词。","受日余光庇，终天无死期。","翺翔富人屋，栖息屋前枝。","巫言此乌至，财产日丰宜。","主人一心惑，诱引不知疲。","转见乌来集，自言家转孳。","白鹤门外养，花鹰架上维。","专听乌喜怒，信受若神龟。","举家同此意，弹射不复施。","往往清池侧，却令鵷鹭随。","羣乌饱粱肉，毛羽色泽滋。","远近恣所往，贪残无不爲。","巢禽攫雏卵，廐马啄疮痍。","渗沥脂膏尽，凤皇那得知。","主人一朝病，争向屋檐窥。","呦鷕呼羣鵩，翩翻集怪鸱。","主人偏养者，啸聚最奔驰。","夜半仍惊噪，鸺鶹逐老狸。","主人病心怯，灯火夜深移。","左右虽无语，奄然皆泪垂。","平明天出日，阴魅走参差。","乌来屋檐上，又惑主人儿。","儿即当家业，玩好方爱奇。","占募能言鸟，置者许高赀。","陇树巢鹦鹉，言语好光仪。","美人倾心献，雕笼身自持。","求者临轩坐，置在白玉墀。","先问鸟中苦，便言乌若斯。","衆乌齐搏铄，翠羽几离披。","远掷千余里，美人情亦衰。","举家惩此患，事乌踰昔时。","向言池上鹭，啄肉寝其皮。","夜漏天终晓，阴云风定吹。","况尔乌何者，数极不知危。","会结弥天网，尽取一无遗。","常令阿阁上，宛宛宿长离。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21100":["分水岭","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["崔嵬分水岭，高下与云平。","上有分流水，东西随势倾。","朝同一源出，暮隔千里情。","风雨各自异，波澜相背惊。","势高竞奔注，势曲已回萦。","偶值当途石，蹙缩又纵横。","有时遭孔穴，变作呜咽声。","褊浅无所用，奔波奚所营。","团团井中水，不复东西征。","上应美人意，中涵孤月明。","旋风西面起，井深波不生。","坚冰一时合，井深冻不成。","终年汲引绝，不耗复不盈。","五月金石铄，既寒亦既清。","易时不易性，改邑不改名。","定如拱北极，莹若烧玉英。","君门客如水，日夜随势行。","君看守心者，井水爲君盟。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21101":["四皓庙","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["巢由昔避世，尧舜不得臣。","伊吕虽急病，汤武乃可君。","四贤胡爲者，千载名氛氲。","显晦有遗迹，前後疑不伦。","秦政虐天下，黩武穷生民。","诸侯战必死，壮士眉亦嚬。","张良韩孺子，椎碎属车轮。","遂令英雄意，日夜思报秦。","先生相将去，不复婴世尘。","云卷在孤岫，龙潜爲小鳞。","秦王转无道，谏者鼎镬亲。","茅焦脱衣谏，先生无一言。","赵高杀二世，先生如不闻。","刘项取天下，先生游白云。","海内八年战，先生全一身。","汉业日已定，先生名亦振。","不得爲济世，宜哉爲隐沦。","如何一朝起，屈作储贰宾。","安存孝惠帝，摧顇戚夫人。","舍大以谋细，虯盘而蠖伸。","惠帝竟不嗣，吕氏祸有因。","虽怀安刘志，未若周与陈。","皆落子房术，先生道何屯。","出处贵明白，故吾今有云。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21102":["青云驿","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["迢嶢青云岭，下有千仞谿。","裴回不可上，人倦马亦嘶。","愿登青云路，若望丹霞梯。","谓言青云驿，绣户芙蓉闺。","谓言青云骑，玉勒黄金蹄。","谓言青云具，瑚琏杂象犀。","谓言青云吏，的的颜如珪。","怀此青云望，安能复久稽。","攀援信不易，风雨正凄凄。","已怪杜鹃鸟，先来山下啼。","才及青云驿，忽遇蓬蒿妻。","延我开荜户，凿窦宛如圭。","逡巡吏来谒，头白颜色黧。","馈食频叫噪，假器仍乞醯。","向时延我者，共舍藿与藜。","乘我牂牁马，蒙茸大如羝。","悔爲青云意，此意良噬脐。","昔游蜀门下，有驿名青泥。","闻名意惨怆，若坠牢与狴。","云泥异所称，人物一以齐。","复闻阊阖上，下视日月低。","银城蘂珠殿，玉版金字题。","大帝直南北，羣仙侍东西。","龙虎俨队仗，雷霆轰鼓鼙。","元君理庭内，左右桃花蹊。","丹霞烂成绮，景云轻若绨。","天池光灩灩，瑶草绿萋萋。","衆真千万辈，柔颜尽如荑。","手持凤尾扇，头戴翠羽笄。","云韶互铿戛，霞服相提携。","双双发皓齿，各各扬轻袿。","天祚乐未极，溟波浩无堤。","秽贱灵所恶，安肯问黔黎。","桑田变成海，宇悬烹爲韲。","虚皇不愿见，云雾重重翳。","大帝安可梦，阊阖何由跻。","灵物可见者，愿以谕端倪。","虫蛇吐云气，妖氛变虹蜺。","获麟书诸册，豢龙醢爲臡。","凤皇占梧桐，丛杂百鸟栖。","野鹤啄腥虫，贪饕不如鸡。","山鹿藏窟穴，虎豹吞其麛。","灵物比灵境，冠履宁甚睽。","道胜即爲乐，何慙居稗稊。","金张好车马，於陵亲灌畦。","在梁或在火，不变玉与鹈。","上天勿行行，潜穴勿凄凄。","吟此青云谕，达观终不迷。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21103":["阳城驿","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["商有阳城驿，名同阳道州。","阳公没已久，感我泪交流。","昔公孝父母，行与曾闵俦。","既孤善兄弟，兄弟和且柔。","一夕不相见，若怀三岁忧。","遂誓不婚娶，没齿同衾裯。","妹夫死他县，遗骨无人收。","公令季弟往，公与仲弟留。","相别竟不得，三人同远游。","共负他乡骨，归来藏故丘。","栖迟居夏邑，邑人无苟媮。","里中竞长短，来问劣与优。","官刑一朝耻，公短终身羞。","公亦不遗布，人自不盗牛。","问公何能尔，忠信先自修。","发言当道理，不顾党与讐。","声香渐翕习，冠盖若云浮。","少者从公学，老者从公游。","往来相告报，县尹与公侯。","名落公卿口，涌如波荐舟。","天子得闻之，书下再三求。","书中愿一见，不异旱地虯。","何以持爲聘，束帛藉琳球。","何以持爲御，驷马驾安輈。","公方伯夷操，事殷不事周。","我实唐士庶，食唐之田畴。","我闻天子忆，安敢专自由。","来爲谏大夫，朝夕侍冕旒。","希夷惇薄俗，密勿献良筹。","神医不言术，人瘼曾暗瘳。","月请谏官俸，诸弟相对谋。","皆曰亲戚外，酒散目前愁。","公云不有尔，安得此嘉猷。","施余尽酤酒，客来相献酬。","日旰不谋食，春深仍弊裘。","人心良戚戚，我乐独由由。","贞元岁云暮，朝有曲如钩。","风波势奔蹙，日月光绸缪。","齿牙属爲猾，禾黍暗生蟊。","岂无司言者，肉食吞其喉。","岂无司搏者，利柄扼其鞲。","鼻复势气塞，不得辩薰莸。","公虽未显谏，惴惴如患瘤。","飞章八九上，皆若珠暗投。","炎炎日将炽，积燎无人抽。","公乃帅其属，决谏同报仇。","延英殿门外，叩合仍叩头。","且曰事不止，臣谏誓不休。","上知不可遏，命以美语酬。","降官司成署，俾之爲赘疣。","奸心不快活，击刺砺戈矛。","终爲道州去，天道竟悠悠。","遂令不言者，反以言爲訧。","喉舌坐成木，鹰鸇化爲鸠。","避权如避虎，冠豸如冠猴。","平生附我者，诗人称好逑。","私来一执手，恐若坠诸沟。","送我不出户，决我不回眸。","唯有太学生，各具粮与糇。","咸言公去矣，我亦去荒陬。","公与诸生别，步步驻行驺。","有生不可诀，行行过闽瓯。","爲师得如此，得爲贤者不。","道州闻公来，鼓舞歌且讴。","昔公居夏邑，狎人如狎鸥。","况自爲刺史，岂复援鼓桴。","滋章一时罢，教化天下遒。","炎瘴不得老，英华忽已秋。","有鸟哭杨震，无儿悲邓攸。","唯余门弟子，列树松与楸。","今来过此驿，若吊汨罗洲。","祠曹讳羊祜，此驿何不侔。","我愿避公讳，名爲避贤邮。","此名有深意，蔽贤天所尤。","吾闻玄元教，日月冥九幽。","幽阴蔽翳者，永爲幽翳囚。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21104":["苦雨","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江瘴气候恶，庭空田地芜。","烦昏一日内，阴暗三四殊。","巢燕汚牀席，苍蝇点肌肤。","不足生诟怒，但苦寡欢娱。","夜来稍清晏，放体阶前呼。","未饱风月思，已爲蚊蚋图。","我受簪组身，我生天地炉。","炎蒸安敢勌，虫豸何时无。","凌晨坐堂庑，努力泥中趋。","官家事不了，尤悔亦可虞。","门外竹桥折，马惊不敢踰。","回头命僮御，向我色踟蹰。","自顾方濩落，安能相诘诛。","隐忍心愤恨，翻爲声喣愉。","逡巡崔嵬日，杲曜东南隅。","已复云蔽翳，不使及泥涂。","良农尽蒲苇，厚地积潢汚。","三光不得照，万物何由苏。","安得飞廉车，磔裂云将躯。","又提精阳劒，蛟螭支节屠。","阴沴皆电埽，幽妖亦雷驱。","煌煌啓阊阖，轧轧掉乾枢。","东西生日月，昼夜如转珠。","百川朝巨海，六龙蹋亨衢。","此意倍寥廓，时来本须臾。","今也泥鸿洞，鼋鼍真得途。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21105":["种竹","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["昔公怜我直，比之秋竹竿。","秋来苦相忆，种竹厅前看。","失地颜色改，伤根枝叶残。","清风犹淅淅，高节空团团。","鸣蝉聒暮景，跳蛙集幽阑。","尘土复昼夜，梢云良独难。","丹丘信云远，安得临仙坛。","瘴江冬草绿，何人惊岁寒。","可怜亭亭干，一一青琅玕。","孤凤竟不至，坐伤时节阑。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21106":["和乐天赠樊着作","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["君爲着作诗，志激词且温。","璨然光扬者，皆以义烈闻。","千虑竟一失，冰玉不断痕。","谬予顽不肖，列在数子间。","因君讥史氏，我亦能具陈。","羲黄眇云远，载籍无遗文。","煌煌二帝道，铺设在典坟。","尧心惟舜会，因着爲话言。","臯夔益稷禹，粗得无间然。","缅然千载後，後圣曰孔宣。","迥知皇王意，缀书爲百篇。","是时游夏辈，不敢措舌端。","信哉作遗训，职在圣与贤。","如何至近古，史氏爲闲官。","但令识字者，窃弄刀笔权。","由心书曲直，不使当世观。","贻之千万代，疑言相竝传。","人人异所见，各各私所偏。","以是曰褒贬，不如都无焉。","况乃丈夫志，用舍贵当年。","顾予有微尚，愿以出处论。","出非利吾已，其出贵道全。","全道岂虚设，道全当及人。","全则富与寿，亏则饥与寒。","遂我一身逸，不如万物安。","解悬不泽手，拯溺无折旋。","神哉伊尹心，可以冠古先。","其次有独善，善己不善民。","天地爲一物，死生爲一源。","合杂分万变，忽若风中尘。","抗哉巢由志，尧舜不可迁。","舍此二者外，安用名爲宾。","持谢着书郎，愚不愿有云。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21107":["和乐天感鹤","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["我有所爱鹤，毛羽霜雪妍。","秋霄一滴露，声闻林外天。","自随卫侯去，遂入大夫轩。","云貌久已隔，玉音无复传。","吟君感鹤操，不觉心惕然。","无乃予所爱，误爲微物迁。","因兹谕直质，未免柔细牵。","君看孤松树，左右萝茑缠。","既可习爲饱，亦可薰爲荃。","期君常善救，勿令终弃捐。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21108":["谕宝二首 一","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["沈玉在弱泥，泥弱玉易沈。","扶桑寒日薄，不照万丈心。","安得潜渊虯，拔壑超邓林。","泥封泰山址，水散旱天霖。","洗此泥下玉，照耀台殿深。","刻爲传国宝，神器人不侵。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21109":["谕宝二首 二","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["冰置白玉壶，始见清皎洁。","珠穿殷红缕，始见明洞彻。","镆鋣无人淬，两刃幽壤铁。","秦镜无人拭，一片埋雾月。","骥局环堵中，骨附筋入节。","虯蟠尺泽内，鱼贯蛙同穴。","艅艎无巨海，浮浮矜瀎潏。","栋梁无广厦，颠倒卧霜雪。","大鹏无长空，举翮受羁絏。","豫樟无厚地，危柢真卼臲。","圭璧无卞和，甘与顽石列。","舜禹无陶尧，名随腐草灭。","神功伏神物，神物神乃别。","神人不世出，所以神功绝。","神物岂徒然，用之乃施设。","禹功九州理，舜德天下悦。","璧充传国玺，圭用祈太折。","千寻豫樟干，九万大鹏歇。","栋梁庇生民，艅艎济来哲。","虯腾旱天雨，骥骋流电掣。","镜悬奸胆露，劒拂妖蛇裂。","珠玉照乘光，冰莹环坐热。","此物比在泥，斯言爲谁发。","於今尽凡耳，不爲君不说。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21110":["说劒","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["吾友有宝劒，密之如密友。","我实胶漆交，中堂共杯酒。","酒酣肝胆露，恨不眼前剖。","高唱荆卿歌，乱击相如缶。","更击复更唱，更酌亦更寿。","白虹坐上飞，青蛇匣中吼。","我闻音响异，疑是干将偶。","爲君再拜言，神物可见不。","君言我所重，我自爲君取。","迎箧已焚香，近鞘先泽手。","徐抽寸寸刃，渐屈弯弯肘。","杀杀霜在锋，团团月临纽。","逡巡潜虯跃，郁律惊左右。","霆电满室光，蛟龙绕身走。","我爲捧之泣，此劒别来久。","铸时近山破，藏在松桂朽。","幽匣狱底埋，神人水心守。","本是稽泥淬，果非雷焕有。","我欲评劒功，愿君良听受。","劒可剸犀兕，劒可切琼玖。","劒决天外云，劒冲日中斗。","劒隳妖蛇腹，劒拂佞臣首。","太古初断鳌，武王亲击纣。","燕丹卷地图，陈平绾花绶。","曾被桂树枝，寒光射林薮。","曾经铸农器，利用翦稂莠。","神物终变化，复爲龙牝牡。","晋末武库烧，脱然排户牖。","爲欲埽羣胡，散作弥天帚。","自兹失所往，豪英共爲诟。","今复谁人铸，挺然千载後。","既非古风胡，无乃近鵶九。","自我与君游，平生益自负。","况擎宝劒出，重以雄心扣。","此劒何太奇，此心何太厚。","劝君慎所用，所用无或苟。","潜将辟魑魅，勿但防妾妇。","留斩泓下蛟，莫试街中狗。","君今困泥滓，我亦坌尘垢。","俗耳惊大言，逢人少开口。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21111":["书异","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["孟冬初寒月，渚泽蒲尚青。","飘萧北风起，皓雪纷满庭。","行过冬至後，冻闭万物零。","奔浑驰暴雨，骤鼓轰雷霆。","传云不终日，通宵曾莫停。","瘴云愁拂地，急溜疑注缾。","汹涌潢潦浊，喷薄鲸鲵腥。","跳趫井蛙喜，突兀水怪形。","飞蚋奔不死，修蛇蛰再醒。","应龙非时出，无乃岁不宁。","吾闻阴阳户，啓闭各有扃。","後时无肃杀，废职乃玄冥。","座配五天帝，荐用百品珍。","权爲祝融夺，神其焉得灵。","春秋雷电异，则必书诸经。","仲冬雷雨苦，愿省蒙蔽刑。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21112":["和乐天折劒头","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["闻君得折劒，一片雄心起。","讵意铁蛟龙，潜在延津水。","风云会一合，呼吸期万里。","雷震山岳碎，电斩鲸鲵死。","莫但宝劒头，劒头非此比。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21113":["松鹤","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["渚宫本坳下，佛庙有台阁。","台下三四松，低昂势前却。","是时晴景丽，松梢残雪薄。","日色相玲珑，纤云暎罗幕。","逡巡九霄外，似振风中铎。","渐见尺帛光，孤飞唳空鹤。","裴回耀霜雪，顾慕下寥廓。","蹋动樛盘枝，龙蛇互跳跃。","俯瞰九江水，旁瞻万里壑。","无心眄乌鸢，有字悲城郭。","清角已沈绝，虞韶亦冥寞。","骞翻勿重留，幸及钧天作。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21114":["竞渡","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["吾观竞舟子，因测大竞源。","天地昔将竞，蓬勃昼夜昏。","龙蛇相嗔薄，海岱俱崩奔。","羣动皆搅挠，化作流浑浑。","数极鬬心息，太和蒸混元。","一气忽爲二，矗然画乾坤。","日月复照耀，春秋递寒温。","八荒坦以旷，万物罗以繁。","圣人中间立，理世了不烦。","延绵复几岁，逮及羲与轩。","炎皇炽如炭，蚩尤扇其燔。","有熊竞心起，驱兽出林樊。","一战波委焰，再战火燎原。","战讫天下定，号之爲轩辕。","自是岂无竞，琐细不复言。","其次有龙竞，竞渡龙之门。","龙门浚如泻，淙射不可援。","赤鳞化时至，唐突鳍鬣掀。","乘风瞥然去，万里黄河飜。","接瞬电烻出，微吟霹雳喧。","傍瞻旷宇宙，俯瞰卑崑仑。","庶类咸在下，九霄行易扪。","倏辞蛙黾穴，遽排天帝阍。","回悲曝鳃者，未免鲸鲵吞。","帝命泽诸夏，不弃虫与昆。","随时布膏露，称物施厚恩。","草木沾我润，豚鱼望我蕃。","向来同竞辈，岂料由我存。","壮哉龙竞渡，一竞身独尊。","舍此皆蚁鬬，竞舟何足论。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21115":["寺院新竹","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["宝地琉璃坼，紫苞琅玕踊。","亭亭巧於削，一一大如拱。","冰碧林外寒，峯峦眼前耸。","槎枒矛戟合，屹仡龙蛇动。","烟泛翠光流，岁余霜彩重。","风朝竽籁过，雨夜鬼神恐。","佳色有鲜妍，修茎无拥肿。","节高迷玉镞，箨缀疑花捧。","讵必太山根，本自仙坛种。","谁令植幽壤，复此依闲冗。","居然霄汉姿，坐受藩篱壅。","噪集勌鸱乌，炎昏繁蠛蠓。","未遭伶伦听，非安子犹宠。","威凤来有时，虚心岂无奉。"],"",[["古评·《唐诗镜》","亦自修耸"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）"]],"open_21116":["詶别致用","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["风行自委顺，云合非有期。","神哉心相见，无眹安得离。","我有恳愤志，三十无人知。","修身不言命，谋道不择时。","达则济亿兆，穷亦济毫氂。","济人无大小，誓不空济私。","研几未淳熟，与世忽参差。","意气一爲累，猜仍良已随。","昨来窜荆蛮，分与平生隳。","那言返爲遇，获见心所奇。","一见肺肝尽，坦然无滞疑。","感念交契定，泪流如断縻。","此交定生死，非爲论盛衰。","此契宗会极，非爲同路岐。","君今虎在柙，我亦鹰就羁。","驯养保性命，安能奋殊姿。","玉色深不变，井水挠不移。","相看各年少，未敢深自悲。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21117":["竹部","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["竹部竹山近，岁伐竹山竹。","伐竹岁亦深，深林隔深谷。","朝朝冰雪行，夜夜豺狼宿。","科首霜断蓬，枯形烧余木。","一束十余茎，千钱百余束。","得钱盈千百，得粟盈斗斛。","归来不买食，父子分半菽。","持此欲何爲，官家岁输促。","我来荆门掾，寓食公堂肉。","岂惟遍妻孥，亦以及僮仆。","分尔有限资，饱我无端腹。","愧尔不复言，尔生何太蹙。"],"",[["古评·《唐诗镜》","石首县界"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）"]],"open_21118":["赛神","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["楚俗不事事，巫风事妖神。","事妖结妖社，不问疎与亲。","年年十月暮，珠稻欲垂新。","家家不歛获，赛妖无富贫。","杀牛贳官酒，椎鼓集顽民。","喧阗里闾隘，凶酗日夜频。","岁暮雪霜至，稻珠随陇湮。","吏来官税迫，求质倍称缗。","贫者日消铄，富亦无仓囷。","不谓事神苦，自言诚不真。","岳阳贤刺史，念此爲俗屯。","未可一朝去，俾之爲等伦。","粗许存习俗，不得呼党人。","但许一日泽，不得月与旬。","吾闻国侨理，三年名乃振。","巫风燎原久，未必怜徙薪。","我来歌此事，非独歌政仁。","此事四邻有，亦欲闻四邻。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21119":["竞舟","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["楚俗不爱力，费力爲竞舟。","买舟俟一竞，竞歛贫者赇。","年年四五月，蠒实麦小秋。","积水堰堤坏，拔秧蒲稗稠。","此时集丁壮，习竞南亩头。","朝饮邨社酒，暮椎邻舍牛。","祭船如祭祖，习竞如习讐。","连延数十日，作业不复忧。","君侯馔良吉，会客陈膳羞。","画鷁四来合，大竞长江流。","建标明取舍，胜负死生求。","一时讙呼罢，三月农事休。","岳阳贤刺史，念此爲俗疣。","习俗难尽去，聊用去其尤。","百船不留一，一竞不滞留。","自爲里中戏，我亦不寓游。","吾闻管仲教，沐树惩堕游。","节此淫竞俗，得爲良政不。","我来歌此事，非独歌此州。","此事数州有，亦欲闻数州。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21120":["茅舍","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["楚俗不理居，居人尽茅舍。","茅苫竹梁栋，茅疎竹仍罅。","边缘堤岸斜，诘屈檐楹亚。","篱落不蔽肩，街衢不容驾。","南风五月盛，时雨不来下。","竹蠹茅亦乾，迎风自焚灺。","防虞集邻里，巡警劳昼夜。","遗烬一星然，连延祸相嫁。","号呼邻谷帛，奔走伐桑柘。","旧架已新焚，新茅又初架。","前日洪州牧，念此常嗟讶。","牧民未及久，郡邑纷如化。","峻邸俨相望，飞甍远相跨。","旗亭红粉泥，佛庙青鸳瓦。","斯事才未终，斯人久云谢。","有客自洪来，洪民至今藉。","惜其心太亟，作役无容暇。","台观亦已多，工徒稍冤咤。","我欲他郡长，三时务耕稼。","农收次邑居，先室後台榭。","啓闭既及期，公私亦相借。","度材无强略，庀役有定价。","不使及僭差，粗得御寒夏。","火至殊陈郑，人安极嵩华。","谁能继此名，名流袭兰麝。","五袴有前闻，斯言我非诈。"],"",[["古评·《唐诗镜》","韦大夫丹"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）"]],"open_21121":["後湖","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["荆有泥泞水，在荆之邑郛。","郛前水在後，谓之爲後湖。","环湖十余里，岁积潢与汚。","臭腐鱼鳌死，不植菰与蒲。","郑公理三载，其理用喣愉。","岁稔民四至，隘廛亦隘衢。","公乃署其地，爲民先矢谟。","人人傥自爲，我亦不庀徒。","下里得闻之，各各相俞俞。","提携翁及孙，捧戴妇与姑。","壮者负砾石，老亦捽茅蒭。","斤磨片片雪，椎隐连连珠。","朝餐布庭落，夜宿完户枢。","邻里近相告，亲戚远相呼。","鬻者自爲鬻，酤者自爲酤。","鸡犬丰中市，人民岐下都。","百年废滞所，一旦奥浩区。","我实司水土，得爲官事无。","人言贱事贵，贵直不贵谀。","此实公所小，安用歌袴襦。","答云潭及广，以至鄂与吴。","万里尽泽国，居人皆垫濡。","富者不容盖，贫者不庇躯。","得不歌此事，以我爲楷模。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21122":["八骏图诗","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["穆满志空阔，将行九州野。","神驭四来归，天与八骏马。","龙种无凡性，龙行无暂舍。","朝辞扶桑底，暮宿崑仑下。","鼻息吼春雷，蹄声裂寒瓦。","尾掉沧波黑，汗染白云赭。","华輈本修密，翠盖尚妍冶。","御者腕不移，乘者寐不假。","车无轮扁斵，辔无王良把。","虽有万骏来，谁是敢骑者。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21123":["画松","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["张璪画古松，往往得神骨。","翠帚扫春风，枯龙戛寒月。","流传画师辈，奇态尽埋没。","纤枝无萧洒，顽干空突兀。","乃悟埃尘心，难状烟霄质。","我去淅阳山，深山看真物。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21124":["遣兴十首 一","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["始见棃花房，坐对棃花白。","行看棃叶青，已复棃叶赤。","严霜九月半，危蔕几时客。","况有高高原，秋风四来迫。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21125":["遣兴十首 二","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["莫厌夏日长，莫愁冬日短。","欲识短复长，君看寒又暖。","城中百万家，冤哀杂丝管。","草没奉诚园，轩车昔曾满。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21126":["遣兴十首 三","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["孤竹迸荒园，误与蓬麻列。","久拥萧萧风，空长高高节。","严霜荡羣秽，蓬断麻亦折。","独立转亭亭，心期凤皇别。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21127":["遣兴十首 四","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["艳艳翦红英，团团削翠茎。","托根在褊浅，因依泥滓生。","中有合欢蘂，池枯难遽呈。","凉宵露华重，低徊当月明。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21128":["遣兴十首 五","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["晚荷犹展卷，早蝉遽萧嘹。","露叶行已重，况乃江风摇。","炎夏火再伏，清商暗回飙。","寄言抱志士，日月东西跳。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21129":["遣兴十首 六","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["买马买锯牙，买犊买破车。","养禽当养鹘，种树先种花。","人生负俊健，天意与光华。","莫学蚯蚓辈，食泥近土涯。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21130":["遣兴十首 七","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["爱直莫爱夸，爱疾莫爱斜。","爱谟莫爱诈，爱施莫爱奢。","择才不求备，任物不过涯。","用人如用己，理国如理家。"],"好是遣兴语苐未得老",[["古评·《唐诗镜》","好是遣兴语苐未得老"],["古评·《唐诗镜》","似箴铭语却得不厌"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）"]],"open_21131":["遣兴十首 八","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["㸌㸌刀刃光，弯弯弓面张。","入水斩犀兕，上山椎虎狼。","里中无老少，唤作癫儿郎。","一日风云会，横行归故乡。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21132":["遣兴十首 九","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["团团规内星，未必明如月。","托迹近北辰，周天无沦没。","老人在南极，地远光不发。","见则寿圣明，愿照高高阙。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21133":["遣兴十首 十","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["河清谅嘉瑞，吾帝真圣人。","时哉不我梦，此时爲废民。","光阴本跳踯，功业劳苦辛。","一到江陵郡，三年成去尘。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21134":["野节鞭","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["神鞭鞭宇宙，玉鞭鞭骐骥。","紧綛野节鞭，本用鞭贔屭。","使君鞭甚长，使君马亦利。","司马竝马行，司马马顦顇。","短鞭不可施，疾步无由致。","使君驻马言，愿以长鞭遗。","此遗不寻常，此鞭不容易。","金坚无缴绕，玉滑无尘腻。","青蛇坼生石，不刺山阿地。","乌龟旋眼斑，不染江头泪。","长看雷雨痕，未忍驽骀试。","持用换所持，无令等闲弃。","答云君何奇，赠我君所贵。","我用亦不凡，终身保明义。","誓以鞭奸顽，不以鞭蹇踬。","指撝狡兔踪，决挞怪龙睡。","惜令寸寸折，节节不虚坠。","因作换鞭诗，诗成谓同志。","而我得闻之，笑君年少意。","安用换长鞭，鞭长亦奚爲。","我有鞭尺余，泥抛风雨渍。","不拟闲赠行，唯将烂夸醉。","春来信马头，款缓花前辔。","愿我迟似挛，饶君疾如翅。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21135":["旱灾自咎贻七县宰","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["吾闻上帝心，降命明且仁。","臣稹苟有罪，胡不灾我身。","胡爲旱一州，祸此千万人。","一旱犹可忍，其旱亦已频。","腊雪不满地，膏雨不降春。","恻恻诏书下，半减麦与缗。","半租岂不薄，尚竭力与筋。","竭力不敢惮，惭戴天子恩。","累累妇拜姑，呐呐翁语孙。","禾黍日夜长，足得盈我囷。","还填折粟税，酬偿贳麦邻。","苟无公私责，饮水不爲贫。","欢言未盈口，旱气已再振。","六月天不雨，秋孟亦既旬。","区区昧陋积，祷祝非不勤。","日驰衰白颜，再拜泥甲鳞。","归来重思忖，愿告诸邑君。","以彼天道远，岂如人事亲。","团团囹圄中，无乃冤不申。","扰扰食廪内，无乃奸有因。","轧轧输送车，无乃使不伦。","遥遥负担卒，无乃役不均。","今年无大麦，计与珠玉滨。","邨胥与里吏，无乃求取繁。","符不歛钱急，值官因酒嗔。","诛求与挞罚，无乃不逡巡。","生小下里住，不曾州县门。","诉词千万恨，无乃不得闻。","强豪富酒肉，穷独无蒭薪。","俱由案牍吏，无乃移祸屯。","官分市井户，迭配水陆珍。","未蒙所偿直，无乃不敢言。","有一於此事，安可尤苍旻。","借使漏刑宪，得不虞鬼神。","自顾顽滞牧，坐贻灾沴臻。","上羞朝廷寄，不愧闾里民。","岂无神明宰，爲我同苦辛。","共布慈惠语，慰此衢客尘。"],"",[["古评·《唐诗镜》","谆恳处不厌其烦"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）"]],"open_21136":["虫豸诗  一","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["巴蛇千种毒，其最鼻褰蛇。","掉舌翻红焰，盘身蹙白花。","喷人竖毛发，饮浪沸泥沙。","欲学叔敖瘗，其如多似麻。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21137":["虫豸诗  二","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["越岭南滨海，武都西隐戎。","雄黄假名石，鷣鸟远难笼。","讵有隳肠计，应无破脑功。","巴山昼昏黑，妖雾毒蒙蒙。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21138":["虫豸诗  三","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["汉帝斩蛇劒，晋时烧上天。","自兹繁巨蟒，往往寿千年。","白昼遮长道，青溪蒸毒烟。","战龙苍海外，平地血浮船。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21139":["虫豸诗  一","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["巴蛇蟠窟穴，穴下有巢蜂。","近树禽垂翅，依原兽绝踪。","微遭断手足，厚毒破心胸。","昔甚招魂句，那知眼自逢。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21140":["虫豸诗  二","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["梨笑清都月，蜂游紫殿春。","构脾分部伍，嚼蕊奉君亲。","翅羽颇同类，心神固异伦。","安知人世里，下有噬人人。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21141":["虫豸诗  三","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["兰蕙本同畹，蜂蛇亦杂居。","害心俱毒螫，妖焰两吹嘘。","雷蛰吞噬止，枯焚巢穴除。","可怜相济恶，勿谓祸无余。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21142":["虫豸诗  一","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["蜘蛛天下足，巴蜀就中多。","缝隙容长踦，虚空织横罗。","萦缠伤竹柏，吞噬及虫蛾。","爲送佳人喜，珠栊无奈何。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21143":["虫豸诗  二","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["网密将求食，丝斜误着人。","因依方纪绪，挂罥遂容身。","截道蝉冠碍，漫天玉露频。","儿童怜小巧，渐欲及车轮。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21144":["虫豸诗  三","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["稚子怜圆网，佳人祝喜丝。","那知缘暗隙，忽被囓柔肌。","毒腠攻犹易，焚心疗恐迟。","看看长祆绪，和扁欲涟洏。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21145":["虫豸诗  一","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["蚁子生无处，偏因湿处生。","阴霪烦扰攘，拾粒苦譻𧭈","牀上主人病，耳中虚藏鸣。","雷霆翻不省，闻汝作牛声。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21146":["虫豸诗  二","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["时术功虽细，年深祸亦成。","攻穿漏江海，噆食困蛟鲸。","敢惮榱𣡵蠹，深藏柱石倾","寄言持重者，微物莫全轻。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21147":["虫豸诗  三","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["攘攘终朝见，悠悠卒岁疑。","讵能分牝牡，焉得有蝝蚳。","徙市竟何意，生涯都几时。","巢由或逢我，应似我相期。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21148":["虫豸诗  一","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["蟆子微於蚋，朝繁夜则无。","毫端生羽翼，针喙噆肌肤。","暗毒应难免，羸形日渐枯。","将身远相就，不敢恨非辜。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21149":["虫豸诗  二","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["晦景权藏毒，明时敢噬人。","不劳生诟怒，祗足助酸辛。","隼眦看无物，蛇躯庇有鳞。","天方刍狗我，甘与尔相亲。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21150":["虫豸诗  三","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["有口深堪异，趋时讵可量。","谁令通鼻息，何故辨馨香。","沈水来沧海，崇兰泛露光。","那能枉焚爇，尔衆我微茫。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21151":["虫豸诗  一","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["可叹浮尘子，纤埃喻此微。","宁谕隔纱幌，幷解透绵衣。","有毒能成痏，无声不见飞。","病来双眼暗，何计辨雰霏。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21152":["虫豸诗  二","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["乍可巢蚊睫，胡爲附蟒鳞。","已微於蠢蠢，仍害及仁人。","动植皆分命，毫芒亦是身。","哀哉此幽物，生死敌浮尘。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21153":["虫豸诗  三","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["但觉皮肤憯，安知琐细来。","因风吹薄雾，向日误轻埃。","暗囓堪销骨，潜飞有祸胎。","然无防备处，留待雪霜摧。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21154":["虫豸诗  一","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["阴深山有瘴，湿垫草多蝱。","衆噬锥刀毒，羣飞风雨声。","汗粘疮痏痛，日曝苦辛行。","饱尔蛆残腹，安知天地情。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21155":["虫豸诗  二","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["千山溪沸石，六月火烧云。","自顾生无类，那堪毒有羣。","搏牛皮若截，噬马血成文。","蹄角尚如此，肌肤安可云。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21156":["虫豸诗  三","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["辛螫终非久，炎凉本递兴。","秋风自天落，夏蘖与霜澄。","一镜开潭面，千锋露石棱。","气平虫豸死，云路好攀登。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21157":["楚歌十首 一","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["楚人千万户，生死系时君。","当璧便爲嗣，贤愚安可分。","干戈长浩浩，篡乱亦纷纷。","纵有明在下，区区何足云。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21158":["楚歌十首 二","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["陶虞事已远，尼父独将明。","潜穴龙无位，幽林兰自生。","楚王谋授邑，此意复中倾。","未别子西语，纵来何所成。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21159":["楚歌十首 三","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["平王渐昏惑，无极转承恩。","子建犹相贰，伍奢安得存。","生居宫雉閟，死葬寝园尊。","岂料奔吴士，鞭屍郢市门。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21160":["楚歌十首 四","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["惧盈因邓曼，罢猎爲樊姬。","盛德留金石，清风鉴薄帷。","襄王忽妖梦，宋玉复淫辞。","万事捐宫馆，空山云雨期。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21161":["楚歌十首 五","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["宜僚南市住，未省食人恩。","临难忽相感，解纷宁用言。","何如晋夷甫，坐占紫微垣。","看着五胡乱，清谈空自尊。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21162":["楚歌十首 六","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["谁恃王深宠，谁爲楚上卿。","包胥心独许，连夜哭秦兵。","千乘徒虚尔，一夫安可轻。","殷勤聘名士，莫但倚方城。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21163":["楚歌十首 七","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["梁业雄图尽，遗孙世运消。","宣明徒有号，江汉不相朝。","碑碣高临路，松枝半作樵。","唯余开圣寺，犹学武皇妖。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21164":["楚歌十首 八","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江陵南北道，长有远人来。","死别登舟去，生心上马回。","荣枯诚异日，今古尽同灰。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21165":["楚歌十首 九","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["三峡连天水，奔波万里来。","风涛各自急，前後苦相推。","倒入黄牛漩，惊冲灩澦堆。","古今流不尽，流去不曾回。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21166":["楚歌十首 十","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["八荒同日月，万古共山川。","生死既由命，兴衰还付天。","栖栖王粲赋，愤愤屈平篇。","各自埋幽恨，江流终宛然。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21167":["襄阳道","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["羊公名渐远，唯有岘山碑。","近日称难继，曹王任马彝。","椒兰俱下世，城郭到今时。","汉水清如玉，流来本爲谁。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21168":["赋得鱼登龙门","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["鱼贯终何益，龙门在苦登。","有成当作雨，无用耻爲鹏。","激浪诚难泝，雄心亦自凭。","风云潜会合，鬐鬣忽腾凌。","泥滓辞河浊，烟霄见海澄。","回瞻顺流辈，谁敢望同升。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21169":["贞元历","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["象魏才颁历，龙镳已御天。","犹看後元历，新署永贞年。","半岁光阴在，三朝礼数迁。","无因书简册，空得咏诗篇。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21170":["塞马","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["塞马倦江渚，今朝神彩生。","晓风寒猎猎，乍得草头行。","夷狄寝烽候，关河无战声。","何由当阵面，从尔四蹄轻。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21171":["鹿角镇","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["去年湖水满，此地覆行舟。","万怪吹高浪，千人死乱流。","谁能问帝子，何事宠阳侯。","渐恐鲸鲵大，波涛及九州。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21172":["感事三首 一","元稹","五言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["爲国谋羊舌，从来不爲身。","此心长自保，终不学张陈。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21173":["感事三首 二","元稹","五言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["自笑心何劣，区区辨所冤。","伯仁虽到死，终不向人言。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21174":["感事三首 三","元稹","五言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["富贵年皆长，风尘旧转稀。","白头方见绝，遥爲一沾衣。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21175":["题翰林东合前小松","元稹","五言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["檐碍修鳞亚，霜侵簇翠黄。","唯余入琴韵，终待舜弦张。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21176":["清都夜境","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["夜久连观静，斜月何晶荧。","寥天如碧玉，历历缀华星。","楼榭自阴暎，云牖深冥冥。","纤埃悄不起，玉砌寒光清。","栖鹤露微影，枯松多怪形。","南厢俨容卫，音响如可聆。","啓圣发空洞，朝真趋广庭。","闲开蘂珠殿，暗阅金字经。","屏气动方息，凝神心自灵。","悠悠车马上，浩思安得宁。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21177":["春晚寄杨十二兼呈赵八","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["蒙蒙竹树深，帘牖多清阴。","避日坐林影，余花委芳襟。","倾尊就残酌，舒卷续微吟。","空际扬高蝶，风中聆素琴。","广庭备幽趣，复对商山岑。","独此爱时景，旷怀云外心。","迁鸎恋嘉木，求友多好音。","自无琅玕实，安得莲花簪。","寄之二君子，希见双南金。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21178":["与杨十二李三早入永寿寺看牡丹","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["晓入白莲宫，琉璃花界净。","开敷多喻草，凌乱被幽径。","压砌锦地铺，当霞日轮暎。","蝶舞香暂飘，蠭牵蕊难正。","笼处彩云合，露湛红珠莹。","结叶影自交，摇风光不定。","繁华有时节，安得保全盛。","色见尽浮荣，希君了真性。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21179":["春余遣兴","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["春去日渐迟，庭空草偏长。","余英间初实，雪絮萦蛛网。","好鸟多息阴，新篁已成响。","帘开斜照入，树褭游丝上。","绝迹念物闲，良时契心赏。","单衣颇新绰，虚室复清敞。","置酒奉亲宾，树萱自怡养。","笑倚连枝花，恭扶瑞藤杖。","步屧恣优游，望山多气象。","云叶遥卷舒，风裾动萧爽。","簪缨固烦杂，江海徒浩荡。","野马笼赤霄，无由负羁鞅。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21180":["忆云之","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["爲鱼实爱泉，食辛宁避蓼。","人生既相合，不复论窕窕。","沧海良有穷，白日非长皎。","何事一人心，各在四方表。","泛若逐水萍，居爲附松茑。","流浪随所之，萦纡牵所绕。","百龄颇局促，况复迷寿夭。","芟发君已衰，冠岁予非小。","娱乐不及时，暮年壮心少。","感此幽念绵，遂爲长悄悄。","中庭草木春，历乱递相扰。","奇树花冥冥，竹竿凤褭褭。","幽芳被兰径，安得寄天杪。","万里潇湘魂，夜夜南枝鸟。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21181":["别李三","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["阶蓂附瑶砌，藂兰偶芳藿。","高位良有依，幽姿亦相托。","鲍叔知我贫，烹葵不爲薄。","半面契始终，千金比然诺。","人生系时命，安得无苦乐。","但感游子颜，又值余英落。","苍苍秦树云，去去缑山鹤。","日暮分手归，杨花满城郭。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21182":["秋夕远怀","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["旦夕天气爽，风飘叶渐轻。","星繁河汉白，露逼衾枕清。","丹鸟月中灭，莎鸡牀下鸣。","悠悠此怀抱，况复多远情。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21183":["东西道","元稹","杂言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["天皇开四极，便有东西道。","万古阅行人，行人几人老。","顾我倦行者，息阴何不早？","少壮尘事多，那言壮年好。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21184":["分流水","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["古时愁别泪，滴作分流水。","日夜东西流，分流几千里。","通塞两不见，波澜各自起。","与君相背飞，去去心如此。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21185":["西还","元稹","五言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["悠悠洛阳梦，郁郁灞陵树。","落日正西归，逢君又东去。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21186":["含风夕","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["炎昏勌烦久，逮此含风夕。","夏服稍轻清，秋堂已岑寂。","载欣凉宇旷，复念佳辰掷。","络纬惊岁功，顾我何成绩。","青荧微月钩，幽晖洞阴魄。","水镜涵玉轮，若见渊泉璧。","参差帘牖重，次第笼虚白。","树影满空牀，萤光缀深壁。","怅望牵牛星，复爲经年隔。","露网褭风珠，轻河泛遥碧。","讵无深秋夜，感此乍流易。","亦有迟暮年，壮年良自惜。","循环切中肠，感念追往昔。","接瞬无停阴，何言问陈积。","馨香推蕙兰，坚贞谕松柏。","生物固有涯，安能比金石。","况兹百龄内，扰扰纷衆役。","日月东西驰，飞车无留迹。","来者良未穷，去矣定奚适。","委顺在物爲，营营复何益。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21187":["秋堂夕","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["炎凉正回互，金火郁相乘。","云雷时交构，川泽方蒸腾。","清风一朝胜，白露忽已凝。","草木凡气尽，始见天地澄。","况此秋堂夕，幽怀旷无朋。","萧条帘外雨，倏闪案前灯。","书卷满牀席，蠨蛸悬复升。","啼儿屡哑咽，勌僮时寝兴。","泛觉昏夜目，咏谣畅烦膺。","况吟获麟章，欲罢久不能。","尧舜事已远，丘道安可胜。","蜉蝣不信鹤，蜩鷃肯窥鹏。","当年且不偶，没世何必称。","胡爲揭闻见，褒贬贻爱憎。","焉用汩其泥，岂在清如冰。","非白又非黑，谁能点青蝇。","处世苟无闷，佯狂道非弘。","无言被人觉，予亦笑孙登。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21188":["酬乐天","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["放鹤在深水，置鱼在高枝。","升沈或异势，同谓非所宜。","君爲邑中吏，皎皎鸾凤姿。","顾我何爲者，翻侍白玉墀。","昔作芸香侣，三载不暂离。","逮兹忽相失，旦夕梦魂思。","崔嵬骊山顶，宫树遥参差。","祗得两相望，不得长相随。","多君岁寒意，裁作秋兴诗。","上言风尘苦，下言时节移。","官家事拘束，安得携手期。","愿爲云与雨，会合天之垂。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21189":["杨子华画三首 一","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["杨画远於展，何言今在兹。","依然古妆服，但感时节移。","念君一朝意，遗我千载思。","子亦几时客，安能长苦悲。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21190":["杨子华画三首 二","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["皓腕卷红袖，锦韝臂苍鹗。","故人断弦心，稚齿从禽乐。","当年惜贵游，遗形寄丹雘。","骨象或依稀，铅华已寥落。","似对古人民，无复昔城郭。","子亦观病身，色空俱寂寞。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21191":["杨子华画三首 三","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["颠倒世人心，纷纷乏公是。","真赏画不成，画赏真相似。","丹青各所尚，工拙何足恃。","求此妄中精，嗟哉子华子。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21192":["西州院","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["自入西州院，唯见东川城。","今夜城头月，非暗又非明。","文案牀席满，卷舒赃罪名。","惨凄且烦勌，弃之阶下行。","怅望天廻转，动摇万里情。","参辰次第出，牛女颠倒倾。","况此风中柳，枝条千万茎。","到来篱下笋，亦已长短生。","感怆正多绪，鵶鵶相唤惊。","墙上杜鹃鸟，又作思归鸣。","以彼撩乱思，吟爲幽怨声。","吟罢终不寝，冬冬复铛铛。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21193":["台中鞫狱忆开元观旧事呈损之兼赠周兄四十韵","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["忆在开元馆，食柏练玉颜。","疎慵日高卧，自谓轻人寰。","李生隔墙住，隔墙如隔山。","怪我久不识，先来问骄顽。","十过乃一往，遂成相往还。","以我文章卷，文章甚斒斓。","因言辛庾辈，亦愿放羸孱。","既廻数子顾，展转相连攀。","驱令选科目，若在闠与闤。","学随尘土坠，漫数公卿关。","唯恐坏情性，安能惧谤讪。","还招辛庾李，静处杯巡环。","进取果由命，不由趋险艰。","穿杨二三子，弓矢次第弯。","推我亦上道，再联朝士班。","二月除御史，三月使巴蛮。","蛮民詀諵诉，啮指明痛癏。","怜蛮不解语，爲发昏帅奸。","归来五六月，旱色天地殷。","分司别兄弟，各各泪潸潸。","哀哉剧部职，唯数赃罪锾。","死款依稀取，鬬辞方便删。","道心常自愧，柔发难久黫。","折支望车乘，支痛谁置患。","奇哉乳臭儿，绯紫䙀被间。","渐大官渐贵，渐富心渐悭。","闹装辔头𧤾，静拭腰带斑","鹞子绣线𩏪，狗儿金油鐶","香汤洗騘马，翠篾笼白鹇。","月请公王封，冰受天子颁。","开筵试歌舞，别宅宠妖娴。","坐卧摩绵褥，捧拥綟丝鬟。","旦夕不相离，比翼若飞鸾。","而我亦何苦，三十身已鳏。","愁吟心骨颤，寒卧支体𤸷","居处虽幽静，尤悔少愉㦨。","不如周道士，鹤岭临钟湾。","绕院松瑟瑟，通畦水潺潺。","阳坡自寻蕨，邨沼看沤菅。","穷通两未遂，营营真老闲。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21194":["韦氏馆与周隐客杜归和泛舟","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["天色低澹澹，池光漫油油。","轻舟闲缴绕，不远池上楼。","时物欣外奖，真元随内修。","神恬津藏满，气委支节柔。","衆处岂自异，旷怀谁我俦。","风车笼野马，八荒安足游。","开颜陆浑杜，握手灵都周。","持君宝珠赠，顶戴头上头。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21195":["刘氏馆集隐客归和子元及之子蒙晦之","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["湿垫缘竹径，寥落护岸冰。","偶然沽市酒，不越四五升。","诗客爱时景，道人话升腾。","笑言各有趣，悠哉古孙登。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21196":["寄隐客","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["我年三十二，鬓有八九丝。","非无官次第，其如身早衰。","今人夸贵富，肉食与妖姬。","而我俱不乐，贵富亦何爲。","况逢多士朝，贤俊若布棊。","班行次第立，朱紫相参差。","谟猷密勿进，羽檄纵横驰。","监察官甚小，发言无所裨。","小官仍不了，谴夺亦已随。","时或不之弃，得不自弃之。","陶君喜不遇，顾我复何疑。","潜书周隐士，白云今有期。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21197":["元和五年予官不了罚俸西归三月六日至陕府与吴十一兄端公崔二十二院长思怆曩游因投五十韵","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["小年闲爱春，认得春风意。","未有花草时，先醲晓窗睡。","霞朝澹云色，霁景牵诗思。","渐到柳枝头，川光始明媚。","长安车马客，倾心奉权贵。","昼夜尘土中，那言早春至。","此时我独游，我游有伦次。","闲行曲江岸，便宿慈恩寺。","扣林引寒龟，疏丛出幽翠。","凌晨过杏园，晓露凝芳气。","初阳好明净，嫩树怜低庳。","排房似缀珠，欲啼红脸泪。","新莺语娇小，浅水光流利。","冷饮空腹杯，因成日高醉。","酒醒闻饭钟，随僧受遗施。","餐罢还复游，过从上文记。","行逢二月半，始足游春骑。","是时春已老，我游亦云既。","藤开九华观，草结三条隧。","新笋踊犀株，落梅飜蝶翅。","名倡绣毂车，公子青丝辔。","朝士还旬休，豪家得春赐。","提携好音乐，翦铲空田地。","同占杏花园，喧阗各丛萃。","顾予烦寝兴，复往散顦顇。","倦仆色肌羸，蹇驴行跛痹。","春衫未成就，冬服渐尘腻。","倾盖吟短章，书空忆难字。","遥闻公主笑，近被王孙戏。","邀我上华筵，横头坐宾位。","那知我年少，深解酒中事。","能唱犯声歌，偏精变筹义。","含词待残拍，促舞递繁吹。","叫噪掷投盘，生狞摄觥使。","逡巡光景晏，散乱东西异。","古观闭闲门，依然复幽閟。","无端矫情性，漫学求科试。","薄艺何足云，虚名偶频遂。","拾遗天子前，密奏升平议。","召见不须臾，憸庸已猜忌。","朝陪香案班，暮作风尘尉。","去岁又登朝，登爲柏台吏。","台官相束缚，不许放情志。","寓直劳送迎，上堂烦避讳。","分司在东洛，所职尤不易。","罚俸得西归，心知受朝庇。","常山攻小寇，淮右择良帅。","国难身不行，劳生欲何爲。","吾兄谙性灵，崔子同臭味。","投此挂冠词，一生还自恣。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21198":["寄吴士矩端公五十韵","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["昔在凤翔日，十岁即相识。","未有好文章，逢人赏颜色。","可怜何郎面，二十才冠饰。","短发予近梳，罗衫紫蝉翼。","伯舅各骄纵，仁兄未摧抑。","事业若杯盘，诗书甚徽纆。","西州戎马地，贤豪事雄特。","百万时可赢，十千良易借。","寒食桐阴下，春风柳林侧。","藉草送远游，列筵酬博塞。","萎蕤云幕翠，灿烂红茵赩。","脍缕轻似丝，香醅腻如职。","将军频下城，佳人尽倾国。","媚语娇不闻，纤腰輭无力。","歌辞妙宛转，舞态能剜刻。","筝弦玉指调，粉汗红绡拭。","予时最年少，专务酒中职。","未能解生狞，偏矜任狂直。","曲庇桃根盏，横讲捎云式。","乱布鬬分朋，惟新间谗慝。","耻作最先吐，羞言未朝食。","醉眼渐纷纷，酒声频䬵䬵。","扣节参差乱，飞觥往来织。","强起相维持，飜成两匍匐。","边霜飒然降，战马鸣不息。","但喜秋光丽，谁忧塞云黑。","常随猎骑走，多在豪家匿。","夜饮天既明，朝歌日还昃。","荒狂岁云久，名利心潜逼。","时辈多得途，亲朋屡相敕。","闲因适农野，忽复爱稼穑。","平生中圣人，飜然腐肠贼。","亦从酒仙去，便被书魔惑。","脱迹壮士场，甘心竖儒域。","矜持翠筠管，敲断黄金勒。","屡益兰膏灯，犹研兔枝墨。","崎岖来掉荡，矫枉事沈默。","隐笑甚艰难，敛容还屴崱。","与君始分散，勉我劳修饰。","岐路各营营，别离长恻恻。","行看二十载，万事纷何极。","相值或须臾，安能洞胸臆。","昨来陕郊会，悲欢两难克。","问我新相知，但报长相忆。","岂无新知者，不及小相得。","亦有生岁游，同年不同德。","爲别讵几时，伊予坠沟洫。","大江鼓风浪，远道参荆棘。","往事返无期，前途浩难测。","一旦得自由，相求北山北。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21199":["三月二十四日宿曾峰馆夜对桐花寄乐天","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["微月照桐花，月微花漠漠。","怨澹不胜情，低回拂帘幕。","叶新阴影细，露重枝条弱。","夜久春恨多，风清暗香薄。","是夕远思君，思君瘦如削。","但感事睽违，非言官好恶。","奏书金銮殿，步屣青龙阁。","我在山馆中，满地桐花落。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21200":["酬乐天书怀见寄","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["新昌北门外，与君从此分。","街衢走车马，尘土不见君。","君爲分手归，我行行不息。","我上秦岭南，君直枢星北。","秦岭高崔嵬，商山好颜色。","月照山馆花，裁诗寄相忆。","天明作诗罢，草草随所如。","凭人寄将去，三月无报书。","荆州白日晚，城上鼓冬冬。","行逢贺州牧，致书三四封。","封题乐天字，未坼已沾裳。","坼书八九读，泪落千万行。","中有酬我诗，句句截我肠。","仍云得诗夜，梦我魂凄凉。","终言作书处，上直金銮东。","诗书费一夕，万恨缄其中。","中宵宫中出，复见宫月斜。","书罢月亦落，晓灯随暗花。","想君书罢时，南望劳所思。","况我江上立，吟君怀我诗。","怀我浩无极，江水秋正深。","清见万丈底，照我平生心。","感君求友什，因报壮士吟。","持谢衆人口，销尽犹是金。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21201":["酬乐天登乐游园见忆","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["昔君乐游园，怅望天欲曛。","今我大江上，快意波飜云。","秋空压澶漫，澒洞无垢氛。","四顾皆豁达，我眉今日伸。","长安隘朝市，百道走埃尘。","轩车随对列，骨肉非本亲。","夸游丞相第，偷入常侍门。","爱君直如发，勿念江湖人。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21202":["酬乐天早夏见怀","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["庭柚有垂实，燕巢无宿雏。","我亦辞社燕，茫茫焉所如。","君诗夏方早，我叹秋已徂。","食物风土异，衾裯时节殊。","荒草满田地，近移江上居。","八日复切九，月明侵半除。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21203":["酬乐天劝醉","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["神麯清浊酒，牡丹深浅花。","少年欲相饮，此乐何可涯。","沈机造神境，不必悟楞伽。","酡颜返童貌，安用成丹砂。","刘伶称酒德，所称良未多。","愿君听此曲，我爲尽称嗟。","一杯颜色好，十盏胆气加。","半酣得自恣，酩酊归太和。","共醉真可乐，飞觥撩乱歌。","独醉亦有趣，兀然无与他。","美人醉灯下，左右流横波。","王孙醉牀上，颠倒眠绮罗。","君今劝我醉，劝醉意如何。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21204":["和乐天初授户曹喜而言志","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["王爵无细大，得请即爲恩。","君求户曹掾，贵以禄奉亲。","闻君得所请，感我欲沾巾。","今人重轩冕，所重华与纷。","矜夸仕台阁，奔走无朝昏。","君衣不盈箧，君食不满囷。","君言养既薄，何以荣我门。","披诚再三请，天子怜俭贫。","词曹直文苑，捧诏荣且忻。","归来高堂上，兄弟罗酒尊。","各称千万寿，共饮三四巡。","我实知君者，千里能具陈。","感君求禄意，求禄殊衆人。","上以奉颜色，余以及亲宾。","弃名不弃实，谋养不谋身。","可怜白华士，永愿凌青云。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21205":["和乐天赠吴丹","元稹","杂言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["不识吴生面，久知吴生道。","迹虽染世名，心本奉天老。","雌一守命门，廻九填血脑。","委气荣卫和，咽津颜色好。","传闻共甲子，衰隤尽枯[槁]。","独有冰雪容，纤华夺鲜缟。","问人何能尔，吴实旷怀抱。","弁冕徒挂身，身外非所宝。","伊予固童昧，希真亦云早。","石坛玉晨尊，昼夜长自埽。","密印视丹田，游神梦三岛。","万过黄庭经，一食青精稻。","冥搜方朔桃，结念安期枣。","绿发幸未改，丹诚自能保。","行当摆尘缨，吴门事探讨。","君爲先此词，终期搴瑶草。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21206":["和乐天秋题曲江","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["十载定交契，七年镇相随。","长安最多处，多是曲江池。","梅杏春尚小，芰荷秋已衰。","共爱寥落境，相将偏此时。","緜緜红蓼水，扬扬白鹭鹚。","诗句偶未得，酒杯聊久持。","今来云雨旷，旧赏魂梦知。","况乃江枫夕，和君秋兴诗。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21207":["和乐天别弟後月夜作","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["闻君别爱弟，明天照夜寒。","秋雁拂檐影，晓琴当砌弹。","怅望天澹澹，因思路漫漫。","吟爲别弟操，闻者爲辛酸。","况我兄弟远，一身形影单。","江波浩无极，但见时岁阑。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21208":["和乐天秋题牡丹丛","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["敝宅艳山卉，别来长叹息。","吟君晚丛咏，似见摧隤色。","欲识别後容，勤过晚丛侧。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21209":["春月","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["春月虽至明，终有霭霭光。","不似秋冬色，逼人寒带霜。","纤粉澹虚壁，轻烟笼半牀。","分晖间林影，余照上虹梁。","病久尘事隔，夜闲清兴长。","拥抱颠倒领，步屣东西厢。","风柳结柔援，露梅飘暗香。","雪含樱绽蘂，珠蹙桃缀房。","杳杳有余思，行行安可忘。","四邻非旧识，无以话中肠。","南有居士俨，默坐调心王。","款关一问讯，爲我披衣裳。","延我入深竹，暖我於小堂。","视身琉璃莹，谕指芭蕉黄。","复有比丘溢，早传龙树方。","口中秘丹诀，肘後悬青囊。","锡杖虽独振，刀圭期共尝。","未知仙近远，已觉神轻翔。","夜久魂耿耿，月明露苍苍。","悲哉沈眠士，宁见兹夕良。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21210":["月临花","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["临风扬扬花，透影胧胧月。","巫峡隔波云，姑峰漏霞雪。","镜匀娇面粉，灯泛高笼缬。","夜久清露多，啼珠坠还结。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21211":["红芍药","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["芍药绽红绡，巴篱织青琐。","繁丝蹙金蘂，高焰当炉火。","翦刻彤云片，开张赤霞裹。","烟轻琉璃叶，风亚珊瑚朵。","受露色低迷，向人娇婀娜。","酡颜醉後泣，小女妆成坐。","艳艳锦不如，夭夭桃未可。","晴霞畏欲散，晚日愁将堕。","结植本爲谁，赏心期在我。","采之谅多思，幽赠何由果。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21212":["送王十一南行","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["夏水漾天末，晚阳依岸邨。","风调乌尾劲，眷恋余芳尊。","解袂方瞬息，征帆已翩翻。","江豚涌高浪，枫树摇去魂。","远戍宗侣泊，暮烟洲渚昏。","离心讵几许，骤若移寒温。","此别信非久，胡爲坐忧烦。","我留石难转，君泛云无根。","万里湖南月，三声山上猿。","从兹耿幽梦，夜夜湘与沅。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21213":["三叹 一","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["孤劒锋刀涩，犹能神彩生。","有时雷雨过，暗吼阗阗声。","主人閟灵宝，畏作升天行。","淬砺当阳铁，刻爲干镆名。","远求鸊鹈莹，同用玉匣盛。","颜色纵相类，利钝颇相倾。","雄爲光电烻，雌但深泓澄。","龙怒有奇变，青蛇终不惊。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21214":["三叹 二","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["仙凤翠皇死，葳蕤光彩低。","非无鸳鸾侣，誓不同树栖。","飞驰岁云暮，感念雏在泥。","顾影不自暖，寄尔蟠桃鸡。","驯养岂无愧，类族安得齐。","愿言成羽翼，奋翅凌丹梯。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21215":["三叹 三","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["天骥失龙偶，三年常夜嘶。","哀缘喷风断，渴且含霜啼。","长恐绝遗类，不复蹑云霓。","非无駉駉者，鹤意不在鸡。","春来筋骨瘦，吊影心亦迷。","自此渥洼种，应生浊水泥。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21216":["遣昼","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["密竹有清阴，旷怀无尘滓。","况乃秋日光，玲珑晓窗里。","旬休聊自适，今辰日高起。","栉沐坐前轩，风轻镜如水。","开卷恣咏谣，望云闲徙倚。","新菊媚鲜妍，短萍怜靃靡。","埽除田地静，摘掇园蔬美。","幽翫惬诗流，空堂称居士。","客来伤寂寞，我念遗烦鄙。","心迹两相忘，谁能验行止。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21217":["冬夜怀李侍御王太祝段丞","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["浩露烟壒尽，月光闲有余。","松篁细阴影，重以帘牖疎。","泛览星粲粲，轻河悠碧虚。","纤云不成叶，脉脉风丝舒。","丹竈炽东序，烧香罗玉书。","飘飘魂神举，若骖鸾鹤舆。","感念夙昔意，华尚簪与裾。","簪裾讵几许，累创吞钩鱼。","今闻馨香道，一以悟臭帤。","悟觉誓不惑，永抱胎仙居。","昼夜欣所适，安知岁云除。","行行二三友，君怀复何如。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21218":["西斋小松二首 一","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["松树短於我，清风亦已多。","况乃枝上雪，动摇微月波。","幽姿得闲地，讵感岁蹉跎。","但恐厦终构，藉君当奈何。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21219":["西斋小松二首 二","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["簇簇枝新黄，纤纤攒素指。","柔苙渐依条，短莎还半委。","清风日夜高，凌云意何已。","千岁盘老龙，修鳞自兹始。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21220":["周先生","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["寥寥空山岑，冷冷风松林。","流月垂鳞光，悬泉扬高音。","希夷周先生，烧香调琴心。","神力盈三千，谁能还黄金。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21221":["遣春十首 一","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["晓月笼云影，鸎声余雾中。","暗芳飘露气，轻寒生柳风。","冉冉一趋府，未爲劳我躬。","因兹得晨起，但觉情兴隆。"],"",[["古评·《唐诗镜》","语帯方束"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）"]],"open_21222":["遣春十首 二","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["久雨怜霁景，偶来堤上行。","空蒙天色嫩，杳淼江面平。","百草短长出，衆禽高下鸣。","春阳各有分，予亦澹无情。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21223":["遣春十首 三","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["镜皎碧潭水，微波粗成文。","烟光垂碧草，琼脉散纤云。","岸柳好阴影，风裾遗垢氛。","悠然送春目，八荒谁与羣。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21224":["遣春十首 四","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["低迷笼树烟，明净当霞日。","阳焰波春空，平湖漫凝溢。","雪鹭远近飞，渚牙浅深出。","江流复浩荡，相爲坐纡郁。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21225":["遣春十首 五","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["暄寒深浅春，红白前後花。","颜色讵相让，生成良有涯。","梅芳勿自早，菊秀勿自赊。","各将一时意，终年无再华。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21226":["遣春十首 六","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["高屋童稚少，春来归燕多。","葺旧良易就，新院亦已罗。","俯怜雏化卵，仰愧鹏无窠。","巢栋与巢幕，秋风俱奈何。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21227":["遣春十首 七","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["撩乱扑树蜂，摧残恋房蕊。","风吹雨又频，安得繁於绮。","酒盃沈易过，世事纷何已。","莫倚颜似花，君看岁如水。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21228":["遣春十首 八","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["绕郭高高冢，半是荆王墓。","後嗣炽阳台，前贤甘荜路。","善恶徒自分，波流尽东注。","胡然不饮酒，坐落桐花树。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21229":["遣春十首 九","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["花阴莎草长，藉莎闲自酌。","坐看鸎鬬枝，轻花满尊杓。","葛巾竹稍挂，书卷琴上阁。","沽酒过此生，狂歌眼前乐。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21230":["遣春十首 十","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["梨叶已成阴，柳条纷起絮。","波绿紫屏风，螺红碧筹筯。","三杯面上热，万事心中去。","我意风散云，何劳问行处。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21231":["表夏十首 一","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["夏风多暖暖，树木有繁阴。","新笋紫长短，早樱红浅深。","烟花云幕重，榴艳朝景侵。","华实各自好，讵云芳意沈。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21232":["表夏十首 二","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["初日满阶前，轻风动帘影。","旬时得休浣，高卧阅清景。","僮儿拂巾箱，鵶轧深林井。","心到物自闲，何劳远箕頴。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21233":["表夏十首 三","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江瘴炎夏早，蒸腾信难度。","今宵好风月，独此荒庭趣。","露叶倾暗光，流星委余素。","但恐清夜徂，讵悲朝景暮。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21234":["表夏十首 四","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["孟月夏犹浅，奇云未成峰。","度霞红漠漠，压浪白溶溶。","玉委有余润，飙驰无去踪。","何如捧云雨，喷毒随蛟龙。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21235":["表夏十首 五","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["流芳递炎景，繁英尽寥落。","公署香满庭，晴霞覆阑药。","裁红起高焰，缀绿排新萼。","凭此遣幽怀，非言念将谑。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21236":["表夏十首 六","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["红丝散芳树，旋转光风急。","烟泛被笼香，露浓妆面湿。","佳人不在此，恨望堦前立。","忽厌夏景长，今春行已及。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21237":["表夏十首 七","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["百舌渐吞声，黄鸎正娇小。","云鸿方警夜，笼鸡已鸣晓。","当时客自适，运去谁能矫。","莫厌夏虫多，蜩螗定相扰。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21238":["表夏十首 八","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["翩翩帘外燕，戢戢巢内雏。","啖食筋力尽，毛衣成紫襦。","朝来各飞去，雄雌梁上呼。","养子将备老，恶儿那胜无。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21239":["表夏十首 九","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["西山夏雪消，江势东南泻。","风波高若天，灩澦低於马。","正被黄牛旋，难期白帝下。","我在平地行，翻忧济川者。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21240":["表夏十首 十","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["灵均死波後，是节常浴兰。","彩缕碧筠糉，香秔白玉团。","逝者良自苦，今人反爲欢。","哀哉徇名士，没命求所难。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21241":["解秋十首 一","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["清晨頮寒水，动摇襟袖轻。","翳翳林上叶，不知秋暗生。","回悲镜中发，华白三四茎。","岂无满头黑，念此衰已萌。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21242":["解秋十首 二","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["微霜才结露，翔鸠初变鹰。","无乃天地意，使之行小惩。","鸱鴞诚可恶，蔽日有高鹏。","舍大以擒细，我心终不能。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21243":["解秋十首 三","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["往岁学仙侣，各在无何乡。","同时骛名者，次第鵷鹭行。","而我两不遂，三十鬓添霜。","日暮江上立，蝉鸣枫树黄。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21244":["解秋十首 四","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["後伏火犹在，先秋蝉已多。","云色日夜白，骄阳能几何。","壤隙漏江海，忽微成网罗。","勿言时不至，但恐岁蹉跎。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21245":["解秋十首 五","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["新月才到地，轻河如泛云。","萤飞高下火，树影参差文。","露簟有微润，清香时暗焚。","夜闲心寂默，洞庭无垢氛。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21246":["解秋十首 六","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["霁丽牀前影，飘萧帘外竹。","簟凉朝睡重，梦觉茶香熟。","亲烹园内葵，凭买家家麯。","酿酒幷毓蔬，人来有棊局。"],"",[["古评·《唐诗镜》","语趣歴落"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）"]],"open_21247":["解秋十首 七","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["寒竹秋雨重，凌霄晚花落。","低回翠玉梢，散乱栀黄萼。","颜色有殊异，风霜无好恶。","年年百草芳，毕意同萧索。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21248":["解秋十首 八","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["春非我独春，秋非我独秋。","岂念百草死，但念霜满头。","头白古所同，胡爲坐烦忧。","茫茫百年内，处身良未休。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21249":["解秋十首 九","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["西风冷衾簟，展转布华茵。","来者承玉体，去者流芳尘。","适意丑爲好，及时疎亦亲。","衰周仲尼出，无乃爲妖人。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21250":["解秋十首 十","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["漠漠江面烧，微微枫树烟。","今日复今夕，秋怀方浩然。","况我头上发，衰白不待年。","我怀有时极，此意何由诠。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21251":["遣病十首 一","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["服药备江瘴，四年方一疠。","岂是药无功，伊予久留滞。","滞留人固薄，瘴久药难制。","去日良已甘，归途奈无际。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21252":["遣病十首 二","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["弃置何所任，郑公怜我病。","三十九万钱，资予养顽瞑。","身贱杀何益，恩深报难罄。","公其万千年，世有天之郑。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21253":["遣病十首 三","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["忆作孩稚初，健羡成人列。","倦学厌日长，嬉游念佳节。","今来渐讳年，顿与前心别。","白日速如飞，佳晨亦骚屑。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21254":["遣病十首 四","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["昔在痛饮场，憎人病辞醉。","病来身怕酒，始悟他人意。","怕酒岂不闲，悲无少年气。","传语少年儿，杯盘莫廻避。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21255":["遣病十首 五","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["忆初头始白，昼夜惊一缕。","渐及鬓与须，多来不能数。","壮年等闲过，过壮年已五。","华发不再青，劳生竟何补。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21256":["遣病十首 六","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["在家非不病，有病心亦安。","起居甥侄扶，药饵兄嫂看。","今病兄远路，道遥书信难。","寄言娇小弟，莫作官家官。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21257":["遣病十首 七","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["燕巢官舍内，我尔俱爲客。","岁晚我独留，秋深尔安适。","风高翅羽垂，路远烟波隔。","去去玉山岑，人间网罗窄。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21258":["遣病十首 八","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["檐宇夜来旷，暗知秋已生。","卧悲衾簟冷，病觉支体轻。","炎昏岂不勌，时去聊自惊。","浩叹终一夕，空堂天欲明。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21259":["遣病十首 九","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["秋依静处多，况乃凌晨趣。","深竹蝉昼风，翠茸衫晓露。","庭莎病看长，林果闲知数。","何以强健时，公门日劳骛。"],"",[["古评·《唐诗镜》","庭莎二语缀趣佳"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）"]],"open_21260":["遣病十首 十","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["朝结故乡念，暮作空堂寝。","梦别泪亦流，啼痕暗横枕。","昔愁凭酒遣，今病安能饮。","落尽秋槿花，离人病犹甚。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21261":["寒","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江瘴节候暖，腊初梅已残。","夜来北风至，喜见今日寒。","扣冰浅塘水，拥雪深竹阑。","复此满尊醁，但嗟谁与欢。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21262":["玉泉道中作","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["楚俗物候晚，孟冬才有霜。","早农半华实，夕水含风凉。","遐想云外寺，峰峦渺相望。","松门接官路，泉脉连僧房。","微露上弦月，暗焚初夜香。","谷深烟壒净，山虚钟磬长。","念此清境远，复忧尘事妨。","行行即前路，勿滞分寸光。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21263":["遣病","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["自古谁不死，不复记其名。","今年京城内，死者老少幷。","独孤才四十，仕宦方荣荣。","李三三十九，登朝有清声。","赵昌八十余，三拥大将旌。","爲生信异异，之死同冥冥。","其家哭泣爱，一一无异情。","其类嗟叹惜，各各无重轻。","万龄龟菌等，一死天地平。","以此方我病，我病何足惊。","借如今日死，亦足了一生。","借使到百年，不知何所成。","况我早师佛，屋宅此身形。","舍彼复就此，去留何所萦。","前身爲过迹，来世即前程。","但念行不息，岂忧无路行。","蜕骨龙不死，蜕皮蝉自鸣。","胡爲神蜕体，此道人不明。","持谢爱朋友，寄之仁弟兄。","吟此可达观，世言何足听。"],"",[["古评·《唐诗镜》","秘书少监郁"],["古评·《唐诗镜》","监察御史顾言"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）"]],"open_21264":["感梦","元稹","杂言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["十月初二日，我行蓬州西。","三十里有馆，有馆名芳溪。","荒邮屋舍坏，新雨田地泥。","我病百日余，肌体顾若刲。","气填暮不食，早早掩窦圭。","阴寒筋骨病，夜久灯火低。","忽然寝成梦，宛见颜如珪。","似叹久离别，嗟嗟复凄凄。","问我何病痛，又叹何栖栖。","答云痰滞久，与世复相暌。","重云痰小疾，良药固易挤。","前时奉橘丸，攻疾有神功。","何不善和疗，岂独头有风。","殷勤平生事，款曲无不终。","悲欢两相极，以是半日中。","言罢相与行，行行古成里。","同行复一人，不识谁氏子。","逡巡急吏来，呼唤愿且止。","驰至相君前，再拜复再起。","啓云吏有奉，奉命传所旨。","事有大惊忙，非君不能理。","答云久就闲，不愿见劳使。","多谢致勤勤，未敢相唯唯。","我因前献言，此事愚可料。","乱热由静消，理繁在知要。","君如冬月阳，奔走不必召。","君如铜镜明，万物自可照。","愿君许苍生，勿复高体调。","相君不我言，顾我再三笑。","行行及城户，黯黯余日晖。","相君不我言，命我从此归。","不省别时语，但省涕淋漓。","觉来身体汗，坐卧心骨悲。","闪闪灯背壁，胶胶鸡去埘。","倦童颠倒寝，我泪纵横垂。","泪垂啼不止，不止啼且声。","啼声觉僮仆，僮仆撩乱惊。","问我何所苦，问我何所思。","我亦不能语，惨惨即路岐。","前经新政县，今夕复明辰。","寘寘满心气，不得说向人。","奇哉赵明府，怪我眉不伸。","云有北来僧，住此月与旬。","自言辨贵骨，谓若识天真。","谈游费閟景，何不与逡巡？","僧来爲予语，语及昔所知。","自言有奇中，裴相未相时。","读书灵山寺，住处接园篱。","指言他日贵，晷刻似不移。","我闻僧此语，不觉泪歔欷。","因言前夕梦，无人一相谓。","无乃裴相君，念我胸中气。","遣师及此言，使我尽前事。","僧云彼何亲，言下涕不已。","我云知我深，不幸先我死。","僧云裴相君，如君恩有几。","我云滔滔衆，好直者皆是。","唯我与白生，感遇同所以。","官学不同时，生小异乡里。","拔我尘土中，使我名字美。","美名何足多，深分从此始。","吹嘘莫我先，顽陋不我鄙。","往往裴相门，终年不曾履。","相门多衆流，多誉亦多毁。","如闻风过尘，不动井中水。","前时予掾荆，公在期复起。","自从裴公无，吾道甘已矣。","白生道亦孤，谗谤销骨髓。","司马九江城，无人一言理。","爲师陈苦言，挥涕满十指。","未死终报恩，师听此男子。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21265":["和东川李相公慈竹十二韵","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["慈竹不外长，密比青瑶华。","矛攒有森束，玉粒无蹉跎。","纤粉妍腻质，细琼交翠柯。","亭亭霄汉近，霭霭雨露多。","冰碧寒夜耸，箫韶风昼罗。","烟含胧胧影，月泛鳞鳞波。","鸾凤一已顾，燕雀永不过。","幽姿媚庭实，颢气爽天涯。","峻节高转露，贞筠寒更佳。","托身仙坛上，灵物神所呵。","时与天籁合，日闻阳春歌。","应怜孤生者，摧折成病痾。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21266":["酬东川李相公十六韵","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["昔附赤霄羽，葳蕤游紫垣。","鬬班香案上，奏语玉晨尊。","戆直撩忌讳，科仪惩傲顽。","自从真籍除，弃置勿复论。","前时共游者，日夕黄金轩。","请帝下巫觋，八荒求我魂。","鸾凤屡鸣顾，燕雀尚篱藩。","徒令霄汉外，往往尘念存。","存念岂虚设，并投琼与璠。","弹珠古所讶，此用何太敦。","邹律寒气变，郑琴祥景奔。","灵芝绕身出，左右光彩繁。","碾玉无俗色，蘂珠非世言。","重慙前日句，陋若莸并荪。","腊月巴地雨，瘴江愁浪翻。","因持骇鸡宝，一照浊水昏。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21267":["酬独孤二十六送归通州","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["再拜捧兄赠，拜兄珍重言。","我有平生志，临别将具论。","十岁慕倜傥，爱白不爱昏。","宁爱寒切烈，不爱阳温暾。","二十走猎骑，三十游海门。","憎兔跳趯趯，恶鹏黑翻翻。","鳌钓气方壮，鹘拳心颇尊。","下观鬇鬡辈，一扫冀不存。","名冠壮士籍，功酬明主恩。","不然合身弃，何况身上痕。","金石有销烁，胏腑无寒温。","分画久已定，波涛何足烦。","尝希苏门啸，讵厌巴树猿。","瘴水徒浩浩，浮云亦轩轩。","长歌莫长欢，饮斛莫饮樽。","生爲醉乡客，死作达士魂。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21268":["酬刘猛见送","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["种花有颜色，异色即爲妖。","养鸟恶羽翮，剪翮不待高。","非无剪伤者，物性难自逃。","百足虽捷捷，商羊亦翘翘。","伊余狷然质，谬入多士朝。","任气有愎戆，容身寡朋曹。","愚狂偶似直，静僻非敢骄。","一爲毫发忤，十载山川遥。","烁铁不在火，割肌不在刀。","险心露山岳，流语翻波涛。","六尺安敢主，方寸自由调。","神劒土不蚀，异布火不燋。","虽无二物姿，庶欲効一毫。","未能深蹙蹙，多谢相劳劳。","去去我移马，迟迟君过桥。","云势正横壑，江流初满槽。","持此慰远道，此之爲旧交。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21269":["酬乐天赴江州路上见寄三首 一","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["昔在京城心，今在吴楚末。","千山道路险，万里音尘阔。","天上参与商，地上胡与越。","终天升沈异，满地网罗设。","心有无眹环，肠有无绳结。","有结解不开，有环寻不歇。","山岳移可尽，江海塞可绝。","离恨若空虚，穷年思不彻。","生莫强相同，相同会相别。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21270":["酬乐天赴江州路上见寄三首 二","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["襄阳大堤绕，我向堤前住。","烛随花艳来，骑送朝云去。","万竿高庙竹，三月徐亭树。","我昔忆君时，君今怀我处。","有身有离别，无地无岐路。","风尘同古今，人世劳新故。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21271":["酬乐天赴江州路上见寄三首 三","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["人亦有相爱，我尔殊衆人。","朝朝宁不食，日日愿见君。","一日不得见，愁肠坐氛氲。","如何远相失，各作万里云。","云高风苦多，会合难遽因。","天上犹有碍，何况地上身。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21272":["邮竹","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["庭有萧萧竹，门有阗阗骑。","嚣静本殊途，因依偶同寄。","亭亭乍干云，嫋嫋亦垂地。","人有异我心，我无异人意。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21273":["落月","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["落月沈余影，阴渠流暗光。","蚊声霭窗户，萤火绕屋梁。","飞幌翠云薄，新荷清露香。","不吟复不寐，竟夕池水傍。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21274":["高荷","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["种藕百余根，高荷才四叶。","颭闪碧云扇，团圆青玉叠。","亭亭自擡举，鼎鼎难藏擪。","不学着水荃，一生长怗怗。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21275":["和裴校书鹭鸶飞","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["鹭鸶鹭鸶何遽飞，鵶惊雀噪难久依。","清江见底草堂在，一点白光终不归。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21276":["夜池","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["荷叶团圆茎削削，绿萍面上红衣落。","满池明月思啼螿，高屋无人风张幕。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21277":["酬杨司业十二兄早秋述情见寄","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["白发故人少，相逢意弥远。","往事共销沈，前期各衰晚。","昨来遇弥苦，已复云离巘。","秋草古胶庠，寒沙废宫苑。","知心岂忘鲍，咏怀难和阮。","壮志日萧条，那能竞朝幰。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21278":["代杭人作使君一朝去二首 一","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["使君一朝去，遗爱在人口。","惠化境内春，才名天下首。","爲问龚黄辈，兼能作诗否。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21279":["代杭人作使君一朝去二首 二","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["使君一朝去，断肠如剉檗。","无复见冰壶，唯应镂金石。","自此一州人，生男尽名白。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21280":["长庆历","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["年历复年历，卷尽悲且惜。","历日何足悲，但悲年运易。","年年岂无叹，此叹何唧唧。","所叹别此年，永无长庆历。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21281":["顺宗至德大圣大安孝皇帝挽歌词三首 一","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["不改延洪祚，因成揖让朝。","讴歌同戴啓，遏密共思尧。","雨露施恩广，梯航会葬遥。","号弓那独切，曾感昔年招。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21282":["顺宗至德大圣大安孝皇帝挽歌词三首 二","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["前春文祖庙，大舜嗣尧登。","及此踰年感，还因是月崩。","寿缘追孝促，业在继明兴。","俭诏同今古，山川绕灞陵。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21283":["顺宗至德大圣大安孝皇帝挽歌词三首 三","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["七月悲风起，凄凉万国人。","羽仪经巷内，輼𨍇转城闉","暝色依陵早，秋声入辂新。","自嗟同草木，不识永贞春。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21284":["宪宗章武孝皇帝挽歌词三首 一","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["国付重离後，身随十圣仙。","北辰移帝座，西日到虞泉。","方丈言虚设，华胥事眇然。","触鳞曾在宥，偏哭堕髯前。"],"",[["古评·《唐诗镜》","膳部员外时作"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）"]],"open_21285":["宪宗章武孝皇帝挽歌词三首 二","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["天宝遗余事，元和盛圣功。","二凶枭帐下，三叛斩都中。","始服沙陁虏，方吞逻逤戎。","狼星如要射，犹有鼎湖弓。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21286":["宪宗章武孝皇帝挽歌词三首 三","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["月落禁垣西，星攒晓仗齐。","风传宫漏苦，云拂羽仪低。","路隘车千两，桥危马万蹄。","共嗟封石捡，不爲报功泥。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21287":["恭王故太妃挽歌词二首 一","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["燕姞贻天梦，梁王尽孝思。","虽从魏诏葬，得用汉藩仪。","曙月残光敛，寒箫度曲迟。","平生奉恩地，哀挽欲何之。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21288":["恭王故太妃挽歌词二首 二","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["文卫罗新圹，仙娥掩暝山。","雪云埋陇合，箫鼓望城还。","寒树风难静，霜郊夜更闲。","哀荣深孝嗣，仪表在河间。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21289":["哭吕衡州六首 一","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["气敌三人杰，交深一纸书。","我投冰莹眼，君报水怜鱼。","髀股惟夸瘦，膏肓岂暇除。","伤心死诸葛，忧道不忧余。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21290":["哭吕衡州六首 二","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["望有经纶钓，虔收宰相刀。","江文驾风远，云貌接天高。","国待球琳器，家藏虎豹韬。","尽将千载宝，埋入五原蒿。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21291":["哭吕衡州六首 三","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["白马双旌队，青山八阵图。","请缨期系虏，枕草誓捐躯。","势激三千壮，年应四十无。","遥闻不瞑目，非是不怜吴。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21292":["哭吕衡州六首 四","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["鵰鹗生难敌，沉檀死更香。","儿童喧巷市，羸老哭碑堂。","鴈起沙汀闇，云连海气黄。","祝融峰上月，几照北人丧。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21293":["哭吕衡州六首 五","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["廻鴈峰前鴈，春廻尽却廻。","联行四人去，同葬一人来。","铙吹临江返，城池隔雾开。","满船深夜哭，风棹楚猿哀。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21294":["哭吕衡州六首 六","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["杜预春秋癖，扬雄着述精。","在时兼不语，终古定归名。","耒水波文细，湘江竹叶轻。","平生思风月，潜寐若爲情。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21295":["僧如展及韦载同游碧涧寺各赋诗予落句云他生莫忘灵山座满壁人名後会稀展共吟他生之句因话释氏缘会所以莫不凄然久之不十日而展公长逝惊悼返覆则他生岂有兆耶其间展公仍赋黄字五十韵飞札相示予方属和未毕自此不复撰成徒以四韵爲识","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["重吟前日他生句，岂料踰旬便隔生。","会拟一来身塔下，无因共绕寺廊竹。","紫毫飞札看犹湿，黄字新诗和未成。","纵使得如羊叔子，不闻兼记旧交情。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21296":["公安县远安寺水亭见展公题壁漂然泪流因书四韵","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["碧涧去年会，与师三两人。","今来见题壁，师已是前身。","芰叶迎僧夏，杨花度俗春。","空将数行泪，洒徧塔中尘。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21297":["寒食日毛空路示侄晦及从简","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["我昔孩提从我兄，我今衰白尔初成。","分明寄取原头路，百世长须此路行。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21298":["别孙村老人","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["年年渐觉老人稀，欲别孙翁泪满衣。","未死不知何处去，此身终向此原归。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21299":["和乐天刘家花","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["闲坊静曲同消日，泪草伤花不爲春。","徧问旧交零落尽，十人才有两三人。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21300":["褒城驿二首 一","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["容州诗句在褒城，几度经过眼暂明。","今日重看满衫泪，可怜名字已前生。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21301":["褒城驿二首 二","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["忆昔万株梨映竹，遇逢黄令醉残春。","梨枯竹尽黄令死，今日再来衰病身。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21302":["和乐天梦亡友刘太白同游二首 一","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["君诗昨日到通州。","万里知君一梦刘，闲坐思量小来事。","秪应元是梦中游。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21303":["和乐天梦亡友刘太白同游二首 二","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["老来东郡复西州，行处生尘爲丧刘。","纵使刘君魂魄在，也应至死不同游。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21304":["酬乐天见忆兼伤仲远","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["死别重泉閟，生离万里赊。","瘴侵新病骨，梦到故人家。","遥泪陈根草，闲收落地花。","庾公楼怅望，巴子国生涯。","河任天然曲，江随峡势斜。","与君皆直戆，须分老泥沙。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21305":["与乐天同葬杓直","元稹","五言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["元伯来相葬，山涛誓抚孤。","不知他日事，兼得似君无。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21306":["夜闲","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["感极都无梦，魂销转易惊。","风帘半钩落，秋月满牀明。","怅望临阶坐，沈吟遶树行。","孤琴在幽匣，时迸断弦声。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21307":["感小株夜合","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["纤干未盈把，高条才过眉。","不禁风苦动，偏受露先萎。","不分秋同尽，深嗟小便衰。","伤心落残叶，犹识合昏期。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21308":["醉醒","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["积善坊中前度饮，谢家诸婢笑扶行。","今宵还似当时醉，半夜觉来闻哭声。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21309":["追昔游","元稹","七言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["谢傅堂前音乐和，狗儿吹笛胆娘歌。","花园欲盛千场饮，水阁初成百度过。","醉摘樱桃投小玉，嬾梳丛鬓舞曹婆。","再来门馆唯相吊，风落秋池红叶多。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21310":["空屋题","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["朝从空屋里，骑马入空台。","尽日推闲事，还归空屋来。","月明穿暗隙，灯烬落残灰。","更想咸阳道，魂车昨夜回。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21311":["初寒夜寄卢子蒙","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["月是阴秋镜，寒爲寂寞资。","轻寒酒醒後，斜月枕前时。","倚壁思闲事，回灯检旧诗。","闻君亦同病，终夜远相悲。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21312":["城外回谢子蒙见谕","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["十里抚柩别，一身骑马回。","寒烟半堂影，烬火满庭灰。","稚女凭人问，病夫空自哀。","潘安寄新咏，仍是夜深来。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21313":["谕子蒙","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["抚稚君休感，无儿我不伤。","片云离岫远，双燕念巢忙。","大壑谁非水，华星各自光。","但令长有酒，何必谢家庄。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21314":["遣悲怀三首 一","元稹","七言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["谢公最小偏怜女，嫁与黔娄百事乖。","顾我无衣搜画箧，泥他沽酒拔金钗。","野蔬充膳甘长藿，落叶添薪仰古槐。","今日俸钱过十万，与君营奠复营斋。"],"韦丛，元稹妻，太子少保韦夏卿之幼女，封裴，元稹为校书郎时娶之，七年后韦氏卒，年二十七。元稹悼之，作《遣悲怀三首》。此为其一，追忆韦氏嫁后之贤淑与贫贱之共苦，于悼亡中写深痛。",[["1. **谢公**","东晋谢安，此借指韦夏卿。"],["2. **偏怜女**","偏怜之幼女，指韦丛。"],["3. **黔娄**","春秋时齐国高士，家贫，此元稹自喻。"],["4. **百事乖**","百事不顺。"],["5. **顾我**","看我。"],["6. **荩箧**","草编之箱箧。"],["7. **泥他**","软求他，缠着他。"],["8. **沽酒**","买酒。"],["9. **野蔬充膳**","野菜充作膳食。"],["10. **甘长藿**","甘于食长藿。藿，豆叶。"],["11. **落叶添薪**","落叶添作柴薪。"],["12. **仰古槐**","仰仗古槐之落叶。"],["13. **营奠**","营办祭奠。"],["14. **营斋**","营办斋僧。"],["1. **闲坐**","闲坐无事。"],["2. **悲君亦自悲**","悲君亦自悲。"],["3. **百年**","百年之寿。"],["4. **几多时**","几何时。"],["5. **邓攸无子**","晋邓攸，字伯道，避石勒乱，弃己子存侄，后竟无子，时人哀之“天道无知，使邓伯道无儿”。"],["6. **寻知命**","寻至于知命之年。"],["7. **潘岳悼亡**","晋潘岳，字安仁，妻亡，作《悼亡诗》三首。"],["8. **犹费词**","犹费词章。"],["9. **同穴**","同葬一穴，指死后合葬。"],["10. **窅冥**","深远幽暗之貌。"],["11. **何所望**","何所望。"],["12. **他生缘会**","来生之因缘相会。"],["13. **难期**","难以期望。"],["","14. **终夜长开眼**：整夜长开眼不眠。"],["15. **未展眉**","生前未展眉，多忧愁。"],["1. **戏言身后意**","戏言死后之事。"],["","2. **今朝都到眼前来**：今朝都到眼前。"],["3. **衣裳已施**","衣裳已经施舍。"],["4. **行看尽**","眼看将尽。"],["5. **针线犹存**","针线之物犹存。"],["6. **未忍开**","未忍打开。"],["7. **旧情**","昔日之情。"],["8. **怜婢仆**","怜惜婢仆。"],["9. **因梦送钱财**","因梦见而送钱财。"],["10. **此恨**","此死别之恨。"],["11. **贫贱夫妻**","贫贱之夫妻。"],["12. **百事哀**","百事可哀。"]],{"source":"周啸天","body":["二是写出了女性的可爱。元稹情诗所怀二人，属于不同类型的两种女性——艳诗所怀之双文女士，是一位才貌双全、情有独钟而命运不幸的女性，固然有值得读者深切同情和倾慕之处。悼亡诗所怀之韦丛夫人，虽文化不高，却是一位善良的主妇和一位贤惠的妻子，“悼亡诸诗所以特为佳作者，直以韦氏之不好虚荣，微之之尚未富贵。贫贱夫妻，关系纯洁，因能措意遣词，悉为真实之故”（陈寅恪）。","三是素朴而自然的描写。元稹情诗的好处是工于白描，长于生活细节的描写——如“顾我无衣搜荩箧，泥他沽酒拔金钗。野蔬充膳甘长蕾，落叶添薪仰古槐”，“衣裳已施行看尽，针线犹存未忍开。尚想日情怜婢仆，也曾因梦送钱财”（见其人之乐善好施），“检得旧书三四纸”（《六年春遣怀》其二，全篇关怀体贴中见夫妇相濡以沫的关系），“昔日戏言身后意，今朝都到眼前来”（戏言容易，经过方知滋味之难受也），“闲读道书慵未起（心不在焉也），水精帘下看梳头”（《离思》其二）等，是可以从诗想见诗中人的。","四是言出于衷，颇有警句，如“今日俸钱过十万，与君营奠复营斋”，宋欧阳修《泷冈阡表》云“祭而丰，不如养之薄也”，事异而情同，“诚知此恨人人有，贫贱夫妻百事哀”（回首患难夫妻寻常细事，但觉事事可哀，而当时不觉也），“唯将终夜长开眼，报答平生未展眉”（“长开眼”对“未展眉”，造语寻常本色中见奇崛匠心，意谓彻夜失眠，为伊憔悴，终不悔也）等等。情语而有警句，更易流传。"]},[],["https://github.com/chinese-poetry/chinese-poetry","《全唐诗》（清·曹寅等编，康熙扬州诗局本）"]],"open_21315":["遣悲怀三首 二","元稹","七言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["昔日戏言身後意，今朝皆到眼前来。","衣裳已施行看尽，针线犹存未忍开。","尚想旧情怜婢仆，也曾因梦送钱财。","诚知此恨人人有，贫贱夫妻百事哀。"],"此为《遣悲怀三首》之二，承前首追忆韦氏嫁后之贤淑，转写物在人亡之悲。诗以戏言成真起笔，以贫贱夫妻之哀作结，于悼亡中写至痛。",[["1. **戏言身后意**","戏言死后之事。"],["","2. **今朝都到眼前来**：今朝都到眼前。"],["3. **衣裳已施**","衣裳已经施舍。"],["4. **行看尽**","眼看将尽。"],["5. **针线犹存**","针线之物犹存。"],["6. **未忍开**","未忍打开。"],["7. **旧情**","昔日之情。"],["8. **怜婢仆**","怜惜婢仆。"],["9. **因梦送钱财**","因梦见而送钱财。"],["10. **此恨**","此死别之恨。"],["11. **贫贱夫妻**","贫贱之夫妻。"],["12. **百事哀**","百事可哀。"],["古评·《唐诗镜》","语到眞时不嫌其𤨏○梁人作昵媟语多出於淫长庆作昵媟语多出於恳梁人病重"]],{"source":"萧涤非","body":["> **出处**：本节主要据萧涤非撰“遣悲怀三首”鉴赏条，《唐诗鉴赏辞典》，上海辞书出版社，1983 年版，第 929—932 页。","此诗写物在人亡之悲。首联“昔日戏言身后意，今朝都到眼前来”起笔即以戏言成真写痛——昔日戏言身后之事，今朝都到眼前来。“戏言”二字写昔日之无心，“都到眼前”写今日之痛切，戏言成真，至痛在此。","颔联“衣裳已施行看尽，针线犹存未忍开”乃名句，写物在人亡——衣裳已经施舍，行看将尽；针线之物犹存，未忍打开。衣裳施尽，所以遗物不留；针线犹存，所以遗物犹在。一“已施”一“犹存”，写物之去留；一“行看尽”一“未忍开”，写情之哀痛。遗物或施或存，皆触目生悲。","颈联“尚想旧情怜婢仆，也曾因梦送钱财”承之写情——尚想旧情而怜惜婢仆，也曾因梦而送钱财。怜婢仆是因念及韦氏旧情，送钱财是因梦见韦氏。两件细事，写尽思念之深。","尾联“诚知此恨人人有，贫贱夫妻百事哀”乃全诗之结，亦千古名句——诚知此死别之恨人人皆有，然贫贱夫妻百事可哀。一“诚知”一“百事哀”，将个人之痛推至普遍之慨，而又特举贫贱夫妻，写其共苦之深、悼亡之痛。全诗于物在人亡中写至痛，为悼亡诗之绝唱。"]},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）"]],"open_21316":["遣悲怀三首 三","元稹","七言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["闲坐悲君亦自悲，百年都是几多时。","邓攸无子寻知命，潘岳悼亡犹费词。","同穴窅冥何所望，他生缘会更难期。","唯将终夜长开眼，报荅平生未展眉。"],"此为《遣悲怀三首》之三，总结前二首之悲，转以己之无子、之独处写悼亡之深痛。诗以邓攸、潘岳自喻，以同穴、他生写来生之望，终归于终夜开眼以报平生未展眉，为悼亡诗之绝唱。",[["1. **闲坐**","闲坐无事。"],["2. **悲君亦自悲**","悲君亦自悲。"],["3. **百年**","百年之寿。"],["4. **几多时**","几何时。"],["5. **邓攸无子**","晋邓攸，字伯道，避石勒乱，弃己子存侄，后竟无子，时人哀之“天道无知，使邓伯道无儿”。"],["6. **寻知命**","寻至于知命之年。"],["7. **潘岳悼亡**","晋潘岳，字安仁，妻亡，作《悼亡诗》三首。"],["8. **犹费词**","犹费词章。"],["9. **同穴**","同葬一穴，指死后合葬。"],["10. **窅冥**","深远幽暗之貌。"],["11. **何所望**","何所望。"],["12. **他生缘会**","来生之因缘相会。"],["13. **难期**","难以期望。"],["","14. **终夜长开眼**：整夜长开眼不眠。"],["15. **未展眉**","生前未展眉，多忧愁。"]],{"source":"萧涤非","body":["> **出处**：本节主要据萧涤非撰“遣悲怀三首”鉴赏条，《唐诗鉴赏辞典》，上海辞书出版社，1983 年版，第 929—932 页。","此诗总结悼亡之悲。首联“闲坐悲君亦自悲，百年都是几多时”起笔即写悲——闲坐悲君亦自悲，百年之寿都是几多时？上句写悲君兼自悲，下句写人生之短。一“亦”字，写出悲君与自悲之相连；一“几多时”之反问，写人生之短促，悲君之逝亦悲己之将逝。","颔联“邓攸无子寻知命，潘岳悼亡犹费词”乃名句，以古自喻——邓攸无子，寻至于知命之年；潘岳悼亡，犹费词章。邓攸、潘岳皆古人，一无子，一悼亡，元稹并之，以喻己之无子与悼亡。“寻知命”写己之将老，“犹费词”写悼亡之词虽多而难尽意。","颈联“同穴窅冥何所望，他生缘会更难期”承之写来生——同穴窅冥何所望？他生缘会更难期。死后同穴，窅冥中何所望？来生缘会，更难期望。一“何所望”一“更难期”，写来生之不可期，则今日之悲更切。","尾联“惟将终夜长开眼，报答平生未展眉”乃全诗之结，亦千古名句——惟将终夜长开眼，报答平生未展眉。“长开眼”谓终夜不寐，“未展眉”谓生前多忧。以终夜不寐报答生前之忧，沉痛之至。一“惟将”一“报答”，写尽悼亡之至痛。全诗于闲坐中写至悲，为悼亡诗之绝唱。蘅塘退士孙洙评此三首“古今悼亡诗充栋，终无出此三首范围者”，信然。"]},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21317":["旅眠","元稹","五言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["内外都无隔，帷屏不复张。","夜眠兼客坐，同在火炉牀。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21318":["除夜","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["忆昔岁除夜，见君花烛前。","今宵祝文上，重叠叙新年。","闲处低声哭，空堂背月眠。","伤心小儿女，撩乱火堆边。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21319":["感梦","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["行吟坐叹知何极，影绝魂销动隔年。","今夜商山馆中梦，分明同在後堂前。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21320":["合衣寝","元稹","五言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["良夕背灯坐，方成合衣寝。","酒醉夜未阑，几回颠倒枕。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21321":["竹簟","元稹","五言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["竹簟衬重茵，未忍都令卷。","忆昨初来日，看君自施展。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21322":["听庾及之弹乌夜啼引","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["君弹乌夜啼，我传乐府解古题。","良人在狱妻在闺，官家欲赦乌报妻。","乌前再拜泪如雨，乌作哀声妻暗语。","後人写出乌啼引，吴调哀弦声楚楚。","四五年前作拾遗，谏书不密丞相知。","谪官诏下吏驱遣，身作囚拘妻在远。","归来相见泪如珠，唯说闲宵长拜乌。","君来到舍是乌力，粧点乌盘邀女巫。","今君爲我千万弹，乌啼啄啄泪澜澜。","感君此曲有深意，昨日乌啼桐叶坠。","当时爲我赛乌人，死葬咸阳原上地。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21323":["梦井","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["梦上高高原，原上有深井。","登高意枯渴，愿见深泉冷。","裴回遶井顾，自照泉中影。","沈浮落井瓶，井上无悬绠。","念此瓶欲沈，荒忙爲求请。","遍入原上村，村空犬仍猛。","还来遶井哭，哭声通复哽。","哽噎梦忽惊，觉来房舍静。","灯焰碧胧胧，泪光疑冏冏。","锺声夜方半，坐卧心难整。","忽忆咸阳原，荒田万余顷。","土厚圹亦深，埋魂在深埂。","埂深安可越，魂通有时逞。","今宵泉下人，化作瓶相憬。","感此涕丸澜，丸澜涕沾领。","所伤觉梦间，便觉死生境。","岂无同穴期，生期谅绵永。","又恐前後魂，安能两知省。","寻环意无极，坐见天将昞。","吟此梦井诗，春朝好光景。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21324":["江陵三梦 一","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["平生每相梦，不省两相知。","况乃幽明隔，梦魂徒尔爲。","情知梦无益，非梦见何期。","今夕亦何夕，梦君相见时。","依稀旧粧服，晻淡昔容仪。","不道间生死，但言将别离。","分张碎针线，襵叠故幈帏。","抚稚再三嘱，泪珠千万垂。","嘱云唯此女，自叹总无儿。","尚念娇且騃，未禁寒与饥。","君复不憘事，奉身犹脱遗。","况有官缚束，安能长顾私。","他人生间别，婢仆多谩欺。","君在或有托，出门当付谁。","言罢泣幽噎，我亦涕淋漓。","惊悲忽然寤，坐卧若狂痴。","月影半床黑，虫声幽草移。","心魂生次第，觉梦久自疑。","寂默深想像，泪下如流澌。","百年永已诀，一梦何太悲。","悲君所娇女，弃置不我随。","长安远於日，山川云间之。","纵我生羽翼，网罗生絷维。","今宵泪零落，半爲生别滋。","感君下泉魄，动我临川思。","一水不可越，黄泉况无涯。","此怀何由极，此梦何由追。","坐见天欲曙，江风吟树枝。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21325":["江陵三梦 二","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["古原三丈穴，深葬一枝琼。","崩剥山门坏，烟绵坟草生。","久依荒陇坐，却望远村行。","惊觉满床月，风波江上声。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21326":["江陵三梦 三","元稹","杂言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["君骨久爲土，我心长似灰。","百年何处尽，三夜梦中来。","逝水良已矣，行云安在哉？","坐看朝日出，衆鸟双裴回。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21327":["张旧蚊帱","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["踰年间生死，千里旷南北。","家居无见期，况乃异乡国。","破尽裁缝衣，忘收遗翰墨。","独有缬纱帱，凭人远携得。","施张合欢榻，展卷双鸳翼。","已矣长空虚，依然旧颜色。","裴回将就寝，徙倚情何极。","昔透香田田，今无魂恻恻。","隙穿斜月照，灯背空床黑。","达理强开怀，梦啼还过臆。","平生贫寡欢，夭枉劳苦忆。","我亦距几时，胡爲自摧逼。","烛蛾焰中舞，蠒蚕丛上织。","燋烂各自求，他人顾何力。","多离因苟合，恶影当务息。","往事勿复言，将来幸前识。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21328":["独夜伤怀赠呈张侍御","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["烬火孤星灭，残灯寸焰明。","竹风吹面冷，檐雪坠阶声。","寡鹤连天呌，寒雏彻夜惊。","秪应张侍御，潜会我心情。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21329":["六年春遣怀八首 一","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["伤禽我是笼中鹤，沈劒君爲泉下龙。","重纩犹存孤枕在，春衫无复旧裁缝。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21330":["六年春遣怀八首 二","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["检得旧书三四纸，高低阔狭粗成行。","自言并食寻高事，唯念山深驿路长。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21331":["六年春遣怀八首 三","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["公无渡河音响绝，已隔前春复去秋。","今日闲窗拂尘土，残弦犹迸钿箜篌。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21332":["六年春遣怀八首 四","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["婢仆晒君余服用，娇痴稚女遶床行。","玉梳钿朵香胶解，尽日风吹玳瑁筝。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21333":["六年春遣怀八首 五","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["伴客销愁长日饮，偶然乘兴便醺醺。","怪来醒後傍人泣，醉里时时错问君。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21334":["六年春遣怀八首 六","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["我随楚泽波中梗，君作咸阳泉下泥。","百事无心值寒食，身将稚女帐前啼。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21335":["六年春遣怀八首 七","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["童稚痴狂撩乱走，绣球花仗满堂前。","病身一到繐帷下，还向临阶背日眠。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21336":["六年春遣怀八首 八","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["小於潘岳头先白，学取庄周泪莫多。","止竟悲君须自省，川流前後各风波。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21337":["荅友封见赠","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["荀令香销潘簟空，悼亡诗满旧屏风。","扶床小女君先识，应爲些些似外翁。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21338":["梦成之","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["烛暗船风独梦惊，梦君频问向南行。","觉来不语到明坐，一夜洞庭湖水声。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21339":["哭小女降真","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["雨点轻沤风复惊，偶来何事去何情。","浮生未到无生地，暂到人间又一生。"],"",[["古评·《唐诗镜》","一语痛絶"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）"]],"open_21340":["哭女樊","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["秋天净绿月分明，何事巴猿不賸鸣。","应是一声肠断去，不容啼到第三声。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21341":["哭女樊四十韵","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["逝者何由见，中人未达情。","马无生角望，猿有断肠鸣。","去伴投遐徼，来随梦险程。","四年巴养育，万里硖回萦。","病是他乡染，魂应远处惊。","山魈邪乱逼，沙虱毒潜婴。","母约看宁辨，余慵疗不精。","欲寻方次第，俄值疾充盈。","灯火徒相守，香花秪浪擎。","莲初开月梵，蕣已落朝荣。","魄散云将尽，形全玉尚莹。","空垂两行血，深送一枝琼。","秘祝休巫觋，安眠放使令。","旧衣和箧施，残药满瓯倾。","乳媪闲於社，医僧婗似酲。","悯渠身觉賸，讶佛力难争。","骑竹痴犹子，牵车小外甥。","等长迷过影，遥戏误啼声。","涴纸伤余画，扶床念试行。","独留呵面镜，谁弄倚墙筝。","忆昨工言语，怜初妙长成。","撩风妬鹦舌，凌露触兰英。","翠凤舆真女，红蕖捧化生。","秪忧嫌五浊，终恐向三清。","宿恶诸荤味，悬知衆物名。","环从枯树得，经认宝函盛。","愠怒偏憎数，分张雅爱平。","最怜贪栗妹，频救嬾书兄。","爲占娇饶分，良多眷恋诚。","别常回面泣，归定出门迎。","解怪还家晚，长将远信呈。","说人偷罪过，要我抱纵横。","腾蹋游江舫，攀缘看乐棚。","和蛮歌字拗，学妓舞腰轻。","迢遰离荒服，提携到近京。","未容夸伎俩，唯恨枉聪明。","往绪心千结，新丝鬓百茎。","暗窗风报晓，秋幌雨闻更。","败槿萧疎馆，衰杨破坏城。","此中临老泪，仍自哭孩婴。"],"生而不食荤血虎豹狨猿等皮毛尽恶斥之巴南所无之物及北而黙识其名者数辈",[["古评·《唐诗镜》","生而不食荤血虎豹狨猿等皮毛尽恶斥之巴南所无之物及北而黙识其名者数辈"],["古评·《唐诗镜》","语近俚而情痛"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）"]],"open_21342":["哭子十首 一","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["维鹈受刺因吾过，得马生灾念尔冤。","独在中庭倚闲树，乱蝉嘶噪欲黄昏。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21343":["哭子十首 二","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["才能辨别东西位，未解分明管带身。","自食自眠犹未得，九重泉路托何人。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21344":["哭子十首 三","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["尔母溺情连夜哭，我身因事有时悲。","锺声欲绝东方动，便是寻常上学时。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21345":["哭子十首 四","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["莲花上品生真界，兜率天中离世途。","彼此业缘多障碍，不知还得见儿无。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21346":["哭子十首 五","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["节量棃栗愁生疾，教示诗书望早成。","鞭扑校多怜校少，又缘遗恨哭三声。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21347":["哭子十首 六","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["深嗟尔更无兄弟，自叹予应绝子孙。","寂寞讲堂基址在，何人车马入高门。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21348":["哭子十首 七","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["往年鬓已同潘岳，垂老年教作邓攸。","烦恼数中除一事，自兹无复子孙忧。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21349":["哭子十首 八","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["长年苦境知何限，岂得因儿独丧明。","消遣又来缘尔母，夜深和泪有经声。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21350":["哭子十首 九","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["乌生八子今无七，猿呌三声月正孤。","寂寞空堂天欲曙，拂帘双燕引新雏。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21351":["哭子十首 十","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["频频子落长江水，夜夜巢边旧处栖。","若是愁肠终不断，一年添得一声啼。"],"数首顚倒思量婉转沉痛殆难为读",[["古评·《唐诗镜》","景逼情生"],["古评·《唐诗镜》","数首顚倒思量婉转沉痛殆难为读"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）"]],"open_21352":["感逝","元稹","七言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["头白夫妻分无子，谁令兰梦感衰翁。","三声啼妇卧床上，一寸断肠埋土中。","蜩甲暗枯秋叶坠，燕雏新去夜巢空。","情知此恨人皆有，应与暮年心不同。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21353":["妻满月日相唁","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["十月辛勤一月悲，今朝相见泪淋漓。","狂风落尽莫惆怅，犹胜因花压折枝。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21354":["代曲江老人百韵","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["何事花前泣，曾逢旧日春。","先皇初在镐，贱子正游秦。","拨乱干戈後，经文礼乐辰。","徽章悬象魏，貔虎画骐驎。","光武休言战，唐尧念睦姻。","琳琅铺柱础，葛藟茂河漘。","尚齿惇耆艾，搜材拔积薪。","裴王持藻镜，姚宋斡陶钧。","内史称张敞，苍生借寇恂。","名卿唯讲德，命士耻忧贫。","杞梓无遗用，蒭荛不忘询。","悬金收逸骥，鼓瑟荐嘉宾。","羽翼皆随凤，圭璋肯杂珉。","班行容济济，文质道彬彬。","百度依皇极，千门辟紫宸。","措刑非苟简，稽古蹈因循。","书谬偏求伏，诗亡远听申。","雄推三虎贾，羣擢八龙荀。","海外恩方洽，寰中教不泯。","儒林精阃奥，流品重清淳。","天净三光丽，时和四序均。","卑官休力役，蠲赋免艰辛。","蛮貊同车轨，乡原尽里仁。","帝途高荡荡，风俗厚誾誾。","暇日耕耘足，丰年雨露频。","戍烟生不见，村竖老犹纯。","耒耜勤千亩，牲牢奉六禋。","南郊礼天地，东野辟原畇。","校猎求初吉，先农卜上寅。","万方来合杂，五色瑞轮囷。","池籞呈朱鴈，坛场得白麟。","酹金光照耀，奠璧彩璘玢。","掉荡云门发，蹁跹鹭羽振。","集灵撞玉磬，和鼓奏金錞。","建簴崇牙盛，衔钟兽目嗔。","总干形屹崪，戛敔背嶙峋。","文物千官会，夷音九部陈。","鱼龙华外戏，歌舞洛中嫔。","佳节修酺礼，非时宴侍臣。","梨园明月夜，花萼艳阳晨。","李杜诗篇敌，苏张笔力匀。","乐章轻鲍照，碑板笑颜竣。","泰岳陪封禅，汾阴颂鬼神。","星移逐西顾，风暖助东巡。","浴德留汤谷，蒐畋过渭滨。","沸天雷殷殷，匝地毂辚辚。","沃土心逾炽，豪家礼渐湮。","老农羞荷锸，贪贾学垂绅。","曲艺争工巧，雕机变组紃。","青凫连不解，红粟朽相因。","山泽长孳货，梯航竞献珍。","翠毛开越巂，龙眼弊瓯闽。","玉馔薪然蜡，椒房烛用银。","铜山供横赐，金屋贮宜嚬。","班女恩移赵，思王赋感甄。","辉光随顾步，生死属摇唇。","世族功勳久，王姬宠爱亲。","街衢连甲第，冠盖拥朱轮。","大道垂珠箔，当垆踏锦茵。","轩车隘南陌，钟磬满西邻。","出入张公子，骄奢石季伦。","鸡场潜介羽，马埒并扬尘。","韬袖夸狐腋，弓弦尚鹿𦟘","紫绦牵白犬，绣䪜被花駰。","箭倒南山虎，鹰擒东郭㕙。","翻身迎过鴈，劈肘取廻鹑。","竟蓄朱公产，争藏邴氏缗。","桥桃矜马鹜，倚顿数牛犉。","齑鬬冬中韭，羹怜远处蓴。","万钱才下筯，五酘未称醇。","曲水闲销日，倡楼醉度旬。","探丸依郭解，投辖伴陈遵。","共谓长之泰，那知遽构屯。","奸心兴桀黠，凶丑比顽嚚。","斗柄侵妖彗，天泉化逆鳞。","背恩欺乃祖，连祸及吾民。","䝟貐当前路，鲸鲵得要津。","王师才业业，暴卒已䖜䖜。","杂虏同谋夏，宗周蹔去豳。","陵园深暮景，霜露下秋旻。","凤阙悲巢鵩，鵷行乱野麏。","华林荒茂草，寒竹碎贞筠。","村落空垣坏，城隍旧井堙。","破船沉古渡，战鬼聚阴磷。","振臂谁相应，攒眉独不伸。","毁容怀赤绂，混迹戴黄巾。","木梗随波荡，桃源斅隐沦。","弟兄书信断，鸥鹭往来驯。","忽遇山光澈，遥瞻海气真。","秘图推废[主]，後圣合经纶。","野杏浑休植，幽兰不复纫。","但惊心愤愤，谁恋水粼粼。","尽室离深洞，轻桡荡小䑳。","殷勤题白石，怅望出青苹。","梦寐平生在，经过处所新。","阮郎迷里巷，辽鹤记城闉。","虚过休明代，旋爲朽病身。","劳生常矻矻，语旧苦谆谆。","晚岁多衰柳，先秋愧大椿。","眼前年少客，无复昔时人。"],"如此长韵整称即佳",[["古评·《唐诗镜》","如此长韵整称即佳"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）"]],"open_21355":["开元观闲居酬吴士矩侍御三十韵","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["静习狂心尽，幽居道气添。","神编啓黄简，秘籙捧朱签。","烂熳烟霞驻，优游岁序淹。","登坛拥旄节，趋殿礼胡髯。","醮起彤庭烛，香开白玉匳。","结盟金劒重，斩魅宝刀銛。","禹步星纲动，焚符竈鬼詹。","冥搜呼直使，章奏役飞廉。","仙籍聊凭检，浮名复爲占。","赤诚祈皓鹤，绿发代青缣。","虚室常怀素，玄关屡引枮。","貂蝉徒自宠，鸥鹭不相嫌。","始悟身爲患，唯欣禄未恬。","龟龙恋淮海，鸡犬傍闾阎。","松笠新偏翠，山峰远更尖。","箫声吟茂竹，虹影逗虚檐。","初日先通牖，轻颸每透帘。","露盘朝滴滴，钩月夜纤纤。","已得餐霞味，应嗤食蓼甜。","工琴闲度昼，耽酒醉销炎。","几案随宜设，诗书逐便拈。","灌园多抱瓮，刈藿乍腰镰。","野鸟终难絷，鹪鹩本易厌。","风高云远逝，波骇鲤深潜。","邸第过从隔，蓬壶梦寐瞻。","所希颜颇练，谁恨突无黔。","思拙慙圭璧，词烦杂米盐。","谕锥言太小，求药意何谦。","语默君休问，行藏我讵兼。","狂歌终此曲，情尽口长箝。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21356":["病减逢春期白二十二辛大不至十韵","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["病与穷阴退，春从血气生。","寒肤渐舒展，阳脉乍虚盈。","就日临堦坐，扶牀履地行。","问人知面瘦，祝鸟愿身轻。","风暖牵诗兴，时新变卖声。","饥馋看药忌，闲闷点书名。","旧雪依深竹，微和动早萌。","推迁悲往事，疎数辨交情。","琴待嵇中散，杯思阮步兵。","世间除却病，何者不营营。"],"拈出眞趣非为客语故佳",[["古评·《唐诗镜》","拈出眞趣非为客语故佳"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）"]],"open_21357":["黄明府诗","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["少年曾痛饮，黄令苦飞觥。","席上当时走，马前今日迎。","依稀迷姓氏，积渐识平生。","故友身皆远，他乡眼暂明。","便邀连榻坐，兼共榜船行。","酒思临风乱，霜棱埽地平。","不堪深浅酌，贪怆古今情。","逦迤七盘路，坡陁数丈城。","花疑褒女笑，栈想武侯征。","一种埋幽石，老闲千载名。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21358":["酬翰林白学士代书一百韵","元稹","杂言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["昔岁俱充赋，同年遇有司。","八人称迥拔，两郡滥相知。","逸骥初翻步，鞲鹰暂脱羁。","远途忧地窄，高视觉天卑。","并入红兰署，偏亲白玉规。","近朱怜冉冉，伐木愿偲偲。","鱼鲁非难识，铅黄自嬾持。","心轻马融帐，谋夺子房帷。","秀发幽岩电，清澄隘岸陂。","九霄排直上，万里整前期。","勇赠栖鸾句，慙当古井诗。","多闻全受益，择善颇相师。","脱俗殊常调，潜工大有爲。","还醇凭酎酒，运智托围棊。","情会招车胤，闲行觅戴逵。","僧餐月灯阁，醵宴劫灰池。","胜概争先到，篇章竞出奇。","输赢论破的，点窜肯容丝。","山岫当街翠，墙花拂面枝。","莺声爱娇小，燕翼翫逶迤。","辔爲逢车缓，鞭缘趂伴施。","密携长上乐，偷宿静坊姬。","僻性慵朝起，新晴助晚嬉。","相欢常满目，别处鲜开眉。","翰墨题名尽，光阴听话移。","绿袍因醉典，乌帽逆风遗。","暗插轻筹箸，仍提小屈巵。","本弦才一举，下口已三迟。","逃席冲门出，归倡借马骑。","狂歌繁节乱，醉舞半衫垂。","散漫纷长薄，邀遮守隘岐。","几遭朝士笑，兼任巷童随。","苟务形骸达，浑将性命[推]。","何曾爱官序，不省计家资。","忽悟成虚掷，翻然叹未宜。","使回躭乐事，坚赴策贤时。","寝食都忘倦，园庐遂绝闚。","劳神甘戚戚，攻短过孜孜。","叶怯穿杨箭，囊藏透頴锥。","超遥望云雨，摆落占泉坻。","略削荒凉苑，搜求激直词。","那能作牛後，更拟助洪基。","唱第听鸡集，趋朝忘马疲。","内人舆御案，朝景丽神旗。","首被呼名姓，多慙冠等衰。","千官容眷盼，五色照离披。","鵷侣从兹洽，鸥情转自縻。","分张殊品命，中外却驱驰。","出入称金籍，东西侍碧墀。","鬬班云汹涌，开扇雉参差。","切愧寻常质，亲瞻咫尺姿。","日轮光照耀，龙服瑞葳蕤。","誓欲通愚謇，生憎效喔咿。","佞存真妾妇，谏死是男儿。","便殿承偏召，权臣惧挠私。","庙堂虽稷契，城社有狐狸。","似锦言应巧，如弦数易欺。","敢嗟身暂黜，所恨政无毗。","谬辱良由此，昇腾亦在斯。","再令陪宪禁，依旧履阽危。","使蜀常緜远，分台更嶮巇。","匿奸劳发掘，破党恶持疑。","斧刃迎皆碎，盘牙老未萎。","乍能还帝笏，讵忍折吾支。","虎尾元来险，圭文却类疵。","浮荣齐壤芥，闲气咏江蓠。","阙下殷勤拜，樽前啸傲辞。","飘沈委蓬梗，忠信敌蛮夷。","戏诮青云驿，讥题皓发祠。","贪过谷隐寺，留读岘山碑。","草没章台址，堤横楚泽湄。","野莲侵稻陇，亚柳压城陴。","遇物伤凋换，登楼思漫弥。","金攒嫩橙子，瑿泛远鸬鹚。","仰竹藤缠屋，苫茆荻补篱。","麪梨通蔕朽，火米带芒炊。","苇笋鍼筒束，鯾鱼箭羽鬐。","芋羹真底可，鲈鱠漫劳思。","北渚销魂望，南风着骨吹。","度梅衣色渍，食稗马蹄羸。","院榷和泥硷，官酤小麴醨。","讹音烦缴绕，轻俗丑威仪。","树罕贞心柏，畦丰卫足葵。","坳洼饶尰矮，游惰压庸缁。","病赛乌称鬼，巫占瓦代龟。","连阴蛙张王，瘴疟雪治医。","我正穷於是，君宁念及兹。","一篇从日下，双鲤送天涯。","坐捧迷前席，行吟忘结綦。","匡床铺错绣，几案踊灵芝。","形影同初合，参商喻此离。","扇因秋弃置，镜异月盈亏。","壮志诚难夺，良辰岂复追。","甯牛终夜永，潘鬓去年衰。","溟渤深那测，穹苍意在谁。","驭方轻騕褭，车肯重辛夷。","卧辙希濡沫，低颜受颔颐。","世情焉足怪，自省固堪悲。","溷鼠虚求洁，笼禽方讶饥。","犹胜忆黄犬，幸得早图之。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21359":["纪怀赠李六户曹崔二十功曹五十韵","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["昔冠诸生首，初因三道徵。","公卿碧墀会，名姓白麻称。","日月光遥射，烟霄志渐弘。","荣班联锦绣，谏纸赐牋藤。","便欲呈肝胆，何言犯股肱。","椎埋冲斗劒，消碎莹壶冰。","赤县才分务，青骢已迥乘。","因骑度海鹘，拟杀蔽天鹏。","缚虎声空壮，连鳌力未胜。","风翻波竟蹙，山压势逾崩。","戮辱徒相困，苍黄性不能。","酣歌离岘顶，负气入江陵。","华表当蟾魄，高楼挂玉绳。","角声悲掉荡，城影暗棱层。","军幕威容盛，官曹礼数兢。","心虽出云鹤，身尚触笼鹰。","竦足良甘分，排衙苦未曾。","通名参将校，抵掌见亲朋。","喣沫求涓滴，沧波怯斗升。","荒居邻鬼魅，羸马步殑㱥。","白草堂檐短，黄梅雨气蒸。","沾黏经汗席，颭闪尽油灯。","夜怯餐肤蚋，朝烦拂面蝇。","过从愁厌贱，专静畏猜仍。","旅寓谁堪托，官联自可凭。","甲科崔并骛，柱史李齐昇。","共展排空翼，俱遭激远矰。","他乡元易感，同病转相矜。","投分多然诺，忘言少爱憎。","誓将探胏腑，耻更辨淄渑。","会宿形骸远，论交意气增。","一心吞渤澥，戮力拔嵩恒。","语到磨圭角，疑消破弩症。","吹嘘期指掌，患难许檐簦。","铩翮鸾栖棘，藏锋箭在弸。","雪中方覩桂，木上莫施罾。","且泛夤沿水，兼过被病僧。","有时鞭欵段，尽日醉儚僜。","蹑屐看秧稻，敲船和采菱。","叉鱼江火合，唤客谷神应。","啸傲虽开口，幽忧复满膺。","望云鳍拨剌，透匣色腾凌。","每想潢池寇，犹稽赤族惩。","夔龙劳算画，貔虎带威棱。","逐鸟忠潜奋，悬旌意远凝。","弢弓思彻札，绊骥闷牵緪。","运甓调辛苦，闻鸡屡寝兴。","闲随人兀兀，梦听鼓鼟鼟。","班笔行看掷，黄陂莫漫澄。","骐驎高阁上，须及壮时登。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21360":["答姨兄胡灵之见寄五十韵","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["忆昔凤翔城，龆年是事荣。","理家烦伯舅，相宅尽吾兄。","诗律蒙亲授，朋游忝自迎。","题头筠管缦，教射角弓騂。","矮马駞鬉䪜，犁牛兽面缨。","对谈依赳赳，送客步盈盈。","米椀诸贤让，蠡杯大户倾。","一船席外语，三榼拍心精。","传盏加分数，横波掷目成。","华奴歌淅淅，媚子舞卿卿。","鬬设狂爲好，谁忧饮败名。","屠过隐朱亥，楼梦古秦嬴。","环坐唯便草，投盘暂废觥。","春郊才烂熳，夕鼓已砰轰。","荏苒移灰琯，喧阗勌塞兵。","糟浆闻渐足，书劒讶无成。","抵璧慙虚弃，弹珠觉用轻。","遂笼云际鹤，来狎谷中莺。","学问攻方苦，篇章兴太清。","囊疎萤易透，锥钝股多坑。","笔阵戈矛合，文房栋桷撑。","豆萁才敏儁，羽猎正峥嵘。","岐下寻时别，京师触处行。","醉眠街北庙，闲绕宅南营。","柳爱凌寒软，梅怜上番惊。","观松青黛笠，栏药紫霞英。","尽日听僧讲，通宵咏月明。","正耽幽趣乐，旋被宦途萦。","吏晋资材枉，留秦岁序更。","我髯黳数寸，君发白千茎。","芸阁怀铅暇，姑峰带雪晴。","何由身倚玉，空覩翰飞琼。","世道难於劒，谗言巧似笙。","但憎心可转，不解跽如擎。","始效神羊触，俄随旅鴈征。","孤芳安可驻，五鼎几时烹。","潦倒沉泥滓，欹危践矫衡。","登楼王粲望，落帽孟嘉情。","巫峡连天水，章台塞路荆。","雨摧渔火焰，风引竹枝声。","分作屯之蹇，那知困亦亨。","官曹三语掾，国器万寻桢。","逸杰雄姿迥，皇王雅论评。","蕙依潜可习，云合定谁令。","原燎逢冰井，鸿流值木罂。","智囊推有在，勇爵敢徒争。","迅拔看鹏举，高音侍鹤鸣。","所期人拭目，焉肯自佯盲。","铅钝丁宁淬，芜荒展转耕。","穷通须豹变，撄搏笑狼狞。","愧捧芝兰赠，还披胏腑呈。","此生如未死，未拟变平生。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21361":["酬许五康佐","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["奋迅君何晚，羁离我讵俦。","鹤笼闲警露，鹰缚闷牵韝。","蓬阁深沈省，荆门远慢州。","课书同吏职，旅宦各乡愁。","白日伤心过，沧江满眼流。","嘶风悲代马，喘月伴吴牛。","枯涸方穷辙，生涯不系舟。","猿啼三峡雨，蝉报两京秋。","珠玉慙新赠，芝兰忝旧游。","他年问狂客，须向老农求。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21362":["送崔侍御之岭南二十韵","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["汉法戎施幕，秦官郡置监。","萧何归旧印，鲍永授新衔。","币聘虽盈箧，泥章未破缄。","蛛悬丝缭绕，鹊报语詀諵。","再砺神羊角，重开宪简函。","鞶缨骢赳赳，緌佩绣縿縿。","逸翮怜鸿翥，离心觉刃劖。","联游亏片玉，洞照失明鉴。","遥想车登岭，那无泪满衫。","茅蒸连蟒气，衣渍度梅黬。","象鬬缘谿竹，猿鸣带雨杉。","飓风狂浩浩，韶石峻崭崭。","宿浦宜深泊，祈泷在至諴。","瘴江乘早度，毒草莫亲芟。","试蛊看银黑，排腥贵食咸。","菌须虫已蠹，菓重鸟先鵮。","冰莹怀贪水，霜清顾痛岩。","珠玑当尽掷，薏苡讵能谗。","荆俗欺王粲，吾生问季咸。","远书多不达，勤爲枉攕攕。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21363":["酬段丞与诸棊流会宿弊居见赠二十四韵","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["鸣局宁虚日，闲窗任废时。","琴书甘尽弃，园井讵能窥。","运石疑填海，争筹忆坐帷。","赤心方苦鬬，红烛已先施。","蛇势萦山合，鸿联度岭迟。","堂堂排直阵，衮衮逼羸师。","悬劫偏深猛，回征特险巇。","旁攻百道进，死战万般爲。","异日玄黄队，今宵黑白棊。","斫营看迥点，对垒重相持。","善败虽称怯，骄盈最易欺。","狼牙当必碎，虎口祸难移。","乘胜同三捷，扶颠望一词。","希因送目便，敢恃指纵奇。","退引防边策，雄吟斩将诗。","眠牀都浪置，通夕共忘疲。","晓雉风传角，寒藂雪压枝。","繁星收玉版，残月耀冰池。","僧请闻钟粥，宾催下药巵。","兽炎余炭在，蜡泪短光衰。","俛仰嗟陈迹，殷勤卜後期。","公私牵去住，车马各支离。","分作终身癖，兼从是事隳。","此中无限兴，唯怕俗人知。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21364":["酬窦校书二十韵","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["鸥鹭元相得，杯觞每共传。","芳游春烂熳，晴望月团圆。","调笑风流剧，论文属对全。","赏花珠并缀，看雪璧常连。","竹寺荒唯好，松斋小更怜。","潜投孟公辖，狂乞莫愁钱。","尘土抛书卷，枪筹弄酒权。","令夸齐箭道，力鬬抹弓弦。","但喜添樽满，谁忧乏桂然。","渐轻身外役，浑证饮中禅。","及我辞云陛，逢君仕圃田。","音徽千里断，魂梦两情偏。","足听猿啼雨，深藏马腹鞭。","官醪半清浊，夷馔杂腥膻。","顾影无依倚，甘心守静专。","那知暮江上，俱会落英前。","欵曲生平在，悲凉岁序迁。","鹤方同北渚，鸿又过南天。","丽句慙虚掷，沈机嬾强牵。","粗酬珍重意，工拙定相悬。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21365":["泛江翫月十二韵","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["楚塞分形势，羊公压大邦。","因依多士子，参画尽敦厖。","岳璧闲相对，荀龙自有双。","共将船载酒，同泛月临江。","远树悬金镜，深潭倒玉幢。","委波添净练，洞照灭凝釭。","阗咽沙头市，𤫩珑竹岸窗","巴童唱巫峡，海客话神泷。","已困连飞盏，犹催未倒缸。","饮荒情烂熳，风棹乐峥摐。","胜事他年忆，愁心此夜降。","知君皆逸韵，须爲应莛撞。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21366":["痁卧闻幕中诸公徵乐会饮因有戏呈三十韵","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["濩落因寒甚，沈阴与病偕。","药囊堆小案，书卷塞空斋。","胀腹看成鼓，羸形渐比柴。","道情忧易适，温瘴气难排。","治尰扶轻杖，开门立静街。","耳鸣疑暮角，眼暗助昏霾。","野竹连荒草，平陂接断崖。","坐隅甘对鵩，当路恐遭豺。","蛇蛊迷弓影，鵰翎落箭靫。","晚篱喧鬬雀，残菊半枯荄。","怅望悲回鴈，依迟傍古槐。","一生长苦节，三省讵行怪。","奔北翻成勇，司南却是呙。","穹苍真漠漠，风雨漫喈喈。","彼美犹谿女，其谁占馆娃。","诚知通有日，太极浩无涯。","布卦求无妄，祈天愿孔皆。","藏衰谋计拙，地僻往还乖。","况羡莲花侣，方欣绮席谐。","钿车迎妓乐，银翰屈朋侪。","白紵颦歌黛，同蹄坠舞钗。","纤身霞出海，艳脸月临淮。","筹箸随宜放，投盘止罚啀。","红娘留醉打，觥使及醒差。","顾我潜孤愤，何人想独怀。","夜灯然檞叶，冻雪堕塼堦。","坏壁虚缸倚，深炉小火埋。","鼠骄衔笔砚，被冷束筋骸。","毕竟图斟酌，先须遣疠痎。","枪旗如在手，那复敢崴㠢。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21367":["酬友封话旧叙怀十二韵","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["风波千里别，书信二年稀。","乍见悲兼喜，犹惊是与非。","身名判作梦，盃盏莫相违。","草馆同牀宿，沙头待月归。","春深乡路远，老去宦情微。","魏阙何由到，荆州且共依。","人欺翻省事，官冷易藏威。","但拟驯鸥鸟，无因用弩机。","开张图卷轴，颠倒醉衫衣。","蓴菜银丝嫩，鲈鱼雪片肥。","怜君诗似涌，赠我笔如飞。","会遣诸伶唱，篇篇入禁闱。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21368":["送王协律游杭越十韵","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["去去莫凄凄，余杭接会稽。","松门天竺寺，花洞若耶溪。","浣渚逢新艳，兰亭识旧题。","山经秦帝望，垒辨越王栖。","江树春常早，城楼月易低。","镜呈湖面出，云叠海潮齐。","章甫官人戴，蓴丝姹女提。","长干迎客闹，小市隔烟迷。","纸乱红蓝压，瓯凝碧玉泥。","荆南无抵物，来日爲侬携。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21369":["送东川马逢侍御使回十韵","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["风水荆门阔，文章蜀地豪。","眼青宾礼重，眉白衆情高。","思勇曾吞笔，投虚惯用刀。","词锋倚天劒，学海驾云涛。","南郡传纱帐，东方让锦袍。","旋吟新乐府，便续古离骚。","雪岸犹封草，春江欲满槽。","饯筵君置醴，随俗我餔糟。","莫叹巴三峡，休惊鬓二毛。","流年等头过，人世各劳劳。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21370":["酬卢秘书","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["偶有冲天气，都无处世才。","未容荣路稳，先蹋祸机开。","分久沉荆掾，慙经厕柏台。","理推愁易惑，乡思病难裁。","夜伴吴牛喘，春惊朔鴈回。","北人肠断送，西日眼穿颓。","唯望魂归去，那知诏下来。","涸鱼千丈水，殭燕一声雷。","幽匣提清镜，衰颜拂故埃。","梦云期紫阁，厌雨别黄梅。","亲戚迎时到，班行见处陪。","文工犹畏忌，朝士绝嫌猜。","新识蓬山杰，深交翰苑材。","连投珠作贯，独和玉成堆。","剧敌徒相轧，羸师亦自媒。","磨砻刮骨刃，翻掷委心灰。","恐被神明哭，忧爲造化灾。","私调破叶箭，定饮搴旗杯。","金宝潜砂砾，芝兰似草莱。","凭君毫发鉴，莫遣翳莓苔。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21371":["见人咏韩舍人新律诗因有戏赠","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["喜闻韩古调，兼爱近诗篇。","玉磬声声彻，金铃个个圆。","高疎明月下，细腻早春前。","花态繁於绮，闺情软似绵。","轻新便妓唱，凝妙入僧禅。","欲得人人伏，能教面面全。","延之苦拘检，摩诘好因缘。","七字排居敬，千词敌乐天。","殷勤闲太祝，好去老通川。","莫漫裁章句，须饶紫禁仙。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21372":["奉和权相公行次临阙驿逢仆射相公归朝俄顷分途因以奉赠诗十四韵","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["帝下赤霄符，搜求造化炉。","中台归内座，太一直南都。","黄霸乘轺入，王尊叱驭趋。","万人东道送，六纛北风驱。","栈阁才倾盖，关门已合繻。","贯鱼行逦迤，交马语踟蹰。","去速熊罴兆，来驰虎豹夫。","昔怜三易地，今讶两分途。","别路环山雪，离章运寸珠。","锋鋩断犀兕，波浪没蓬壶。","区宇声虽动，淮河孽末诛。","将军遥策画，师氏密訏谟。","汉上坛仍筑，褒西阵再图。","公方先二虏，何暇进愚儒。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21373":["酬乐天东南行诗一百韵","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["我病方吟越，君行已过湖。","去应缘直道，哭不爲穷途。","亚竹寒惊牖，空堂夜向隅。","暗魂思背烛，危梦怯乘桴。","坐痛筋骸憯，旁嗟物候殊。","雨蒸虫沸渭，浪涌怪睢盱。","索绠飘蚊蚋，蓬麻甃舳舻。","短檐苫稻草，微俸封渔租。","泥浦喧捞蛤，荒郊险鬬貙。","鲸吞近溟涨，猿闹接黔巫。","芒屩泅牛妇，丫头荡桨夫。","酢醅荷裹卖，醨酒水淋沽。","舞态翻鸜鹆，歌词咽鹧鸪。","夷音啼似笑，蛮语谜相呼。","江郭船添店，山城木竖郛。","吠声沙市犬，争食墓林乌。","犷俗诚堪惮，妖神甚可虞。","欲令仁渐及，已被疟潜图。","膳减思调鼎，行稀恐蠹枢。","杂蓴多剖鳝，和黍半蒸菰。","绿糉新菱实，金丸小木奴。","芋羹真蹔淡，䶉炙漫涂苏。","炰鼈那胜羜，烹鯄只似鲈。","楚风轻似蜀，巴地湿如吴。","气浊星难见，州斜日易晡。","通宵但云雾，未酉即桑榆。","瘴窟蛇休蛰，炎溪暑不徂。","伥魂阴叫啸，鵩貌昼踟蹰。","乡里家藏蛊，官曹世乏儒。","敛缗偷印信，传箭作符繻。","椎髻抛巾帼，鑹刀代辘轳。","当心鞙铜鼓，背弝射桑弧。","岂复民甿料，须将鸟兽驱。","是非浑并漆，词讼敢研朱。","陋室鴞窥伺，衰形蟒觊觎。","鬓毛霜点合，襟泪血痕濡。","倍忆京华伴，偏忘我尔躯。","谪居今共远，荣路昔同趋。","科试铨衡局，衙参典校厨。","月中分桂树，天上识昌蒲。","应召逢鸿泽，陪游值赐酺。","心唯撞卫磬，耳不乱齐竽。","海岱词锋截，皇王笔阵敺。","疾奔凌騕褭，高唱轧吴歈。","点检张仪舌，提携傅说图。","摆囊看利頴，开颔出明珠。","并取千人特，皆非十上徒。","白麻云色腻，墨诏电光麤。","衆口贪归美，何颜敢妬姝。","秦台纳红旭，酆匣洗黄垆。","谏猎宁规避，弹豪讵嗫嚅。","胏肝憎巧曲，蹊径绝萦迂。","誓遣朝纲振，忠饶翰苑输。","骥调方汗血，蝇点忽成卢。","遂谪栖遑掾，还飞送别盂。","痛嗟亲爱隔，颠望友朋扶。","狸病翻随鼠，骢羸返作驹。","物情良狥俗，时论太诬吾。","瓶罄罍偏耻，松摧柏自枯。","虎虽遭陷穽，龙不怕泥涂。","重喜登贤苑，方欣佐伍符。","判身入矛戟，轻敌比锱铢。","驿骑来千里，天书下九衢。","因教罢飞檄，便许到皇都。","舟败罂浮汉，骖疲杖过邘。","邮亭一萧索，烽候各崎岖。","馈饷人推辂，谁何吏执殳。","拔家逃力役，连鏁责逋诛。","防戍兄兼弟，收田妇与姑。","缣缃工女竭，青紫使臣纡。","望国参云树，归家满地芜。","破窗尘𡋯𡋯，幽院鸟呜","祖竹藂新笋，孙枝压旧梧。","晚花狂蛱蝶，残蒂宿茱萸。","始悟摧林秀，因衔避缴芦。","文房长遣闭，经肆未曾铺。","鵷鹭方求侣，鸱鸢已吓雏。","徵还何郑重，斥去亦须臾。","迢递投遐徼，苍黄出奥区。","通川诚有咎，湓口定无辜。","利器从头匣，刚肠到底刳。","薰莸任盛贮，稊稗莫超踰。","公干经时卧，锺仪几岁拘。","光阴流似水，蒸瘴热於鑪。","薄命知然也，深交有矣夫。","救焚期骨肉，投分刻肌肤。","二妙驰轩陛，三英咏袴襦。","李多嘲蝘蜓，窦数集蜘蛛。","数子皆奇货，唯予独朽株。","邯郸笑匍匐，燕蒯受揶揄。","嬾学三闾愤，甘齐百里愚。","耽眠稀醒素，凭醉少嗟吁。","学问徒爲尔，书题尽已于。","别犹多梦寐，情尚感凋枯。","近喜司戎健，寻伤掌诰徂。","士元名位屈，伯道子孙无。","旧好飞琼翰，新诗灌玉壶。","几催闲处泣，终作苦中娱。","廉蔺声相让，燕秦势岂俱。","此篇应绝倒，休漫捋髭须。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21374":["和乐天送客游岭南二十韵","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["我自离乡久，君那度岭频。","一杯魂惨澹，万里路艰辛。","江馆连沙市，泷船泊水滨。","骑田廻北顾，铜柱指南邻。","大壑浮三岛，周天过五均。","波心涌楼阁，规外布星辰。","狒狒穿筒格，猩猩置屐驯。","贡兼蛟女绢，俗重语儿巾。","舶主腰藏宝，黄家砦起尘。","歌锺排象背，炊爨上鱼身。","电白雷山接，旗红贼舰新。","岛夷徐市种，庙觋赵佗神。","鸢跕方知瘴，蛇苏不待春。","曙潮云斩斩，夜海火磷磷。","冠冕中华客，梯航异域臣。","果然皮胜锦，吉了舌如人。","风黖秋茅叶，烟埋晓月轮。","定应玄发变，焉用翠毛珍。","句漏沙须买，贪泉货莫亲。","能传稚川术，何患隐之贫。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21375":["献荥阳公诗五十韵","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["郑驿骑翩翩，丘门子弟贤。","文翁开学日，正礼骋途年。","骏骨黄金买，英髦绦帐延。","趋风皆蹀足，侍坐各差肩。","解榻招徐穉，登楼引仲宣。","凤攒题字扇，鱼落讲经筵。","盛气河包济，贞姿岳柱天。","臯夔当五百，邹鲁重三千。","科斗翻腾取，关雎教授先。","篆垂朝露滴，诗缀夜珠联。","逸礼多心匠，焚书旧口传。","陈遵修尺牍，阮瑀让飞牋。","中的颜初啓，抽毫踵未旋。","森罗万木合，属对百花全。","词海跳波涌，文星拂坐悬。","戴冯遥避席，祖逖後施鞭。","西蜀凌云赋，东阳咏月篇。","劲芟鳌足断，精贯蝨心穿。","浩汗神弥王，鹞扬兴欲仙。","冰壶通皓雪，绮树眇晴烟。","驱驾雷霆走，铺陈锦绣鲜。","情机登穾奥，流韵溢山川。","墨客膺潜服，谈宾膝误前。","张鳞定摧败，折角反矜怜。","句句推琼玉，声声播管弦。","纤新撩造化，澒洞斡陶甄。","卫磬琤鍧极，齐竽僭滥偏。","空虚慙炙輠，点窜许怀铅。","惫色秋来草，哀吟雨後蝉。","自伤魂惨沮，何暇思幽玄。","喜到樽罍侧，愁亲几案边。","菁华知竭矣，胏腑尚求旃。","抵滞浑成醉，徘徊转慕膻。","老叹才渐少，闲苦病相煎。","瓦砾难追琢，刍荛分弃捐。","漫劳成恳恳，那得美娟娟。","拙劣仍非速，迂愚且异专。","移时停笔砚，挥景乏戈鋋。","仪舌忻犹在，舒帷誓不褰。","会将连献楚，深耻谬游燕。","蒲有临书叶，韦充读易编。","沙须披见宝，经拟带耕田。","入雾长期闰，持朱本望研。","轮辕呈曲直，凿枘取方圆。","呼吸宁徒尔，沾濡岂浪然。","过箫资响亮，随水涨沦涟。","惜日看圭短，偷光恨壁坚。","勤勤雕朽木，细细导蒙泉。","传癖今应甚，头风昨已痊。","丹青公旧物，一爲变蚩妍。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21376":["酬乐天江楼夜吟稹诗因成三十韵","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["忽见君新句，君吟我旧篇。","见当巴徼外，吟在楚江前。","思鄙宁通律，声清遂扣玄。","三都时觉重，一顾世称妍。","排韵曾遥荅，分题几共联。","昔凭银翰写，今赖玉音宣。","布鼓随椎响，坯泥仰匠圆。","铃因风断续，珠与调牵緜。","阮籍惊长啸，商陵怨别弦。","猿羞啼月峡，鹤让警秋天。","志士潜兴感，高僧暂废禅。","兴飘沧海动，气合碧云连。","点缀工微者，吹嘘势特然。","休文徒倚槛，彦伯浪回船。","伎乐当筵唱，儿童满巷传。","改张思妇锦，腾跃贾人牋。","魏拙虚教出，曹风敢望痊。","定遭才子笑，恐赚学生癫。","裁什情何厚，飞书信不专。","隼猜鸿蓄缩，虎横犬迍邅。","水墨看虽久，琼瑶喜尚全。","才从鱼里得，便向市头悬。","夜置堂东序，朝铺座右边。","手寻韦欲绝，泪滴纸浑穿。","甘蔗销残醉，醍醐醒早眠。","深藏那遽灭，同咏苦无缘。","雅羡诗能圣，终嗟药未仙。","五千诚远道，四十已中年。","暗魄多相梦，衰容每自怜。","卒章还恸哭，蚊蚋溢山川。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21377":["酬乐天待漏入合见赠","元稹","杂言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["未勘银台契，先排浴殿关。","沃心因特召，[承]旨绝常班。","颭闪才人袖，呕鵶软举鐶。","宫花低作帐，云从积成山。","密视枢机草，偷瞻咫尺颜。","恩垂天语近，对久漏声闲。","丹陛曾同立，金銮恨独攀。","笔无鸿业润，袍愧紫文殷。","河水通天上，瀛州接世间。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21378":["酬乐天早春闲游西湖颇多野趣恨不得与微之同赏因思在越官重事殷镜湖之游或恐未暇因成十八韵见寄乐天前篇到时适会予亦宴镜湖南亭因述目前所睹以成酬荅末章亦示暇诚则势使之然亦欲粗爲恬养之赠耳","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["雁思欲回宾，风声乍变新。","各携红粉伎，俱伴紫垣人。","水面波疑縠，山腰虹似巾。","柳条黄大带，茭葑绿文茵。","雪尽才通屐，汀寒未有苹。","向阳偏晒羽，依岸小游鳞。","浦屿崎岖到，林园次第巡。","墨池怜嗜学，丹井羡登真。","雅叹游方盛，聊非意所亲。","白头辞北阙，沧海是东邻。","问俗烦江界，蒐畋想渭津。","故交音讯少，归梦往来频。","独喜同门旧，皆爲列郡臣。","三刀连地轴，一苇碍车轮。","尚阻青天雾，空瞻白玉尘。","龙因雕字识，犬爲送书驯。","胜事无穷境，流年有限身。","嬾将闲气力，争鬬野塘春。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21379":["江边四十韵","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["官借江边宅，天生地势坳。","敧危饶坏构，迢递接长郊。","怪鵩频栖息，跳蛙颇混殽。","总无篱缴绕，尤怕虎咆哮。","停潦鱼招獭，空仓鼠敌猫。","土虚烦穴蚁，柱朽畏藏蛟。","蛇虺吞檐雀，豺狼逐野麃。","犬惊狂浩浩，鸡乱响嘐嘐。","濩落贫甘守，荒凉秽尽包。","断帘飞熠燿，当户网蠨蛸。","曲突翻成沼，行廊却代庖。","桥横老颠枿，马病裛刍茭。","一一牀头点，连连砌下泡。","辱泥疑在绦，避雨想经崤。","相顾忧爲鼈，谁能复系匏。","誓心来利往，卜食过安爻。","何计逃昏垫，移文报旧交。","栋梁存伐木，苫盖愧分茅。","金琯排黄荻，琅玕褭翠梢。","花塼水面鬬，鸳瓦玉声敲。","方础荆山采，修掾郢匠刨。","隐锥雷震蛰，破竹箭鸣骹。","正寝初停午，频眠欲转胞。","囷圆收薄禄，厨敝备嘉肴。","各各人宁宇，双双燕贺巢。","高门受车辙，华廐称蒲捎。","尺寸皆随用，毫厘敢浪抛。","篾余笼白鹤，枝賸架青鵁。","制榻容筐篚，施关拒斗筲。","栏干防汲井，密室待持胶。","庭草佣工薙，园蔬稚子掊。","本图闲种植，那要择肥硗。","绿柚勤勤数，红榴个个抄。","池清漉螃蟹，瓜蠹拾𧏘蟊","晒篆看沙鸟，磨刀绽海鲛。","罗灰修药竈，筑垛阅弓弰。","散诞都由习，童蒙剩嬾教。","最便陶静饮，还作解愁嘲。","近浦闻归楫，遥城罢晓铙。","王孙如有问，须爲并挥鞘。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21380":["春六十韵","元稹","杂言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["节应寒灰下，春生返照中。","未能消积雪，已渐少回风。","迎气邦经重，斋诚帝念隆。","龙骧紫宸北，天压翠坛东。","仙仗摇佳彩，荣光荅圣衷。","便从威仰座，随入大罗宫。","先到璇渊底，偷穿玳瑁栊。","馆娃朝镜晚，太液晓冰融。","撩摘芳情徧，搜求好处终。","九霄浑可可，万姓尚忡忡。","昼漏频加箭，宵晖欲半弓。","驱令三殿出，乞与百蛮同。","直自方壶岛，斜临绝漠戎。","南巡暧珠树，西转丽崆峒。","度岭梅甘坻，潜泉脉暗洪。","悠悠铺塞草，冉冉着江枫。","蚕役投筐妾，耘催荷蓧翁。","既蒸难发地，仍送嬾归鸿。","约略环区宇，殷勤绮镐酆。","华山青黛扑，渭水碧沙蒙。","宿露清余霭，晴烟塞迥空。","燕巢才点缀，莺舌最惺愡。","腻粉梨园白，臙脂桃径红。","郁金垂嫩柳，罯画委高笼。","地甲门阑大，天开禁掖崇。","层台张舞凤，阁道架飞虹。","麴糵调神化，鵷鸾竭至忠。","歌锺齐锡宴，车服奖庸功。","俊造欣时用，闾阎贺岁丰。","倡楼妆㸌㸌，农野绿芃芃。","贵主骄矜盛，豪家恃赖雄。","偏沾打球彩，频得铸钱铜。","专杀擒杨若，殊恩赦邓通。","女孙新在内，婴稚近封公。","游衍关心乐，诗书对面聋。","盘筵饶异味，音乐斥庸工。","酒爱油衣浅，杯夸玛瑙烘。","挑鬟玉钗髻，刺绣宝装拢。","啓齿呈编贝，弹丝动削葱。","醉圆双媚靥，波溢两明瞳。","但赏欢无极，那知恨亦充。","洞房闲窈窕，庭院独葱茏。","谢砌萦残絮，班窗网曙虫。","望夫身化石，爲伯首如蓬。","顾我沉忧士，骑他老病骢。","静街乘旷荡，初日接曈曨。","饮败胏常渴，魂惊耳更聪。","虚逢好阳艳，其那苦昏懜。","僶俛还移步，持疑又省躬。","慵将疲顇质，漫走倦羸僮。","季月行当暮，良辰坐叹穷。","晋悲焚介子，鲁愿浴沂童。","燧改鲜妍火，阴繁晻澹桐。","瑞云低𢈁𢈁，香雨润蒙","药溉分窠数，篱栽备幼冲。","种莎怜见叶，护笋冀成筒。","有梦多爲蝶，因蒐定坐熊。","漂沈随坏芥，荣茂委苍穹。","震动风千变，晴和鹤一冲。","丁宁搴芳侣，须识未开丛。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21381":["月三十韵","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["蓂叶标新朔，霜豪引细辉。","白眉惊半隐，虹势讶全微。","凉魄潭空洞，虚弓雁畏威。","上弦何汲汲，佳色转依依。","绮幕残灯敛，妆楼破镜飞。","玲珑穿竹树，岑寂思幈帏。","坐爱规将合，行看望已几。","绦河冰监朗，黄道玉轮巍。","迥照偏琼砌，余光借粉闱。","泛池相皎洁，压桂共芳菲。","的的当歌扇，娟娟透舞衣。","殷勤入怀什，恳款堕云圻。","素液传烘盏，鸣琴荐碧徽。","椒房深肃肃，兰路霭霏霏。","翡翠通帘影，琉璃莹殿扉。","西园筵玳瑁，东壁射蛜蝛。","老将占天阵，幽人钓石矶。","荷锄元亮息，回櫂子猷归。","迢递同千里，孤高净九围。","从星作风雨，配日丽旌旗。","麟鬬宁徒设，蝇声岂浪讥。","司存委卿士，新拜出郊畿。","今古虽云极，亏盈不易违。","珠胎方夜满，清露忍朝曦。","渐减姮娥面，徐收楚练机。","卞疑雕璧碎，潘感竟牀稀。","捐箧辞班女，潜波蔽虙妃。","氛埃谁定灭，蟾兔杳难希。","须遣圆明尽，良嗟造化非。","如能付刀尺，别爲创璿玑。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21382":["饮致用神麴酒三十韵","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["七月调神麴，三春酿绿醽。","雕镌荆玉盏，烘透内丘缾。","试滴盘心露，疑添案上萤。","满尊凝止水，祝地落繁星。","翻陋琼浆浊，唯闻石髓馨。","冰壶通角簟，金镜彻云屏。","雪暎烟光薄，霜涵霁色泠。","蚌珠悬皎皛，桂魄倒瀴溟。","昼洒蝉将饮，宵挥鹤误聆。","琉璃惊太白，锺乳讶微青。","讵敢辞濡首，幷怜可鉴形。","行当遣俗累，便得造禅扃。","何惮说千日，甘从过百龄。","但令长泛蚁，无复恨漂萍。","胆壮还增气，机忘反自冥。","瓮眠思毕卓，糟籍忆刘伶。","髣髴中圣日，希夷夹大庭。","眼前须底物，座右任他铭。","刮骨都无痛，如泥未拟停。","残觞犹漠漠，华烛已荧荧。","真性临时见，狂歌半睡听。","喧阗争意气，调笑学娉婷。","酩酊焉知极，羇离忽暂宁。","鸡声催欲曙，蟾影照初醒。","咽绝鹃啼竹，萧撩雁去汀。","遥城传漏箭，乡寺响风铃。","楚泽一爲梗，尧阶屡变蓂。","醉荒非独此，愁梦几曾经。","每耻穷途哭，今那客泪零。","感君澄醴酒，不遣渭和泾。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21383":["感石榴二十韵","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["何年安石国，万里贡榴花。","迢递河源道，因依汉使槎。","酸辛犯葱岭，顦顇涉龙沙。","初到摽珍木，多来比乱麻。","深抛故园里，少种贵人家。","唯我荆州见，怜君胡地赊。","从教当路长，兼恣入檐斜。","绿叶裁烟翠，红英动日华。","新帘帬透影，疎牖烛笼纱。","委作金炉焰，飘成玉砌瑕。","乍惊珠缀密，终误绣帏奢。","琥珀烘梳碎，燕支嬾颊涂。","风翻一树火，电转五云车。","绦帐迎宵日，芙蕖绽早牙。","浅深俱隐映，前後各分葩。","宿露低莲脸，朝光借绮霞。","暗虹徒缴绕，濯锦莫周遮。","俗态能嫌旧，芳姿尚可嘉。","非专爱颜色，同恨阻幽遐。","满眼思乡泪，相嗟亦自嗟。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21384":["度门寺","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["北祖三禅地，西山万树松。","门临溪一带，桥映竹千重。","翦凿基阶正，包藏景气浓。","诸岩分院宇，双岭抱垣墉。","舍利开层墖，香炉占小峰。","道场居士置，经藏大师封。","太子知栽植，神王守要冲。","由旬排讲座，丈六写真容。","佛语迦陵说，僧行猛虎从。","修罗擡日拒，楼至拔霜锋。","画井垂枯朽，穿池救噞喁。","蕉非难败坏，槿喻暂丰茸。","宝界留遗事，金棺灭去踪。","鉢传烘玛瑙，石长翠芙蓉。","影帐纱全落，绳牀土半壅。","荒林迷醉象，危壁亚盘龙。","行色怜初月，归程待晓钟。","心源虽了了，尘世苦憧憧。","宿荫高声忏，斋粮幷力舂。","他生再来此，还愿总相逢。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21385":["大云寺二十韵","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["地胜宜台殿，山晴离垢氛。","现身千佛国，护世四王军。","碧耀高楼瓦，赬飞半壁文。","鹤林萦古道，雁墖没归云。","幡影中天扬，钟声下界闻。","攀萝极峰顶，游目到江濆。","驯鸽闲依缀，调猿静守羣。","虎行风捷猎，龙睡气氛氲。","获稻禅衣卷，烧畲劫火焚。","新英蜂采掇，荒草象耕耘。","鉢付灵童洗，香教善女熏。","果枝低罯罯，花雨泽雰雰。","示化维摩疾，降魔力士勳。","听经神变见，说偈鸟纷纭。","上境光犹在，深谿暗不分。","竹笼烟欲暝，松带日余曛。","真谛成知别，迷心尚有云。","多生沈五蕴，宿习乐三坟。","谕鹿车虽设，如蚕绪正棼。","且将平等义，还奉圣明君。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21386":["和友封题开善寺十韵","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["梁王开佛庙，云构岁时遥。","珠缀飞闲鸽，红泥落碎椒。","灯笼青焰短，香印白灰销。","古匣收遗施，行廊画本朝。","藏经沾雨烂，魔女捧花娇。","亚树牵藤阁，横查压石桥。","竹荒新笋细，池浅小鱼跳。","匠正琉璃瓦，僧锄芍药苗。","旋蒸茶嫩叶，偏把柳长条。","便欲忘归路，方知隐易招。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21387":["牡丹二首 一","元稹","五言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["簇蘂风频坏，裁红雨更新。","眼看吹落地，便别一年春。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21388":["牡丹二首 二","元稹","五言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["繁绿阴全合，衰红展渐难。","风光一擡举，犹得暂时看。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21389":["象人","元稹","五言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["被色空成象，观空色异真。","自悲人是假，那复假爲人。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21390":["与杨十二巨源卢十九经济同游大安亭各赋二物各爲五韵探得松石","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["片石与孤松，曾经物外逢。","月临栖鹤影，云抱老人峰。","蜀客君当问，秦官我旧封。","积膏当琥珀，新劫长芙蓉。","待补苍苍去，樛柯早变龙。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21391":["赋得春雪映早梅","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["飞舞先春雪，因依上番梅。","一枝方渐秀，六出已同开。","积素光逾密，真花节暗催。","抟风飘不散，见晛忽偏摧。","郢曲琴空奏，羌音笛自哀。","今朝两成咏，翻挟昔人才。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21392":["赋得玉巵无当","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["共惜连城宝，翻成无当巵。","讵慙君子贵，深讶巧工隳。","泛蚁功全小，如虹色不移。","可怜殊砾石，何计辨糟醨。","江海诚难满，盘筵莫忘施。","纵乖斟酌意，犹得对光仪。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21393":["赋得数蓂","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["将课司天历，先观近砌蓂。","一旬开应月，五日数从星。","桂满丛初合，蟾亏影渐零。","辨时长有素，数闰或余青。","坠叶推前事，新芽察未形。","尧年始今岁，方欲瑞千龄。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21394":["赋得九月尽","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["霜降三旬後，蓂余一叶秋。","玄阴迎落日，凉魄尽残钓。","半夜灰移琯，明朝帝御裘。","潘安过今夕，休咏赋中愁。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21395":["赋得雨後花","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["红芳怜静色，深与雨相宜。","余滴下纤蘂，残珠堕细枝。","浣花江上思，啼粉镜中窥。","念此低回久，风光幸一吹。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21396":["早归","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["春静晓风微，凌晨带酒归。","远山笼宿雾，高树影朝晖。","饮马鱼惊水，穿花露滴衣。","娇莺似相恼，含啭傍人飞。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21397":["晚秋","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["竹露滴寒声，离人晓思惊。","酒醒秋簟冷，风急夏衣轻。","寝倦解幽梦，虑闲添远情。","谁怜独欹枕，斜月透窗明。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21398":["送林复梦赴韦令辟","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["蜀路危於劒，怜君自坦途。","几回曾啖炙，千里远衔珠。","野性便荒饮，时风忌酒徒。","相门多礼让，前後莫相踰。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21399":["忆杨十二","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["杨子爱言诗，春天好咏时。","恋花从马滞，联句放杯迟。","日映含烟竹，风牵卧柳丝。","南山更多兴，须作白云期。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21400":["夜合","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["绮树满朝阳，融融有露光。","雨多疑濯锦，风散似分妆。","叶密烟蒙火，枝低绣拂墙。","更怜当暑见，留咏日偏长。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21401":["新竹","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["新篁才解箨，寒色已青葱。","冉冉偏凝粉，萧萧渐引风。","扶疎多透日，寥落未成丛。","惟有团团节，坚贞大小同。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21402":["秋相望","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["檐月惊残梦，浮凉满夏衾。","蠨蛸低户网，萤火度墙阴。","炉暗灯光短，牀空帐影深。","此时相望久，高树忆横岑。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21403":["春病","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["病来闲卧久，因见静时心。","残月晓窗迥，落花幽院深。","望山移坐榻，行药步墙阴。","车马门前度，遥闻哀苦吟。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21404":["山竹枝","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["深院虎溪竹，远公身自栽。","多慙折君节，扶我出山来。","贵宅安危步，难将混俗材。","还投辋川水，从作老龙回。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21405":["悟禅三首寄胡果 一","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["近闻胡隐士，潜认得心王。","不恨百年促，翻悲万劫长。","有修终有限，无事亦无殃。","慎莫通方便，应机不顿忘。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21406":["悟禅三首寄胡果 二","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["百年都几日，何事苦嚣然。","晚岁倦爲学，闲心易到禅。","病宜多宴坐，贫似少攀缘。","自笑无名字，因名自在天。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21407":["悟禅三首寄胡果 三","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["近见新章句，因知见在心。","春游晋祠水，晴上霍山岑。","问法僧当偈，还丹客赠金。","莫惊头欲白，禅观老弥深。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21408":["东台去","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["陶君喜不遇，予每爲君言。","今日东台去，澄心在陆浑。","旋抽随日俸，幷买近山园。","千万崔兼白，殷勤承主恩。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21409":["戴光弓","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["潞府筋角劲，戴光因合成。","因君怀胆气，赠我定交情。","不拟闲穿叶，那能枉始生。","唯调一只箭，飞入破聊城。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21410":["刘颇诗","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["一言感激士，三世义忠臣。","破瓮嫌妨路，烧庄耻属人。","迥分辽海气，闲蹋洛阳尘。","傥使权由我，还君白马津。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21411":["夜饮","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["灯火隔帘明，竹梢风雨声。","诗篇随意赠，杯酒越巡行。","漫唱江朝曲，闲徵药草名。","莫辞终夜饮，朝起又营营。"],"",[["古评·《唐诗镜》","三四语剏获"]],{"source":"管遗瑞","body":["最后两句是本诗的点题之笔：他们互相劝说今夜要通宵畅饮，因为明天早上大家又要分头身处官场，去过那种自己不愿意过的污浊的生活了。有此两句，诗歌的境界就提升到了一个新的认识层次，这也是此诗不同于一般饮酒诗歌之处。自然，通宵夜饮，这对于大家厌倦的官场只是一种消极回避的办法；而且通宵饮酒，酒醒之后，那无名的烦恼又会袭来，如此恶性循环，不仅官场的恶浊不会改变，就是自己的身心也会受到很大的摧残。但是，在那时这也是没有办法的事，于此我们也可以看见元稹所处的时代的官僚文士们生活的一个侧面。"]},[],["https://github.com/chinese-poetry/chinese-poetry","《全唐诗》（清·曹寅等编，康熙扬州诗局本）","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）"]],"open_21412":["襃城驿","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["严秦修此驿，兼涨驿前池。","已种千竿竹，又栽千树棃。","四年三月半，新笋晚花时。","怅望东川去，等闲题作诗。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21413":["闲二首 一","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["晻澹洲烟白，篱筛日脚红。","江喧过云雨，船泊打头风。","艇子收鱼市，鸦儿噪荻丛。","不堪堤上立，满眼是蚊虫。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21414":["闲二首 二","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["青衫经夏黕，白发望乡稠。","雨冷新秋簟，星稀欲曙楼。","连鸿尽南去，双鲤本东流。","北信无人寄，蝉声满树头。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21415":["欲曙","元稹","古风","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江堤阅暗流，漏鼓急残筹。","片月低城堞，稀星转角楼。","鹤媒华表上，{篦𥫗+鸟}鵊柳枝头","不爲来趋府，何因欲曙游。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21416":["寄胡灵之","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["早岁颠狂伴，城中共几年。","有时潜步出，连夜小亭眠。","月影侵牀上，花丛在眼前。","今宵正风雨，空宅楚江边。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21417":["夜雨","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["水怪潜幽草，江云拥废居。","雷惊空屋柱，电照满牀书。","竹瓦风频裂，茅檐雨渐疎。","平生沧海意，此去怯爲鱼。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21418":["酬李六醉後见寄口号","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["顿愈头风疾，因吟口号诗。","文章纷似绣，珠玉布如棊。","健羡觥飞酒，苍黄日映篱。","命童寒色倦，抚穉晚啼饥。","潦倒慙相识，平生颇自奇。","明公将有问，林下是灵龟。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21419":["归田","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["陶君三十七，挂绶出都门。","我亦今年去，商山淅岸邨。","冬修方丈室，春种桔橰园。","千万人间事，从兹不复言。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21420":["缘路","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["总是玲珑竹，兼藏浅漫溪。","沙平深见底，石乱不成泥。","烟火遥邨落，桑麻隔稻畦。","此中如有问，甘被到头迷。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21421":["诮卢戡与予数约游三寺戡独沈醉而不行","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["乘兴无羁束，闲行信马蹄。","路幽穿竹远，野迥望云低。","素帚茅花乱，圆珠稻实齐。","如何卢进士，空恋醉如泥。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21422":["遣春三首 一","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["杨公三不惑，我惑两般全。","逢酒判身病，拈花尽意怜。","水生低岸没，梅蹙小珠连。","千万红颜辈，须惊又一年。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21423":["遣春三首 二","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["柳眼开浑尽，梅心动已阑。","风光好时少，杯酒病中难。","学问慵都废，声名老更判。","唯余看花伴，未免忆长安。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21424":["遣春三首 三","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["失却游花伴，因风浪引将。","柳堤遥认马，梅径误寻香。","晚景行看谢，春心渐欲狂。","园林都不到，何处枉风光。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21425":["岁日","元稹","五言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["一日今年始，一年前事空。","凄凉百年事，应与一年同。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21426":["湘南登临湘楼","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["高处望潇湘，花时万井香。","雨余怜日嫩，岁闰觉春长。","霞刹分危牓，烟波透远光。","情知楼上好，不是仲宣乡。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21427":["晚宴湘亭","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["晚日宴清湘，晴空走艳阳。","花低愁露醉，絮起觉春狂。","舞旋红裙急，歌垂碧袖长。","甘心出童羖，须一尽时荒。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21428":["酒醒","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["饮醉日将尽，醒时夜已阑。","暗灯风焰晓，春席水窗寒。","未解萦身带，犹倾坠枕冠。","呼儿问狼藉，疑是梦中欢。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21429":["独游","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["远地难逢侣，闲人且独行。","上山随老鹤，接酒待残鸎。","花当西施面，泉胜卫玠清。","鹈鹕满春野，无限好同声。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21430":["洞庭湖","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["人生除泛海，便到洞庭波。","驾浪沉西日，吞空接曙河。","虞巡竟安在，轩乐讵曾过。","唯有君山下，狂风万古多。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21431":["雪天","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["故乡千里梦，往事万重悲。","小雪沈阴夜，闲窗老病时。","独闻归去鴈，偏咏别来诗。","惭愧红妆女，频惊两鬓丝。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21432":["赠熊士登","元稹","五言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["平生本多思，况复老逢春。","今日梅花下，他乡值故人。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21433":["别岭南熊判官","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["十年常远道，不忍别离声。","况复三巴外，仍逢万里行。","桐花新雨气，梨叶晚春晴。","到海知何日，风波从此生。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21434":["水上寄乐天","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["眼前明月水，先入汉江流。","汉水流江海，西江过庾楼。","庾楼今夜月，君岂在楼头。","万一楼头望，还应望我愁。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21435":["夏阳亭临望寄河阳侍御尧","元稹","五言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["望远音书绝，临川意绪长。","殷勤眼前水，千里到河阳。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21436":["日高睡","元稹","五言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["隔是身如梦，频来不爲名。","怜君近南住，时得到山行。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21437":["辋川","元稹","五言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["世累爲身累，闲忙不自由。","殷勤辋川水，何事出山流。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21438":["天坛归","元稹","五言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["爲结区中累，因辞洞里花。","还来旧城郭，烟火万人家。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21439":["雨後","元稹","五言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["倦寝数残更，孤灯暗又明。","竹梢余雨重，时复拂帘惊。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21440":["晴日","元稹","五言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["多病苦虚羸，晴明强展眉。","读书心绪少，闲卧日长时。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21441":["直台","元稹","五言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["麋入神羊队，乌惊海鹭眠。","仍教百余日，迎送直厅前。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21442":["行宫","元稹","五言绝句","约元和、长庆间","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["寥落古行宫，宫花寂寞红。","白头宫女在，闲坐说玄宗。"],"行宫，指洛阳上阳宫，玄宗时事多在此。元稹过之，见宫花寂寞、白头宫女，因作此诗以寄盛衰之慨。诗以寥寥二十字，写尽开元天宝之盛衰，为元稹五绝之冠。",[["1. **行宫**","皇帝出行之宫，此指洛阳上阳宫。"],["2. **寥落**","寂寞寥落。"],["3. **宫花**","宫中之花。"],["4. **寂寞红**","寂寞而自红。"],["5. **白头宫女**","白发之宫女，玄宗时入宫者。"],["6. **闲坐**","闲坐无事。"],["7. **说玄宗**","说玄宗时事。"]],{"source":"本节主要据周锡䪖撰“行宫”鉴赏条，《唐诗鉴赏辞典》，上海辞书出版社，1983 年版，第 932—933 页。","body":["此诗写盛衰之慨。前二句“寥落古行宫，宫花寂寞红”写行宫之景——寥落之古行宫，宫花寂寞而自红。“寥落”写行宫之衰，“寂寞红”写宫花之自开。宫花不知人之寥落，仍自寂寞而红，愈见寥落之甚。一“古”一“红”，写出时间之久与生命之续，盛衰之慨见焉。","后二句“白头宫女在，闲坐说玄宗”乃全诗之眼——白头宫女犹在，闲坐而说玄宗时事。“白头宫女”是玄宗时入宫者，至今已白头，时间之久可见；“闲坐”写其无事之寂；“说玄宗”写其追忆盛时。白头宫女之闲坐说玄宗，是衰中之盛，亦盛中之衰，盛衰之慨深焉。","全诗二十字，以寥落行宫、寂寞宫花、白头宫女、闲坐说玄宗四层写盛衰之慨。洪迈《容斋随笔》评此诗“语少意足，有无穷之味”，潘德舆《养一斋诗话》谓“寂寞红”三字尤妙。全诗语浅意深，为元稹五绝之冠，亦盛唐怀古绝句之佳作。"]},[["白头宫女在，闲坐说玄宗。","写盛衰之慨之千古名句。"],["寥落古行宫，宫花寂寞红。","写行宫寥落之名句。"]],["https://github.com/chinese-poetry/chinese-poetry","周锡䪖撰“行宫”鉴赏条，《唐诗鉴赏辞典》，上海辞书出版社，1983 年版，第 932—933 页","洪迈《容斋随笔》评此诗“语少意足，有无穷之味”","潘德舆《养一斋诗话》评此诗","袁行霈主编《中国文学史》第二卷，高等教育出版社，1999 年版，论元稹五绝","《全唐诗》（清·曹寅等编，康熙扬州诗局本）"]],"open_21443":["醉行","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["秋风方索漠，霜貌足暌携。","今日骑骢马，街中醉蹋泥。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21444":["指巡胡","元稹","五言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["遣闷多凭酒，公心只仰胡。","挺身唯直指，无意独欺愚。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21445":["饮新酒","元稹","五言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["闻君新酒熟，况值菊花秋。","莫怪平生志，图销尽日愁。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21446":["香球","元稹","五言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["顺俗唯团转，居中莫动摇。","爱君心不恻，犹讶火长烧。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21447":["景申秋八首 一","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["年年秋意绪，多向雨中生。","渐欲烟火近，稍怜衣服轻。","咏诗闲处立，忆事夜深行。","濩落寻常惯，凄凉别爲情。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21448":["景申秋八首 二","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["蚊幌雨来卷，烛蛾灯上稀。","啼儿冷秋簟，思妇问寒衣。","帘断萤火入，窗明蝙蝠飞。","良辰日夜去，渐与壮心违。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21449":["景申秋八首 三","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["嗢嗢檐溜凝，丁丁窗雨繁。","枕倾筒簟滑，幔颭案灯翻。","唤魇儿难觉，吟诗婢苦烦。","强眠终不着，闲卧暗消魂。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21450":["景申秋八首 四","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["瓶泻高檐雨，窗来激箭风。","病憎灯火暗，寒觉薄帏空。","婢报樵苏竭，妻愁院落通。","老夫慵计数，教想蔡城东。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21451":["景申秋八首 五","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["风头难着枕，病眼厌看书。","无酒销长夜，回灯照小余。","三元推废王，九曜入乘除。","廊庙应多算，参差斡太虚。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21452":["景申秋八首 六","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["经雨篱落坏，入秋田地荒。","竹垂哀折节，莲败惜空房。","小片慈菇白，低丛柚子黄。","眼前撩乱辈，无不是同乡。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21453":["景申秋八首 七","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["雨柳枝枝弱，风光片片斜。","蜻蜓怜晓露，蛱蝶恋秋花。","饥啅空篱雀，寒栖满树鸦。","荒凉池馆内，不似有人家。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21454":["景申秋八首 八","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["病苦十年後，连阴十日余。","人方教作鼠，天岂遣爲鱼。","鲛绽酆城劒，虫凋鬼火书。","出闻泥泞尽，何地不摧车。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21455":["遣行十首 一","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["惨切风雨夕，沉吟离别情。","燕辞前日社，蝉是每年声。","暗泪深相感，危心亦自惊。","不如元不识，俱作路人行。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21456":["遣行十首 二","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["十五年前事，恓惶无限情。","病僮更借出，羸马共驰声。","射叶杨才破，闻弓鴈已惊。","小年辛苦学，求得苦辛行。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21457":["遣行十首 三","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["徙倚檐宇下，思量去住情。","暗萤穿竹见，斜雨隔窗声。","就枕回转数，闻鸡撩乱惊。","一家同草草，排比送君行。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21458":["遣行十首 四","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["已怆朋交别，复怀儿女情。","相兄亦相旧，同病又同声。","白发年年剩，秋蓬处处惊。","不堪身渐老，频送异乡行。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21459":["遣行十首 五","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["塞上风雨思，城中兄弟情。","北随鵷立位，南送鴈来声。","遇适尤兼恨，闻书喜复惊。","唯应遥料得，知我伴君行。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21460":["遣行十首 六","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["暮欲歌吹乐，暗冲泥水情。","稻花秋雨气，江石夜滩声。","犬吠穿篱出，鸥眠起水惊。","愁君明月夜，独自入山行。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21461":["遣行十首 七","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["七过襃城驿，回回各爲情。","八年身世梦，一种水风声。","寻觅诗章在，思量岁月惊。","更悲西塞别，终夜绕池行。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21462":["遣行十首 八","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["襃县驿前境，曲江池上情。","南堤衰柳意，西寺晚钟声。","云水兴方远，风波心已惊。","可怜皆老大，不得自由行。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21463":["遣行十首 九","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["见说巴风俗，都无汉性情。","猿声芦管调，羌笛竹鸡声。","迎候人应少，平安火莫惊。","每逢危栈处，须作贯鱼行。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21464":["遣行十首 十","元稹","乐府","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["闻道阴平郡，翛然古戍情。","桥兼麋鹿蹋，山应鼓鼙声。","羌妇梳头紧，蕃牛护尾惊。","怜君闲闷极，只傍白江行。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21465":["生春二十首 一","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["何处生春早，春生云色中。","笼葱闲着水，晻淡欲随风。","度晓分霞态，余光庇雪融。","晚来低漠漠，浑欲泥幽丛。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21466":["生春二十首 二","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["何处生春早，春生漫雪中。","浑无到地片，唯逐入楼风。","屋上些些薄，池心旋旋融。","自悲销散尽，谁假入兰丛。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21467":["生春二十首 三","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["何处生春早，春生霁色中。","远林横返照，高树亚东风。","水冻霜威庇，泥新地气融。","渐知残雪薄，杪近最怜丛。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21468":["生春二十首 四","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["何处生春早，春生曙火中。","星围分暗陌，烟气满晴风。","宫树栖鵶乱，城楼带雪融。","竞排阊阖侧，珂伞自相丛。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21469":["生春二十首 五","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["何处生春早，春生晓禁中。","殿阶龙斾日，漏阁宝筝风。","药树香烟重，天颜瑞气融。","柳梅浑未觉，青紫已丛丛。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21470":["生春二十首 六","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["何处生春早，春生江路中。","雨移临浦市，晴候过湖风。","芦笋锥犹短，凌澌玉渐融。","数宗船载足，商妇两眉丛。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21471":["生春二十首 七","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["何处生春早，春生野墅中。","病翁闲向日，征妇嬾成风。","斫筤天虽暖，穿区冻未融。","鞭牛县门外，争土盖蚕丛。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21472":["生春二十首 八","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["何处生春早，春生冰岸中。","尚怜扶腊雪，渐觉受东风。","织女云桥断，波神玉貌融。","便成呜咽去，流恨与莲丛。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21473":["生春二十首 九","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["何处生春早，春生柳眼中。","芽新才绽日，茸短未含风。","绿误眉心重，黄惊蜡泪融。","碧条殊未合，愁绪已先丛。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21474":["生春二十首 十","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["何处生春早，春生梅援中。","蘂排难犯雪，香乞拟来风。","陇迥羌声怨，江遥客思融。","年年最相恼，缘未有诸丛。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21475":["生春二十首 十一","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["何处生春早，春生鸟思中。","鹊巢移旧岁，䳒羽旋高风。","鸿鴈惊沙暖，鸳鸯爱水融。","最怜双翡翠，飞入小梅丛。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21476":["生春二十首 十二","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["何处生春早，春生池榭中。","镂琼冰陷日，文縠水廻风。","柳爱和身动，梅愁合树融。","草芽犹未出，挑得小萱丛。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21477":["生春二十首 十三","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["何处生春早，春生稚戏中。","乱骑残爆竹，争唾小旋风。","駡雨愁妨走，呵冰喜旋融。","女儿针线尽，偷学五辛丛。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21478":["生春二十首 十四","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["何处生春早，春生人意中。","晓妆虽近火，晴戏渐怜风。","暗入心情嬾，先添酒思融。","预知花好恶，偏在最深丛。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21479":["生春二十首 十五","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["何处生春早，春生半睡中。","见灯如见雾，闻雨似闻风。","开眼犹残梦，擡身便恐融。","却成双翅蝶，还绕庳花丛。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21480":["生春二十首 十六","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["何处生春早，春生晓镜中。","手寒匀面粉，鬟动倚帘风。","宿雾梅心滴，朝光幕上融。","思牵梳洗嬾，空拔绿丝丛。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21481":["生春二十首 十七","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["何处生春早，春生绮户中。","玉栊穿细日，罗幔张轻风。","柳软腰支嫩，梅香密气融。","独眠傍妬物，偷铲合欢丛。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21482":["生春二十首 十八","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["何处生春早，春生老病中。","土膏蒸足肿，天暖痒头风。","似觉肌肤展，潜知血气融。","又添新一岁，衰白转成丛。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21483":["生春二十首 十九","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["何处生春早，春生客思中。","旅魂惊北鴈，乡信是东风。","纵有心灰动，无由鬓雪融。","未知开眼日，空绕未开丛。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21484":["生春二十首 二十","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["何处生春早，春生蒙雨中。","裛尘微有气，拂面细如风。","柳误啼珠密，梅惊粉汗融。","满空愁淡淡，应豫忆芳丛。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21485":["嘉陵水","元稹","五言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["尔是无心水，东流有恨无。","我心无说处，也共尔何殊。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21486":["漫天岭赠僧","元稹","五言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["五上两漫天，因师忏业缘。","漫天无尽日，浮世有穷年。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21487":["百牢关","元稹","五言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["天上无穷路，生期七十间。","那堪九年内，五度百牢关。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21488":["二月十九日酬王十八全素","元稹","五言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["君念世上川，嗟予老瘴天。","那堪十日内，又长白头年。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21489":["荥阳郑公以稹寓居严茅有池塘之胜寄诗四首因有意献","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["激射分流阔，湾环此地多。","暂停随梗浪，犹阅败霜荷。","恨阻还江势，思深到海波。","自伤才畎浍，其奈赠珠何。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21490":["酬乐天寄蕲州簟","元稹","五言古诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["蕲簟未经春，君先拭翠筠。","知爲热时物，预与瘴中人。","碾玉连心润，编牙小片珍。","霜凝青汗简，冰透碧游鳞。","水魄轻涵黛，琉璃薄带尘。","梦成伤冷滑，惊卧老龙身。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21491":["酬李浙西先因从事见寄之作","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["近日金銮直，亲於汉珥貂。","内人传帝命，丞相让吾僚。","浙郡悬旌远，长安谕日遥。","因君蘂珠赠，还一梦烟霄。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21492":["酬周从事望海亭见寄","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["年老无流辈，行稀足薜萝。","热时怜水近，高处见山多。","衣袖长堪舞，喉咙转解歌。","不辞狂复醉，人世有风波。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21493":["代杭民答乐天","元稹","五言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["翠幕笼斜日，朱衣俨别筵。","管弦凄欲罢，城郭望依然。","路溢新城市，农开旧废田。","春坊幸无事，何惜借三年。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21494":["杏园","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["浩浩长安车马尘，狂风吹送每年春。","门前本是虚空界，何事栽花误世人。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21495":["菊花","元稹","七言绝句","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["秋丛绕舍似陶家，遍绕篱边日渐斜。","不是花中偏爱菊，此花开尽更无花。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21496":["酬哥舒大少府寄同年科第","元稹","七言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["前年科第偏年少，未解知羞最爱狂。","九陌争驰好鞍马，八人同着彩衣裳。","自言行乐朝朝是，岂料浮生渐渐忙。","赖得官闲且疎散，到君花下忆诸郎。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21497":["幽栖","元稹","七言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["野人自爱幽栖所，近对长松远是山。","尽日望云心不系，有时看月夜方闲。","壶中天地乾坤外，梦里身名旦暮间。","辽海若思千岁鹤，且留城市会飞还。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_21498":["清都春霁寄胡三吴十一","元稹","七言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["蘂珠宫殿经微雨，草树无尘耀眼光。","白日当空天气暖，好风飘树柳阴凉。","蜂怜宿露攒芳久，燕得新泥拂户忙。","时节催年春不住，武陵花谢忆诸郎。"],"黄庭内景经太上大道玉宸君闲居蕋珠作七言秘要经仙宫中有寥阳之殿蕋珠之阙李白诗传诗蕋珠宫潘岳赋微雨新晴六",[["古注·《御选唐诗》","黄庭内景经太上大道玉宸君闲居蕋珠作七言秘要经仙宫中有寥阳之殿蕋珠之阙李白诗传诗蕋珠宫潘岳赋微雨新晴六合清朗王褒文香随微雨自洒风尘"],["古注·《御选唐诗》","庾信赋草树溷淆枝格相交梁武帝歌草树非一香陆云赋函夏无尘海外有谧徐陵诗石路本无尘魏文帝诏前于阗所上孔雀尾万枝以为金根车盖遥望耀人眼"],["古注·《御选唐诗》","班固荅賔戏未仰天庭而覩白日也谢眺诗白日丽飞甍韩凭妻诗日出当心储光羲诗山势当空出礼记孟春之月天气下降陶潜诗今日天气佳江淹诗南中气候暖"],["古注·《御选唐诗》","陶潜诗微雨从东来好风与之俱文士传𥞇康性絶巧能鍜家有一栁树乃激水圜之夏天甚凉居其下遨逰及鍜魏文帝诗栁垂重绿隂"],["古注·《御选唐诗》","方言蜂燕赵之间谓之蠓螉或谓之蚴蜕唐太宗诗宿露足朝烟埤雅蜂采取百芳酿蜜其房如脾谓之蜜脾韵㑹攒簇聚也"],["古注·《御选唐诗》","夏小正三月燕来降古诗思为双飞燕𠼫泥巢君屋傅休奕赋燕𠼫泥於广庭杜甫诗燕子𠼫泥两度新皇甫冉檐燕诗拂水竞何忙"],["古注·《御选唐诗》","孔融书嵗月不居时节如流古诗白露沾野草时节忽复易张九龄诗年催华髪新刘李威诗翩翩终不住"],["古注·《御选唐诗》","陶潜桃花源记晋太康中武陵人捕鱼为业缘溪行忘路之逺近忽逢桃花林夹岸数百歩中无杂树芳草鲜美落英缤纷渔人甚异之郑愔诗别访武陵花乔知之诗茎枯花谢枝憔悴"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《御选唐诗》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/御選唐詩_(四庫全書本)）"]],"open_21499":["华岳寺","元稹","七言律诗","约805前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["山前古寺临长道，来往淹留爲爱山。","双燕营巢始西别，百花成子又东还。","暝驱羸马频看堠，晓听鸣鸡欲度关。","羞见窦师无外役，竹窗依旧老身闲。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]]};